import React from 'react';
import { Player, Currency } from '../types';
import { PLAYER_COLORS, PLAYER_BORDER_COLORS } from '../constants';
import { ThemeColor } from '../types';

interface PlayerCardProps {
  player: Player;
  currency: Currency;
  onEditName: (name: string) => void;
  onDragStart: (e: React.PointerEvent, id: string) => void;
  style?: React.CSSProperties;
  className?: string;
}

const PlayerCard: React.FC<PlayerCardProps> = ({ 
  player, 
  currency, 
  onEditName, 
  onDragStart, 
  style, 
  className = '' 
}) => {
  const colorKey = player.color as ThemeColor;

  const borderColor = PLAYER_BORDER_COLORS[colorKey] || 'border-slate-500';
  const glowColor = PLAYER_COLORS[colorKey] || 'bg-slate-500';

  const formatMoney = (amount: number) => {
    // Shorten large numbers
    let displayVal = amount.toLocaleString();
    if (Math.abs(amount) >= 10000000) displayVal = `${(amount/1000000).toFixed(1)}M`;
    else if (Math.abs(amount) >= 10000) displayVal = `${(amount/1000).toFixed(1)}k`;

    return currency.position === 'prefix' 
      ? `${currency.symbol}${displayVal}`
      : `${displayVal}${currency.symbol}`;
  };

  return (
    <div 
      className={`absolute flex flex-col items-center touch-none select-none group cursor-grab active:cursor-grabbing ${className}`}
      style={{
        ...style,
        transform: 'translate(-50%, -50%)', // Ensure (x,y) is the exact center
        width: 'max-content'
      }}
      onPointerDown={(e) => onDragStart(e, player.id)}
      data-id={player.id}
    >
      {/* Avatar Circle - Doubled dimensions */}
      <div 
        className={`relative w-32 h-32 md:w-48 md:h-48 rounded-full border-[6px] md:border-[10px] ${borderColor} shadow-[0_0_30px_rgba(0,0,0,0.7)] transition-all duration-300 hover:scale-105 active:scale-95 z-20 flex items-center justify-center bg-gradient-to-b from-slate-700 to-slate-900`}
      >
        {/* Inner Glow/Highlight */}
        <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-white/10 to-transparent pointer-events-none"></div>

        {/* External Glow behind (hover) */}
        <div className={`absolute -inset-2 rounded-full opacity-0 group-hover:opacity-60 blur-xl transition-opacity duration-300 ${glowColor}`}></div>

        {/* Doubled emoji size */}
        <span className="text-6xl md:text-[6rem] relative z-10 filter drop-shadow-lg select-none leading-none transform group-hover:rotate-6 transition-transform">
          {player.avatar}
        </span>

        {player.isBankrupt && (
          <div className="absolute inset-0 bg-black/80 rounded-full flex items-center justify-center z-30 border-4 border-red-600">
            <span className="text-5xl md:text-7xl">💀</span>
          </div>
        )}
      </div>

      {/* Info Pill - Increased scaling for readability with larger icon */}
      <div className="mt-4 flex flex-col items-center z-30 filter drop-shadow-xl scale-150 md:scale-[1.8] origin-top">
        <input
          value={player.name}
          onChange={(e) => onEditName(e.target.value)}
          onClick={(e) => e.stopPropagation()} 
          className="bg-slate-900/80 backdrop-blur-md rounded-t-lg px-2 py-0.5 text-[10px] md:text-xs text-white font-bold text-center w-20 md:w-24 outline-none border-b border-white/10 focus:bg-black/90 focus:text-cyan-400 transition-colors truncate shadow-sm"
        />
        <div className={`bg-slate-800/95 backdrop-blur-md border border-t-0 border-white/10 rounded-b-lg px-2 py-0.5 min-w-[5rem] md:min-w-[6rem] text-center shadow-md ${player.balance < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
          <span className="text-xs md:text-sm font-black font-mono tracking-tight">
            {formatMoney(player.balance)}
          </span>
        </div>
      </div>
    </div>
  );
};

