export default BankCard;

import React, { useState, useEffect, useRef } from 'react';
import { Player, Transaction, TransactionType, ThemeColor, Currency, GameSettings } from './types';
import { DEFAULT_STARTING_BALANCE, DEFAULT_PASS_GO_AMOUNT, PLAYER_COLORS, CURRENCIES, AVATARS } from './constants';
import PlayerCard from './components/PlayerCard';
import BankCard from './components/BankCard';
import TransactionModal from './components/TransactionModal';
import HistoryLogModal from './components/HistoryLogModal';
import RulesBot from './components/RulesBot';
import Button from './components/Button';
import PlayerFormModal from './components/PlayerFormModal';
import AnalysisModal from './components/AnalysisModal';

const generateId = () => Math.random().toString(36).substr(2, 9);

const App: React.FC = () => {
  // --- State ---

  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [gameSettings, setGameSettings] = useState<GameSettings>({
    startingBalance: DEFAULT_STARTING_BALANCE,
    passGoAmount: DEFAULT_PASS_GO_AMOUNT
  });

  const [players, setPlayers] = useState<Player[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [gameStarted, setGameStarted] = useState(false);

  const [modalState, setModalState] = useState<{
    isOpen: boolean;
    initialFromId?: string;
    initialToId?: string;
  }>({ isOpen: false });

  const [isRulesOpen, setIsRulesOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isAnalysisOpen, setIsAnalysisOpen] = useState(false);
  const [playerFormState, setPlayerFormState] = useState<{
    isOpen: boolean;
    playerToEdit?: Player;
  }>({ isOpen: false });

  const [dragVisual, setDragVisual] = useState<{
    isDragging: boolean;
    startX: number;
    startY: number;
    currX: number;
    currY: number;
  }>({
    isDragging: false,
    startX: 0,
    startY: 0,
    currX: 0,
    currY: 0,
  });

  const dragRef = useRef<{
    isDragging: boolean;
    sourceId: string | null;
    startX: number;
    startY: number;
    hasMoved: boolean;
  }>({
    isDragging: false,
    sourceId: null,
    startX: 0,
    startY: 0,
    hasMoved: false
  });

  const boardRef = useRef<HTMLDivElement>(null);
  const [playerPositions, setPlayerPositions] = useState<{ [key: string]: { x: number, y: number } }>({});

  // --- Persistence ---

  useEffect(() => {
    const savedGame = localStorage.getItem('bankair_state_v1');
    if (savedGame) {
      try {
        const parsed = JSON.parse(savedGame);
        setPlayers(parsed.players || []);
        setTransactions(parsed.transactions || []);
        setGameStarted(parsed.gameStarted || false);
        setCurrency(parsed.currency || CURRENCIES[0]);
        setGameSettings(parsed.settings || { startingBalance: DEFAULT_STARTING_BALANCE, passGoAmount: DEFAULT_PASS_GO_AMOUNT });
      } catch (e) {
        console.error("Failed to load save", e);
      }
    }
  }, []);

  useEffect(() => {
    const stateToSave = {
      players,
      transactions,
      gameStarted,
      currency,
      settings: gameSettings
    };
    localStorage.setItem('bankair_state_v1', JSON.stringify(stateToSave));
  }, [players, transactions, gameStarted, currency, gameSettings]);

  // --- Logic ---

  const formatMoney = (val: number) => val.toLocaleString();

  const parseMoneyInput = (val: string) => {
    const clean = val.replace(/,/g, '').replace(/[^0-9]/g, '');
    return clean ? parseInt(clean) : 0;
  };

  const handleStartGame = () => {
    if (players.length < 2) return;
    const resetPlayers = players.map(p => ({
      ...p,
      balance: gameSettings.startingBalance,
      isBankrupt: false
    }));
    setPlayers(resetPlayers);
    setTransactions([]);
    setGameStarted(true);
  };

  const handleEndGame = () => {
    if (window.confirm("End current game and return to setup? Players will be preserved.")) {
      setGameStarted(false);
    }
  };

  const handleAddPlayer = () => {
    if (players.length >= 6) return;
    const count = players.length + 1;
    const randomAvatar = AVATARS[Math.floor(Math.random() * AVATARS.length)];
    const colorKeys = Object.keys(PLAYER_COLORS) as ThemeColor[];
    const randomColor = colorKeys[Math.floor(Math.random() * colorKeys.length)];

    const newPlayer: Player = {
      id: generateId(),
      name: `Player ${count}`,
      avatar: randomAvatar,
      balance: gameStarted ? gameSettings.startingBalance : 0,
      color: randomColor,
      isBankrupt: false
    };
    setPlayers([...players, newPlayer]);
  };

  const handleUpdatePlayerName = (id: string, name: string) => {
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const handleUpdatePlayerAppearance = (data: Partial<Player>) => {
    const editId = playerFormState.playerToEdit?.id;
    if (editId) {
      setPlayers(prev => prev.map(p => 
        p.id === editId ? { ...p, ...data } : p
      ));
    }
  };

  // --- Transactions ---

  const handleTransaction = (type: TransactionType, fromId: string, toId: string, amount: number) => {
    const newTx: Transaction = {
      id: generateId(),
      timestamp: Date.now(),
      type,
      fromId,
      toId,
      amount,
      isReverted: false
    };

    setTransactions(prev => [...prev, newTx]);
    applyTransactionEffect(newTx, false);
  };

  const handleToggleTransaction = (id: string) => {
    const txIndex = transactions.findIndex(t => t.id === id);
    if (txIndex === -1) return;

    const tx = transactions[txIndex];
    const isReverting = !tx.isReverted;

    const updatedTransactions = [...transactions];
    updatedTransactions[txIndex] = { ...tx, isReverted: isReverting };
    setTransactions(updatedTransactions);

    applyTransactionEffect(tx, isReverting);
  };

  const applyTransactionEffect = (tx: Transaction, isReversing: boolean) => {
    const { fromId, toId, amount } = tx;

    setPlayers(prevPlayers => prevPlayers.map(p => {
      let newBalance = p.balance;
      if (p.id === fromId) {
        newBalance = isReversing ? p.balance + amount : p.balance - amount;
      }
      if (p.id === toId) {
        newBalance = isReversing ? p.balance - amount : p.balance + amount;
      }
      return { ...p, balance: newBalance };
    }));
  };

  // --- Advanced Layout Calculation ---

  useEffect(() => {
    if (!gameStarted || !boardRef.current) return;

    const updatePositions = () => {
      if (!boardRef.current) return;

      const { width, height } = boardRef.current.getBoundingClientRect();
      if (width === 0 || height === 0) {
        requestAnimationFrame(updatePositions);
        return;
      }

      const cx = width / 2;
      const cy = height / 2;

      const isMobile = width < 768;

      // Dynamic padding to keep large icons inside the viewport
      const paddingX = isMobile ? 80 : 150;
      const paddingY = isMobile ? 120 : 150;

      // Elliptical layout: wider X-radius on landscape to spread players
      const rx = (width / 2) - paddingX;
      const ry = (height / 2) - paddingY;

      if (rx <= 50 || ry <= 50) return;

      const newPositions: { [key: string]: { x: number, y: number } } = {};

      players.forEach((player, index) => {
        // Start at top (-90deg)
        const angle = (index / players.length) * 2 * Math.PI - (Math.PI / 2); 
        newPositions[player.id] = {
          x: cx + rx * Math.cos(angle),
          y: cy + ry * Math.sin(angle)
        };
      });

      setPlayerPositions(newPositions);
    };

    const timer = setTimeout(updatePositions, 100);
    const observer = new ResizeObserver(() => requestAnimationFrame(updatePositions));
    observer.observe(boardRef.current);

    return () => {
      clearTimeout(timer);
      observer.disconnect();
    };
  }, [players.length, gameStarted]);

  // --- Drag & Drop ---

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return;
    const clientX = e.clientX;
    const clientY = e.clientY;

    dragRef.current = {
      isDragging: true,
      sourceId: id,
      startX: clientX,
      startY: clientY,
      hasMoved: false
    };

    setDragVisual({
      isDragging: true,
      startX: clientX,
      startY: clientY,
      currX: clientX,
      currY: clientY
    });

    try {
      (e.target as Element).setPointerCapture(e.pointerId);
    } catch (err) { }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!dragRef.current.isDragging) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;
    if (Math.abs(dx) > 10 || Math.abs(dy) > 10) {
      dragRef.current.hasMoved = true;
    }
    setDragVisual(prev => ({ ...prev, currX: e.clientX, currY: e.clientY }));
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (!dragRef.current.isDragging) return;
    const { sourceId, hasMoved } = dragRef.current;

    if (!hasMoved && sourceId) {
      if (sourceId === 'BANK') {
        setIsHistoryOpen(true);
      } else {
        const player = players.find(p => p.id === sourceId);
        if (player) setPlayerFormState({ isOpen: true, playerToEdit: player });
      }
    } 
    else if (hasMoved && sourceId) {
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-id'));
      const targetId = targetElement?.getAttribute('data-id');

      if (targetId && targetId !== sourceId) {
        setModalState({ isOpen: true, initialFromId: sourceId, initialToId: targetId });
      }
    }

    dragRef.current = { isDragging: false, sourceId: null, startX: 0, startY: 0, hasMoved: false };
    setDragVisual(prev => ({ ...prev, isDragging: false }));
    try {
      (e.target as Element).releasePointerCapture(e.pointerId);
    } catch (err) { }
  };


  // --- Render ---

  if (!gameStarted) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 flex flex-col items-center p-4 md:p-8 font-sans text-slate-100 overflow-y-auto">
        <div className="w-full max-w-2xl space-y-8">

          <div className="text-center space-y-2">
            <h1 className="text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-600 drop-shadow-lg tracking-tighter">
              BankAIr
            </h1>
            <p className="text-slate-400 text-lg">The AI-Powered Monopoly Banker</p>
          </div>

          <div className="glass-panel rounded-3xl p-6 md:p-8 shadow-2xl space-y-6">
            <div className="flex items-center gap-3 border-b border-white/10 pb-4">
              <span className="text-2xl">⚙️</span>
              <h2 className="text-xl font-bold text-white">Set up</h2>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Starting Balance</label>
                <div className="relative">
                  <span className="absolute left-4 top-3 text-slate-400">{currency.position === 'prefix' ? currency.symbol : ''}</span>
                  <input 
                    type="text" 
                    value={formatMoney(gameSettings.startingBalance)}
                    onChange={(e) => setGameSettings({...gameSettings, startingBalance: parseMoneyInput(e.target.value)})}
                    className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-10 text-white font-mono focus:ring-2 focus:ring-cyan-500 outline-none transition-all"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Pass Go Amount</label>
                <div className="relative">
                  <span className="absolute left-4 top-3 text-slate-400">{currency.position === 'prefix' ? currency.symbol : ''}</span>
                  <input 
                    type="text" 
                    value={formatMoney(gameSettings.passGoAmount)}
                    onChange={(e) => setGameSettings({...gameSettings, passGoAmount: parseMoneyInput(e.target.value)})}
                    className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-10 text-white font-mono focus:ring-2 focus:ring-cyan-500 outline-none transition-all"
                  />
                </div>
              </div>

               <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Currency</label>
                <select 
                  value={currency.symbol}
                  onChange={(e) => setCurrency(CURRENCIES.find(c => c.symbol === e.target.value) || CURRENCIES[0])}
                  className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-4 text-white focus:ring-2 focus:ring-cyan-500 outline-none appearance-none"
                >
                  {CURRENCIES.map(c => <option key={c.symbol} value={c.symbol}>{c.name}</option>)}
                </select>
              </div>
            </div>
          </div>

          <div className="glass-panel rounded-3xl p-6 md:p-8 shadow-2xl space-y-6">
            <div className="flex items-center justify-between border-b border-white/10 pb-4">
               <div className="flex items-center gap-3">
                <span className="text-2xl">👥</span>
                <h2 className="text-xl font-bold text-white">Players ({players.length}/6)</h2>
              </div>
               <button 
                onClick={handleAddPlayer}
                disabled={players.length >= 6}
                className="bg-white/10 hover:bg-white/20 text-white p-2 rounded-lg transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
              </button>
            </div>

            <div className="space-y-3">
              {players.map((player) => (
                <div key={player.id} className="flex items-center gap-3 bg-white/5 p-3 rounded-xl border border-white/5 hover:bg-white/10 transition-colors">
                  <button 
                    onClick={() => setPlayerFormState({ isOpen: true, playerToEdit: player })}
                    className="text-3xl hover:scale-110 transition-transform"
                  >
                    {player.avatar}
                  </button>
                  <div className="flex-1">
                     <input
                      type="text"
                      value={player.name}
                      onChange={(e) => handleUpdatePlayerName(player.id, e.target.value)}
                      className="bg-transparent text-white font-bold w-full outline-none border-b border-transparent focus:border-cyan-400"
                    />
                  </div>
                </div>
              ))}
              {players.length === 0 && <div className="text-center text-slate-500 py-4 italic">No players added.</div>}
            </div>
          </div>

          <Button fullWidth size="lg" onClick={handleStartGame} disabled={players.length < 2} className="!bg-gradient-to-r !from-cyan-500 !to-blue-600 !py-4 !text-xl !shadow-xl">
            Start Game 🚀
          </Button>
        </div>

        <PlayerFormModal 
          isOpen={playerFormState.isOpen}
          onClose={() => setPlayerFormState({ isOpen: false, playerToEdit: undefined })}
          initialData={playerFormState.playerToEdit}
          onSave={handleUpdatePlayerAppearance}
        />
      </div>
    );
  }

  return (
    <div 
      className="fixed inset-0 bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 overflow-hidden font-sans text-slate-100 touch-none"
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onContextMenu={(e) => e.preventDefault()}
    >
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-blue-900/20 via-transparent to-transparent pointer-events-none"></div>

      {/* HUD Header */}
      <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-start z-40 pointer-events-none">
        <div className="flex gap-2 pointer-events-auto">
          <button onClick={handleEndGame} className="bg-white/10 hover:bg-red-500/20 text-slate-400 p-2 rounded-lg backdrop-blur-md border border-white/5 shadow-lg">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>

          {players.length < 6 && (
             <button onClick={handleAddPlayer} className="bg-white/10 hover:bg-cyan-500/20 text-slate-400 p-2 rounded-lg backdrop-blur-md border border-white/5">
               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
               </svg>
             </button>
          )}
        </div>

        <div className="flex gap-2 pointer-events-auto">
          <button onClick={() => setIsAnalysisOpen(true)} className="bg-purple-600 text-white p-2 rounded-lg shadow-lg"><span className="text-xl">🔮</span></button>
          <button onClick={() => setIsRulesOpen(true)} className="bg-white/10 text-slate-400 p-2 rounded-lg shadow-lg"><span className="text-xl">⚖️</span></button>
          <button onClick={() => setIsHistoryOpen(true)} className="bg-white/10 text-slate-400 p-2 rounded-lg shadow-lg"><span className="text-xl">📜</span></button>
        </div>
      </div>

      {/* Board Layout */}
      <div ref={boardRef} className="absolute inset-0 z-0">
        <BankCard currency={currency} onDragStart={handlePointerDown} />

        {players.map((player) => (
          <PlayerCard 
            key={player.id}
            player={player}
            currency={currency}
            onEditName={handleUpdatePlayerName}
            onDragStart={handlePointerDown}
            style={{
              left: playerPositions[player.id]?.x || '50%',
              top: playerPositions[player.id]?.y || '50%',
              opacity: playerPositions[player.id] ? 1 : 0, 
              visibility: playerPositions[player.id] ? 'visible' : 'hidden',
              transition: 'opacity 0.4s ease-out, left 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), top 0.5s cubic-bezier(0.2, 0.8, 0.2, 1)'
            }}
          />
        ))}
      </div>

      {/* Drag Visuals */}
      {dragVisual.isDragging && (
        <div className="absolute inset-0 pointer-events-none z-50">
          <svg className="w-full h-full drop-shadow-[0_0_8px_rgba(34,211,238,0.8)]">
            <line 
              x1={dragVisual.startX} y1={dragVisual.startY} 
              x2={dragVisual.currX} y2={dragVisual.currY} 
              stroke="url(#gradient-line)" strokeWidth="6" strokeLinecap="round" className="opacity-80"
            />
             <defs>
              <linearGradient id="gradient-line" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#22d3ee" />
                <stop offset="100%" stopColor="#a855f7" />
              </linearGradient>
            </defs>
          </svg>
          <div 
            className="absolute w-8 h-8 rounded-full bg-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.8)] border-2 border-white transform -translate-x-1/2 -translate-y-1/2"
            style={{ left: dragVisual.currX, top: dragVisual.currY }}
          ></div>
        </div>
      )}

      {/* Modals */}
      <TransactionModal 
        isOpen={modalState.isOpen}
        initialFromId={modalState.initialFromId}
        initialToId={modalState.initialToId}
        onClose={() => setModalState({ isOpen: false })}
        players={players}
        currency={currency}
        passGoAmount={gameSettings.passGoAmount}
        onTransaction={handleTransaction}
      />

      <HistoryLogModal 
        isOpen={isHistoryOpen}
        onClose={() => setIsHistoryOpen(false)}
        transactions={transactions}
        players={players}
        currency={currency}
        onToggleTransaction={handleToggleTransaction}
      />

      <RulesBot isOpen={isRulesOpen} onClose={() => setIsRulesOpen(false)} />
      <AnalysisModal isOpen={isAnalysisOpen} onClose={() => setIsAnalysisOpen(false)} players={players} />
      <PlayerFormModal 
        isOpen={playerFormState.isOpen}
        onClose={() => setPlayerFormState({ isOpen: false, playerToEdit: undefined })}
        initialData={playerFormState.playerToEdit}
        onSave={handleUpdatePlayerAppearance}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Player, Transaction, TransactionType, ThemeColor, Currency, GameSettings } from './types';
import { DEFAULT_STARTING_BALANCE, DEFAULT_PASS_GO_AMOUNT, PLAYER_COLORS, CURRENCIES, AVATARS } from './constants';
import PlayerCard from './components/PlayerCard';
import BankCard from './components/BankCard';
import TransactionModal from './components/TransactionModal';
import HistoryLogModal from './components/HistoryLogModal';
import RulesBot from './components/RulesBot';
import Button from './components/Button';
import PlayerFormModal from './components/PlayerFormModal';
import AnalysisModal from './components/AnalysisModal';

const generateId = () => Math.random().toString(36).substr(2, 9);

const App: React.FC = () => {
  // --- State ---

  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [gameSettings, setGameSettings] = useState<GameSettings>({
    startingBalance: DEFAULT_STARTING_BALANCE,
    passGoAmount: DEFAULT_PASS_GO_AMOUNT
  });

  const [players, setPlayers] = useState<Player[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [gameStarted, setGameStarted] = useState(false);

  const [modalState, setModalState] = useState<{
    isOpen: boolean;
    initialFromId?: string;
    initialToId?: string;
  }>({ isOpen: false });

  const [isRulesOpen, setIsRulesOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isAnalysisOpen, setIsAnalysisOpen] = useState(false);
  const [playerFormState, setPlayerFormState] = useState<{
    isOpen: boolean;
    playerToEdit?: Player;
  }>({ isOpen: false });

  const [dragVisual, setDragVisual] = useState<{
    isDragging: boolean;
    startX: number;
    startY: number;
    currX: number;
    currY: number;
  }>({
    isDragging: false,
    startX: 0,
    startY: 0,
    currX: 0,
    currY: 0,
  });

  const dragRef = useRef<{
    isDragging: boolean;
    sourceId: string | null;
    startX: number;
    startY: number;
    hasMoved: boolean;
  }>({
    isDragging: false,
    sourceId: null,
    startX: 0,
    startY: 0,
    hasMoved: false
  });

  const boardRef = useRef<HTMLDivElement>(null);
  const [playerPositions, setPlayerPositions] = useState<{ [key: string]: { x: number, y: number } }>({});

  // --- Persistence ---

  useEffect(() => {
    const savedGame = localStorage.getItem('bankair_state_v1');
    if (savedGame) {
      try {
        const parsed = JSON.parse(savedGame);
        setPlayers(parsed.players || []);
        setTransactions(parsed.transactions || []);
        setGameStarted(parsed.gameStarted || false);
        setCurrency(parsed.currency || CURRENCIES[0]);
        setGameSettings(parsed.settings || { startingBalance: DEFAULT_STARTING_BALANCE, passGoAmount: DEFAULT_PASS_GO_AMOUNT });
      } catch (e) {
        console.error("Failed to load save", e);
      }
    }
  }, []);

  useEffect(() => {
    const stateToSave = {
      players,
      transactions,
      gameStarted,
      currency,
      settings: gameSettings
    };
    localStorage.setItem('bankair_state_v1', JSON.stringify(stateToSave));
  }, [players, transactions, gameStarted, currency, gameSettings]);

  // --- Logic ---

  const formatMoney = (val: number) => val.toLocaleString();

  const parseMoneyInput = (val: string) => {
    const clean = val.replace(/,/g, '').replace(/[^0-9]/g, '');
    return clean ? parseInt(clean) : 0;
  };

  const handleStartGame = () => {
    if (players.length < 2) return;
    const resetPlayers = players.map(p => ({
      ...p,
      balance: gameSettings.startingBalance,
      isBankrupt: false
    }));
    setPlayers(resetPlayers);
    setTransactions([]);
    setGameStarted(true);
  };

  const handleEndGame = () => {
    if (window.confirm("End current game and return to setup? Players will be preserved.")) {
      setGameStarted(false);
    }
  };

  const handleAddPlayer = () => {
    if (players.length >= 6) return;
    const count = players.length + 1;
    const randomAvatar = AVATARS[Math.floor(Math.random() * AVATARS.length)];
    const colorKeys = Object.keys(PLAYER_COLORS) as ThemeColor[];
    const randomColor = colorKeys[Math.floor(Math.random() * colorKeys.length)];

    const newPlayer: Player = {
      id: generateId(),
      name: `Player ${count}`,
      avatar: randomAvatar,
      balance: gameStarted ? gameSettings.startingBalance : 0,
      color: randomColor,
      isBankrupt: false
    };
    setPlayers([...players, newPlayer]);
  };

  const handleUpdatePlayerName = (id: string, name: string) => {
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const handleUpdatePlayerAppearance = (data: Partial<Player>) => {
    const editId = playerFormState.playerToEdit?.id;
    if (editId) {
      setPlayers(prev => prev.map(p => 
        p.id === editId ? { ...p, ...data } : p
      ));
    }
  };

  // --- Transactions ---

  const handleTransaction = (type: TransactionType, fromId: string, toId: string, amount: number) => {
    const newTx: Transaction = {
      id: generateId(),
      timestamp: Date.now(),
      type,
      fromId,
      toId,
      amount,
      isReverted: false
    };

    setTransactions(prev => [...prev, newTx]);
    applyTransactionEffect(newTx, false);
  };

  const handleToggleTransaction = (id: string) => {
    const txIndex = transactions.findIndex(t => t.id === id);
    if (txIndex === -1) return;

    const tx = transactions[txIndex];
    const isReverting = !tx.isReverted;

    const updatedTransactions = [...transactions];
    updatedTransactions[txIndex] = { ...tx, isReverted: isReverting };
    setTransactions(updatedTransactions);

    applyTransactionEffect(tx, isReverting);
  };

  const applyTransactionEffect = (tx: Transaction, isReversing: boolean) => {
    const { fromId, toId, amount } = tx;

    setPlayers(prevPlayers => prevPlayers.map(p => {
      let newBalance = p.balance;
      if (p.id === fromId) {
        newBalance = isReversing ? p.balance + amount : p.balance - amount;
      }
      if (p.id === toId) {
        newBalance = isReversing ? p.balance - amount : p.balance + amount;
      }
      return { ...p, balance: newBalance };
    }));
  };

  // --- Advanced Layout Calculation ---

  useEffect(() => {
    if (!gameStarted || !boardRef.current) return;

    const updatePositions = () => {
      if (!boardRef.current) return;

      const { width, height } = boardRef.current.getBoundingClientRect();
      if (width === 0 || height === 0) {
        requestAnimationFrame(updatePositions);
        return;
      }

      const cx = width / 2;
      const cy = height / 2;

      const isMobile = width < 768;

      // Dynamic padding for large icons. 
      // X padding is increased on desktop to keep icons away from side edges.
      const paddingX = isMobile ? 85 : 180;
      const paddingY = isMobile ? 130 : 180;

      const rx = (width / 2) - paddingX;
      const ry = (height / 2) - paddingY;

      if (rx <= 20 || ry <= 20) return;

      const newPositions: { [key: string]: { x: number, y: number } } = {};
      const numPlayers = players.length;

      // START ANGLE ADJUSTMENT
      // For 4 players, shift by 45deg (Math.PI/4) to put them in corners instead of cross shape.
      // For others, use top center (-90deg).
      const startAngle = numPlayers === 4 ? -Math.PI / 4 : -Math.PI / 2;

      players.forEach((player, index) => {
        const angle = (index / numPlayers) * 2 * Math.PI + startAngle; 
        newPositions[player.id] = {
          x: cx + rx * Math.cos(angle),
          y: cy + ry * Math.sin(angle)
        };
      });

      setPlayerPositions(newPositions);
    };

    const timer = setTimeout(updatePositions, 100);
    const observer = new ResizeObserver(() => requestAnimationFrame(updatePositions));
    observer.observe(boardRef.current);

    return () => {
      clearTimeout(timer);
      observer.disconnect();
    };
  }, [players.length, gameStarted]);

  // --- Drag & Drop ---

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return;
    const clientX = e.clientX;
    const clientY = e.clientY;

    dragRef.current = {
      isDragging: true,
      sourceId: id,
      startX: clientX,
      startY: clientY,
      hasMoved: false
    };

    setDragVisual({
      isDragging: true,
      startX: clientX,
      startY: clientY,
      currX: clientX,
      currY: clientY
    });

    try {
      (e.target as Element).setPointerCapture(e.pointerId);
    } catch (err) { }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!dragRef.current.isDragging) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;
    if (Math.abs(dx) > 10 || Math.abs(dy) > 10) {
      dragRef.current.hasMoved = true;
    }
    setDragVisual(prev => ({ ...prev, currX: e.clientX, currY: e.clientY }));
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    if (!dragRef.current.isDragging) return;
    const { sourceId, hasMoved } = dragRef.current;

    if (!hasMoved && sourceId) {
      if (sourceId === 'BANK') {
        setIsHistoryOpen(true);
      } else {
        const player = players.find(p => p.id === sourceId);
        if (player) setPlayerFormState({ isOpen: true, playerToEdit: player });
      }
    } 
    else if (hasMoved && sourceId) {
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-id'));
      const targetId = targetElement?.getAttribute('data-id');

      if (targetId && targetId !== sourceId) {
        setModalState({ isOpen: true, initialFromId: sourceId, initialToId: targetId });
      }
    }

    dragRef.current = { isDragging: false, sourceId: null, startX: 0, startY: 0, hasMoved: false };
    setDragVisual(prev => ({ ...prev, isDragging: false }));
    try {
      (e.target as Element).releasePointerCapture(e.pointerId);
    } catch (err) { }
  };


  // --- Render ---

  if (!gameStarted) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 flex flex-col items-center p-4 md:p-8 font-sans text-slate-100 overflow-y-auto">
        <div className="w-full max-w-2xl space-y-8">

          <div className="text-center space-y-2">
            <h1 className="text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-600 drop-shadow-lg tracking-tighter">
              BankAIr
            </h1>
            <p className="text-slate-400 text-lg">The AI-Powered Monopoly Banker</p>
          </div>

          <div className="glass-panel rounded-3xl p-6 md:p-8 shadow-2xl space-y-6">
            <div className="flex items-center gap-3 border-b border-white/10 pb-4">
              <span className="text-2xl">⚙️</span>
              <h2 className="text-xl font-bold text-white">Set up</h2>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Starting Balance</label>
                <div className="relative">
                  <span className="absolute left-4 top-3 text-slate-400">{currency.position === 'prefix' ? currency.symbol : ''}</span>
                  <input 
                    type="text" 
                    value={formatMoney(gameSettings.startingBalance)}
                    onChange={(e) => setGameSettings({...gameSettings, startingBalance: parseMoneyInput(e.target.value)})}
                    className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-10 text-white font-mono focus:ring-2 focus:ring-cyan-500 outline-none transition-all"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Pass Go Amount</label>
                <div className="relative">
                  <span className="absolute left-4 top-3 text-slate-400">{currency.position === 'prefix' ? currency.symbol : ''}</span>
                  <input 
                    type="text" 
                    value={formatMoney(gameSettings.passGoAmount)}
                    onChange={(e) => setGameSettings({...gameSettings, passGoAmount: parseMoneyInput(e.target.value)})}
                    className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-10 text-white font-mono focus:ring-2 focus:ring-cyan-500 outline-none transition-all"
                  />
                </div>
              </div>

               <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Currency</label>
                <select 
                  value={currency.symbol}
                  onChange={(e) => setCurrency(CURRENCIES.find(c => c.symbol === e.target.value) || CURRENCIES[0])}
                  className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-4 text-white focus:ring-2 focus:ring-cyan-500 outline-none appearance-none"
                >
                  {CURRENCIES.map(c => <option key={c.symbol} value={c.symbol}>{c.name}</option>)}
                </select>
              </div>
            </div>
          </div>

          <div className="glass-panel rounded-3xl p-6 md:p-8 shadow-2xl space-y-6">
            <div className="flex items-center justify-between border-b border-white/10 pb-4">
               <div className="flex items-center gap-3">
                <span className="text-2xl">👥</span>
                <h2 className="text-xl font-bold text-white">Players ({players.length}/6)</h2>
              </div>
               <button 
                onClick={handleAddPlayer}
                disabled={players.length >= 6}
                className="bg-white/10 hover:bg-white/20 text-white p-2 rounded-lg transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
              </button>
            </div>

            <div className="space-y-3">
              {players.map((player) => (
                <div key={player.id} className="flex items-center gap-3 bg-white/5 p-3 rounded-xl border border-white/5 hover:bg-white/10 transition-colors">
                  <button 
                    onClick={() => setPlayerFormState({ isOpen: true, playerToEdit: player })}
                    className="text-3xl hover:scale-110 transition-transform"
                  >
                    {player.avatar}
                  </button>
                  <div className="flex-1">
                     <input
                      type="text"
                      value={player.name}
                      onChange={(e) => handleUpdatePlayerName(player.id, e.target.value)}
                      className="bg-transparent text-white font-bold w-full outline-none border-b border-transparent focus:border-cyan-400"
                    />
                  </div>
                </div>
              ))}
              {players.length === 0 && <div className="text-center text-slate-500 py-4 italic">No players added.</div>}
            </div>
          </div>

          <Button fullWidth size="lg" onClick={handleStartGame} disabled={players.length < 2} className="!bg-gradient-to-r !from-cyan-500 !to-blue-600 !py-4 !text-xl !shadow-xl">
            Start Game 🚀
          </Button>
        </div>

        <PlayerFormModal 
          isOpen={playerFormState.isOpen}
          onClose={() => setPlayerFormState({ isOpen: false, playerToEdit: undefined })}
          initialData={playerFormState.playerToEdit}
          onSave={handleUpdatePlayerAppearance}
        />
      </div>
    );
  }

  return (
    <div 
      className="fixed inset-0 bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 overflow-hidden font-sans text-slate-100 touch-none"
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onContextMenu={(e) => e.preventDefault()}
    >
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-blue-900/20 via-transparent to-transparent pointer-events-none"></div>

      {/* HUD Header */}
      <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-start z-40 pointer-events-none">
        <div className="flex gap-2 pointer-events-auto">
          <button onClick={handleEndGame} className="bg-white/10 hover:bg-red-500/20 text-slate-400 p-2 rounded-lg backdrop-blur-md border border-white/5 shadow-lg">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>

          {players.length < 6 && (
             <button onClick={handleAddPlayer} className="bg-white/10 hover:bg-cyan-500/20 text-slate-400 p-2 rounded-lg backdrop-blur-md border border-white/5">
               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
               </svg>
             </button>
          )}
        </div>

        <div className="flex gap-2 pointer-events-auto">
          <button onClick={() => setIsAnalysisOpen(true)} className="bg-purple-600 text-white p-2 rounded-lg shadow-lg"><span className="text-xl">🔮</span></button>
          <button onClick={() => setIsRulesOpen(true)} className="bg-white/10 text-slate-400 p-2 rounded-lg shadow-lg"><span className="text-xl">⚖️</span></button>
          <button onClick={() => setIsHistoryOpen(true)} className="bg-white/10 text-slate-400 p-2 rounded-lg shadow-lg"><span className="text-xl">📜</span></button>
        </div>
      </div>

      {/* Board Layout */}
      <div ref={boardRef} className="absolute inset-0 z-0">
        <BankCard currency={currency} onDragStart={handlePointerDown} />

        {players.map((player) => (
          <PlayerCard 
            key={player.id}
            player={player}
            currency={currency}
            onEditName={handleUpdatePlayerName}
            onDragStart={handlePointerDown}
            style={{
              left: playerPositions[player.id]?.x || '50%',
              top: playerPositions[player.id]?.y || '50%',
              opacity: playerPositions[player.id] ? 1 : 0, 
              visibility: playerPositions[player.id] ? 'visible' : 'hidden',
              transition: 'opacity 0.4s ease-out, left 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), top 0.5s cubic-bezier(0.2, 0.8, 0.2, 1)'
            }}
          />
        ))}
      </div>

      {/* Drag Visuals */}
      {dragVisual.isDragging && (
        <div className="absolute inset-0 pointer-events-none z-50">
          <svg className="w-full h-full drop-shadow-[0_0_8px_rgba(34,211,238,0.8)]">
            <line 
              x1={dragVisual.startX} y1={dragVisual.startY} 
              x2={dragVisual.currX} y2={dragVisual.currY} 
              stroke="url(#gradient-line)" strokeWidth="6" strokeLinecap="round" className="opacity-80"
            />
             <defs>
              <linearGradient id="gradient-line" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#22d3ee" />
                <stop offset="100%" stopColor="#a855f7" />
              </linearGradient>
            </defs>
          </svg>
          <div 
            className="absolute w-8 h-8 rounded-full bg-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.8)] border-2 border-white transform -translate-x-1/2 -translate-y-1/2"
            style={{ left: dragVisual.currX, top: dragVisual.currY }}
          ></div>
        </div>
      )}

      {/* Modals */}
      <TransactionModal 
        isOpen={modalState.isOpen}
        initialFromId={modalState.initialFromId}
        initialToId={modalState.initialToId}
        onClose={() => setModalState({ isOpen: false })}
        players={players}
        currency={currency}
        passGoAmount={gameSettings.passGoAmount}
        onTransaction={handleTransaction}
      />

      <HistoryLogModal 
        isOpen={isHistoryOpen}
        onClose={() => setIsHistoryOpen(false)}
        transactions={transactions}
        players={players}
        currency={currency}
        onToggleTransaction={handleToggleTransaction}
      />

      <RulesBot isOpen={isRulesOpen} onClose={() => setIsRulesOpen(false)} />
      <AnalysisModal isOpen={isAnalysisOpen} onClose={() => setIsAnalysisOpen(false)} players={players} />
      <PlayerFormModal 
        isOpen={playerFormState.isOpen}
        onClose={() => setPlayerFormState({ isOpen: false, playerToEdit: undefined })}
        initialData={playerFormState.playerToEdit}
        onSave={handleUpdatePlayerAppearance}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Player, Currency } from '../types';
import { PLAYER_COLORS, PLAYER_BORDER_COLORS } from '../constants';
import { ThemeColor } from '../types';

interface PlayerCardProps {
  player: Player;
  currency: Currency;
  onEditName: (name: string) => void;
  onDragStart: (e: React.PointerEvent, id: string) => void;
  deleteProgress?: number; // 0 to 100
  style?: React.CSSProperties;
  className?: string;
}

const PlayerCard: React.FC<PlayerCardProps> = ({ 
  player, 
  currency, 
  onEditName, 
  onDragStart, 
  deleteProgress = 0,
  style, 
  className = '' 
}) => {
  const colorKey = player.color as ThemeColor;

  const borderColor = PLAYER_BORDER_COLORS[colorKey] || 'border-slate-500';
  const glowColor = PLAYER_COLORS[colorKey] || 'bg-slate-500';

  const formatMoney = (amount: number) => {
    let displayVal = amount.toLocaleString();
    if (Math.abs(amount) >= 10000000) displayVal = `${(amount/1000000).toFixed(1)}M`;
    else if (Math.abs(amount) >= 10000) displayVal = `${(amount/1000).toFixed(1)}k`;

    return currency.position === 'prefix' 
      ? `${currency.symbol}${displayVal}`
      : `${displayVal}${currency.symbol}`;
  };

  const isDeleting = deleteProgress > 0;
  const shakeClass = isDeleting ? (deleteProgress > 50 ? 'animate-shake-intense' : 'animate-shake-gentle') : '';

  return (
    <div 
      className={`absolute flex flex-col items-center touch-none select-none group cursor-grab active:cursor-grabbing ${className} ${shakeClass}`}
      style={{
        ...style,
        transform: 'translate(-50%, -50%)',
        width: 'max-content',
        transition: isDeleting ? 'none' : (style?.transition || 'all 0.4s ease-out')
      }}
      onPointerDown={(e) => onDragStart(e, player.id)}
      data-id={player.id}
    >
      {/* Avatar Circle */}
      <div 
        className={`relative w-28 h-28 md:w-40 md:h-40 rounded-full border-[6px] md:border-[8px] ${borderColor} shadow-[0_0_30px_rgba(0,0,0,0.6)] z-20 flex items-center justify-center bg-gradient-to-b from-slate-700 to-slate-900 overflow-hidden`}
      >
        {/* Progress Ring for Deletion */}
        {isDeleting && (
          <div className="absolute inset-0 z-30 pointer-events-none">
            <svg className="w-full h-full rotate-[-90deg]">
              <circle
                cx="50%"
                cy="50%"
                r="48%"
                fill="transparent"
                stroke="rgba(239, 68, 68, 0.8)"
                strokeWidth="12"
                strokeDasharray="301.6"
                strokeDashoffset={301.6 - (301.6 * deleteProgress) / 100}
                className="transition-all duration-75 ease-linear"
              />
            </svg>
            <div className="absolute inset-0 bg-red-600/20 backdrop-blur-[2px] flex items-center justify-center">
              <span className="text-white font-black text-xs md:text-sm uppercase tracking-tighter drop-shadow-md">Delete?</span>
            </div>
          </div>
        )}

        <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-white/10 to-transparent pointer-events-none"></div>
        <div className={`absolute -inset-2 rounded-full opacity-0 group-hover:opacity-40 blur-xl transition-opacity duration-300 ${glowColor}`}></div>

        <span className="text-5xl md:text-7xl relative z-10 filter drop-shadow-lg select-none leading-none transform group-hover:rotate-6 transition-transform">
          {player.avatar}
        </span>

        {player.isBankrupt && (
          <div className="absolute inset-0 bg-black/80 rounded-full flex items-center justify-center z-40 border-4 border-red-600">
            <span className="text-4xl md:text-6xl">💀</span>
          </div>
        )}
      </div>

      {/* Info Pill */}
      <div className={`mt-3 flex flex-col items-center z-30 filter drop-shadow-xl scale-125 md:scale-150 origin-top transition-opacity ${isDeleting ? 'opacity-30' : 'opacity-100'}`}>
        <input
          value={player.name}
          onChange={(e) => onEditName(e.target.value)}
          onClick={(e) => e.stopPropagation()} 
          className="bg-slate-900/90 backdrop-blur-md rounded-t-lg px-2 py-0.5 text-[10px] md:text-xs text-white font-bold text-center w-20 md:w-24 outline-none border-b border-white/10 focus:bg-black focus:text-cyan-400 transition-colors truncate"
        />
        <div className={`bg-slate-800/95 backdrop-blur-md border border-t-0 border-white/10 rounded-b-lg px-2 py-0.5 min-w-[5rem] md:min-w-[6rem] text-center shadow-md ${player.balance < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
          <span className="text-xs md:text-sm font-black font-mono tracking-tight">
            {formatMoney(player.balance)}
          </span>
        </div>
      </div>

      <style>{`
        @keyframes shake-gentle {
          0%, 100% { transform: translate(-50%, -50%) rotate(0deg); }
          25% { transform: translate(-50.5%, -50%) rotate(-1deg); }
          75% { transform: translate(-49.5%, -50%) rotate(1deg); }
        }
        @keyframes shake-intense {
          0%, 100% { transform: translate(-50%, -50%) rotate(0deg); }
          20% { transform: translate(-51%, -49%) rotate(-2deg); }
          40% { transform: translate(-49%, -51%) rotate(2deg); }
          60% { transform: translate(-51%, -51%) rotate(-2deg); }
          80% { transform: translate(-49%, -49%) rotate(2deg); }
        }
        .animate-shake-gentle { animation: shake-gentle 0.2s infinite; }
        .animate-shake-intense { animation: shake-intense 0.15s infinite; }
      `}</style>
    </div>
  );
};

export default PlayerCard;

import React, { useState, useEffect, useRef } from 'react';
import { Player, Transaction, TransactionType, ThemeColor, Currency, GameSettings } from './types';
import { DEFAULT_STARTING_BALANCE, DEFAULT_PASS_GO_AMOUNT, PLAYER_COLORS, CURRENCIES, AVATARS } from './constants';
import PlayerCard from './components/PlayerCard';
import BankCard from './components/BankCard';
import TransactionModal from './components/TransactionModal';
import HistoryLogModal from './components/HistoryLogModal';
import RulesBot from './components/RulesBot';
import Button from './components/Button';
import PlayerFormModal from './components/PlayerFormModal';
import AnalysisModal from './components/AnalysisModal';

const generateId = () => Math.random().toString(36).substr(2, 9);
const DELETE_THRESHOLD_MS = 1000;

const App: React.FC = () => {
  // --- State ---

  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [gameSettings, setGameSettings] = useState<GameSettings>({
    startingBalance: DEFAULT_STARTING_BALANCE,
    passGoAmount: DEFAULT_PASS_GO_AMOUNT
  });

  const [players, setPlayers] = useState<Player[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [gameStarted, setGameStarted] = useState(false);

  const [modalState, setModalState] = useState<{
    isOpen: boolean;
    initialFromId?: string;
    initialToId?: string;
  }>({ isOpen: false });

  const [isRulesOpen, setIsRulesOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isAnalysisOpen, setIsAnalysisOpen] = useState(false);
  const [playerFormState, setPlayerFormState] = useState<{
    isOpen: boolean;
    playerToEdit?: Player;
  }>({ isOpen: false });

  // Long Press State
  const [deleteState, setDeleteState] = useState<{ id: string | null; progress: number }>({ id: null, progress: 0 });
  const deleteTimerRef = useRef<number | null>(null);

  const [dragVisual, setDragVisual] = useState<{
    isDragging: boolean;
    startX: number;
    startY: number;
    currX: number;
    currY: number;
  }>({
    isDragging: false,
    startX: 0,
    startY: 0,
    currX: 0,
    currY: 0,
  });

  const dragRef = useRef<{
    isDragging: boolean;
    sourceId: string | null;
    startX: number;
    startY: number;
    hasMoved: boolean;
  }>({
    isDragging: false,
    sourceId: null,
    startX: 0,
    startY: 0,
    hasMoved: false
  });

  const boardRef = useRef<HTMLDivElement>(null);
  const [playerPositions, setPlayerPositions] = useState<{ [key: string]: { x: number, y: number } }>({});

  // --- Persistence ---

  useEffect(() => {
    const savedGame = localStorage.getItem('bankair_state_v1');
    if (savedGame) {
      try {
        const parsed = JSON.parse(savedGame);
        setPlayers(parsed.players || []);
        setTransactions(parsed.transactions || []);
        setGameStarted(parsed.gameStarted || false);
        setCurrency(parsed.currency || CURRENCIES[0]);
        setGameSettings(parsed.settings || { startingBalance: DEFAULT_STARTING_BALANCE, passGoAmount: DEFAULT_PASS_GO_AMOUNT });
      } catch (e) {
        console.error("Failed to load save", e);
      }
    }
  }, []);

  useEffect(() => {
    const stateToSave = {
      players,
      transactions,
      gameStarted,
      currency,
      settings: gameSettings
    };
    localStorage.setItem('bankair_state_v1', JSON.stringify(stateToSave));
  }, [players, transactions, gameStarted, currency, gameSettings]);

  // --- Logic ---

  const formatMoney = (val: number) => val.toLocaleString();

  const parseMoneyInput = (val: string) => {
    const clean = val.replace(/,/g, '').replace(/[^0-9]/g, '');
    return clean ? parseInt(clean) : 0;
  };

  const handleStartGame = () => {
    if (players.length < 2) return;
    const resetPlayers = players.map(p => ({
      ...p,
      balance: gameSettings.startingBalance,
      isBankrupt: false
    }));
    setPlayers(resetPlayers);
    setTransactions([]);
    setGameStarted(true);
  };

  const handleEndGame = () => {
    if (window.confirm("End current game and return to setup? Players will be preserved.")) {
      setGameStarted(false);
    }
  };

  const handleDeletePlayer = (id: string) => {
    if (players.length <= 2 && gameStarted) {
      alert("Cannot have fewer than 2 players in an active game.");
      return;
    }
    if (window.confirm("Remove this player from the game?")) {
      setPlayers(prev => prev.filter(p => p.id !== id));
      // Cleanup transactions involving this player? Usually better to keep history but mark player as 'Removed'
    }
  };

  const handleAddPlayer = () => {
    if (players.length >= 6) return;
    const count = players.length + 1;
    const randomAvatar = AVATARS[Math.floor(Math.random() * AVATARS.length)];
    const colorKeys = Object.keys(PLAYER_COLORS) as ThemeColor[];
    const randomColor = colorKeys[Math.floor(Math.random() * colorKeys.length)];

    const newPlayer: Player = {
      id: generateId(),
      name: `Player ${count}`,
      avatar: randomAvatar,
      balance: gameStarted ? gameSettings.startingBalance : 0,
      color: randomColor,
      isBankrupt: false
    };
    setPlayers([...players, newPlayer]);
  };

  const handleUpdatePlayerName = (id: string, name: string) => {
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const handleUpdatePlayerAppearance = (data: Partial<Player>) => {
    const editId = playerFormState.playerToEdit?.id;
    if (editId) {
      setPlayers(prev => prev.map(p => 
        p.id === editId ? { ...p, ...data } : p
      ));
    }
  };

  // --- Transactions ---

  const handleTransaction = (type: TransactionType, fromId: string, toId: string, amount: number) => {
    const newTx: Transaction = {
      id: generateId(),
      timestamp: Date.now(),
      type,
      fromId,
      toId,
      amount,
      isReverted: false
    };

    setTransactions(prev => [...prev, newTx]);
    applyTransactionEffect(newTx, false);
  };

  const handleToggleTransaction = (id: string) => {
    const txIndex = transactions.findIndex(t => t.id === id);
    if (txIndex === -1) return;

    const tx = transactions[txIndex];
    const isReverting = !tx.isReverted;

    const updatedTransactions = [...transactions];
    updatedTransactions[txIndex] = { ...tx, isReverted: isReverting };
    setTransactions(updatedTransactions);

    applyTransactionEffect(tx, isReverting);
  };

  const applyTransactionEffect = (tx: Transaction, isReversing: boolean) => {
    const { fromId, toId, amount } = tx;

    setPlayers(prevPlayers => prevPlayers.map(p => {
      let newBalance = p.balance;
      if (p.id === fromId) {
        newBalance = isReversing ? p.balance + amount : p.balance - amount;
      }
      if (p.id === toId) {
        newBalance = isReversing ? p.balance - amount : p.balance + amount;
      }
      return { ...p, balance: newBalance };
    }));
  };

  // --- Advanced Layout Calculation ---

  useEffect(() => {
    if (!gameStarted || !boardRef.current) return;

    const updatePositions = () => {
      if (!boardRef.current) return;

      const { width, height } = boardRef.current.getBoundingClientRect();
      if (width === 0 || height === 0) {
        requestAnimationFrame(updatePositions);
        return;
      }

      const cx = width / 2;
      const cy = height / 2;

      const isMobile = width < 768;
      const paddingX = isMobile ? 85 : 180;
      const paddingY = isMobile ? 130 : 180;

      const rx = (width / 2) - paddingX;
      const ry = (height / 2) - paddingY;

      if (rx <= 20 || ry <= 20) return;

      const newPositions: { [key: string]: { x: number, y: number } } = {};
      const numPlayers = players.length;

      const startAngle = numPlayers === 4 ? -Math.PI / 4 : -Math.PI / 2;

      players.forEach((player, index) => {
        const angle = (index / numPlayers) * 2 * Math.PI + startAngle; 
        newPositions[player.id] = {
          x: cx + rx * Math.cos(angle),
          y: cy + ry * Math.sin(angle)
        };
      });

      setPlayerPositions(newPositions);
    };

    const timer = setTimeout(updatePositions, 100);
    const observer = new ResizeObserver(() => requestAnimationFrame(updatePositions));
    observer.observe(boardRef.current);

    return () => {
      clearTimeout(timer);
      observer.disconnect();
    };
  }, [players.length, gameStarted]);

  // --- Long Press Deletion Tracker ---

  const startDeleteTimer = (id: string) => {
    if (id === 'BANK') return;

    setDeleteState({ id, progress: 0 });
    const startTime = Date.now();

    if (deleteTimerRef.current) clearInterval(deleteTimerRef.current);

    deleteTimerRef.current = window.setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min((elapsed / DELETE_THRESHOLD_MS) * 100, 100);

      setDeleteState({ id, progress });

      if (progress >= 100) {
        clearInterval(deleteTimerRef.current!);
        deleteTimerRef.current = null;
        if (window.navigator.vibrate) window.navigator.vibrate([100, 50, 100]);
        handleDeletePlayer(id);
        setDeleteState({ id: null, progress: 0 });
      }
    }, 50);
  };

  const cancelDeleteTimer = () => {
    if (deleteTimerRef.current) {
      clearInterval(deleteTimerRef.current);
      deleteTimerRef.current = null;
    }
    setDeleteState({ id: null, progress: 0 });
  };

  // --- Drag & Drop ---

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return;
    const clientX = e.clientX;
    const clientY = e.clientY;

    dragRef.current = {
      isDragging: true,
      sourceId: id,
      startX: clientX,
      startY: clientY,
      hasMoved: false
    };

    setDragVisual({
      isDragging: true,
      startX: clientX,
      startY: clientY,
      currX: clientX,
      currY: clientY
    });

    // Start long press detection
    startDeleteTimer(id);

    try {
      (e.target as Element).setPointerCapture(e.pointerId);
    } catch (err) { }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!dragRef.current.isDragging) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;

    if (Math.abs(dx) > 10 || Math.abs(dy) > 10) {
      dragRef.current.hasMoved = true;
      cancelDeleteTimer(); // Moved too much, cancel deletion
    }

    setDragVisual(prev => ({ ...prev, currX: e.clientX, currY: e.clientY }));
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    cancelDeleteTimer();
    if (!dragRef.current.isDragging) return;
    const { sourceId, hasMoved } = dragRef.current;

    if (!hasMoved && sourceId) {
      if (sourceId === 'BANK') {
        setIsHistoryOpen(true);
      } else {
        const player = players.find(p => p.id === sourceId);
        if (player) setPlayerFormState({ isOpen: true, playerToEdit: player });
      }
    } 
    else if (hasMoved && sourceId) {
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-id'));
      const targetId = targetElement?.getAttribute('data-id');

      if (targetId && targetId !== sourceId) {
        setModalState({ isOpen: true, initialFromId: sourceId, initialToId: targetId });
      }
    }

    dragRef.current = { isDragging: false, sourceId: null, startX: 0, startY: 0, hasMoved: false };
    setDragVisual(prev => ({ ...prev, isDragging: false }));
    try {
      (e.target as Element).releasePointerCapture(e.pointerId);
    } catch (err) { }
  };


  // --- Render ---

  if (!gameStarted) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 flex flex-col items-center p-4 md:p-8 font-sans text-slate-100 overflow-y-auto">
        <div className="w-full max-w-2xl space-y-8">

          <div className="text-center space-y-2">
            <h1 className="text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-600 drop-shadow-lg tracking-tighter">
              BankAIr
            </h1>
            <p className="text-slate-400 text-lg">The AI-Powered Monopoly Banker</p>
          </div>

          <div className="glass-panel rounded-3xl p-6 md:p-8 shadow-2xl space-y-6">
            <div className="flex items-center gap-3 border-b border-white/10 pb-4">
              <span className="text-2xl">⚙️</span>
              <h2 className="text-xl font-bold text-white">Set up</h2>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Starting Balance</label>
                <div className="relative">
                  <span className="absolute left-4 top-3 text-slate-400">{currency.position === 'prefix' ? currency.symbol : ''}</span>
                  <input 
                    type="text" 
                    value={formatMoney(gameSettings.startingBalance)}
                    onChange={(e) => setGameSettings({...gameSettings, startingBalance: parseMoneyInput(e.target.value)})}
                    className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-10 text-white font-mono focus:ring-2 focus:ring-cyan-500 outline-none transition-all"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Pass Go Amount</label>
                <div className="relative">
                  <span className="absolute left-4 top-3 text-slate-400">{currency.position === 'prefix' ? currency.symbol : ''}</span>
                  <input 
                    type="text" 
                    value={formatMoney(gameSettings.passGoAmount)}
                    onChange={(e) => setGameSettings({...gameSettings, passGoAmount: parseMoneyInput(e.target.value)})}
                    className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-10 text-white font-mono focus:ring-2 focus:ring-cyan-500 outline-none transition-all"
                  />
                </div>
              </div>

               <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Currency</label>
                <select 
                  value={currency.symbol}
                  onChange={(e) => setCurrency(CURRENCIES.find(c => c.symbol === e.target.value) || CURRENCIES[0])}
                  className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-4 text-white focus:ring-2 focus:ring-cyan-500 outline-none appearance-none"
                >
                  {CURRENCIES.map(c => <option key={c.symbol} value={c.symbol}>{c.name}</option>)}
                </select>
              </div>
            </div>
          </div>

          <div className="glass-panel rounded-3xl p-6 md:p-8 shadow-2xl space-y-6">
            <div className="flex items-center justify-between border-b border-white/10 pb-4">
               <div className="flex items-center gap-3">
                <span className="text-2xl">👥</span>
                <h2 className="text-xl font-bold text-white">Players ({players.length}/6)</h2>
              </div>
               <button 
                onClick={handleAddPlayer}
                disabled={players.length >= 6}
                className="bg-white/10 hover:bg-white/20 text-white p-2 rounded-lg transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
              </button>
            </div>

            <div className="space-y-3">
              {players.map((player) => (
                <div 
                  key={player.id} 
                  className={`flex items-center gap-3 bg-white/5 p-3 rounded-xl border border-white/5 hover:bg-white/10 transition-all ${deleteState.id === player.id ? 'bg-red-900/20 border-red-500/30' : ''}`}
                  onPointerDown={(e) => startDeleteTimer(player.id)}
                  onPointerUp={cancelDeleteTimer}
                  onPointerLeave={cancelDeleteTimer}
                >
                  <div className="relative">
                    <button 
                      onClick={() => setPlayerFormState({ isOpen: true, playerToEdit: player })}
                      className="text-3xl hover:scale-110 transition-transform"
                    >
                      {player.avatar}
                    </button>
                    {deleteState.id === player.id && (
                       <div className="absolute inset-0 rounded-full border-2 border-red-500 animate-ping opacity-30"></div>
                    )}
                  </div>
                  <div className="flex-1">
                     <input
                      type="text"
                      value={player.name}
                      onChange={(e) => handleUpdatePlayerName(player.id, e.target.value)}
                      className="bg-transparent text-white font-bold w-full outline-none border-b border-transparent focus:border-cyan-400"
                    />
                  </div>
                  <button 
                    onClick={() => handleDeletePlayer(player.id)}
                    className="text-slate-600 hover:text-red-400 transition-colors p-2"
                  >
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                </div>
              ))}
              {players.length === 0 && <div className="text-center text-slate-500 py-4 italic">No players added.</div>}
            </div>
          </div>

          <Button fullWidth size="lg" onClick={handleStartGame} disabled={players.length < 2} className="!bg-gradient-to-r !from-cyan-500 !to-blue-600 !py-4 !text-xl !shadow-xl">
            Start Game 🚀
          </Button>
        </div>

        <PlayerFormModal 
          isOpen={playerFormState.isOpen}
          onClose={() => setPlayerFormState({ isOpen: false, playerToEdit: undefined })}
          initialData={playerFormState.playerToEdit}
          onSave={handleUpdatePlayerAppearance}
        />
      </div>
    );
  }

  return (
    <div 
      className="fixed inset-0 bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 overflow-hidden font-sans text-slate-100 touch-none"
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onContextMenu={(e) => e.preventDefault()}
    >
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-blue-900/20 via-transparent to-transparent pointer-events-none"></div>

      {/* HUD Header */}
      <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-start z-40 pointer-events-none">
        <div className="flex gap-2 pointer-events-auto">
          <button onClick={handleEndGame} className="bg-white/10 hover:bg-red-500/20 text-slate-400 p-2 rounded-lg backdrop-blur-md border border-white/5 shadow-lg">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>

          {players.length < 6 && (
             <button onClick={handleAddPlayer} className="bg-white/10 hover:bg-cyan-500/20 text-slate-400 p-2 rounded-lg backdrop-blur-md border border-white/5">
               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
               </svg>
             </button>
          )}
        </div>

        <div className="flex gap-2 pointer-events-auto">
          <button onClick={() => setIsAnalysisOpen(true)} className="bg-purple-600 text-white p-2 rounded-lg shadow-lg"><span className="text-xl">🔮</span></button>
          <button onClick={() => setIsRulesOpen(true)} className="bg-white/10 text-slate-400 p-2 rounded-lg shadow-lg"><span className="text-xl">⚖️</span></button>
          <button onClick={() => setIsHistoryOpen(true)} className="bg-white/10 text-slate-400 p-2 rounded-lg shadow-lg"><span className="text-xl">📜</span></button>
        </div>
      </div>

      {/* Board Layout */}
      <div ref={boardRef} className="absolute inset-0 z-0">
        <BankCard currency={currency} onDragStart={handlePointerDown} />

        {players.map((player) => (
          <PlayerCard 
            key={player.id}
            player={player}
            currency={currency}
            onEditName={handleUpdatePlayerName}
            onDragStart={handlePointerDown}
            deleteProgress={deleteState.id === player.id ? deleteState.progress : 0}
            style={{
              left: playerPositions[player.id]?.x || '50%',
              top: playerPositions[player.id]?.y || '50%',
              opacity: playerPositions[player.id] ? 1 : 0, 
              visibility: playerPositions[player.id] ? 'visible' : 'hidden',
              transition: deleteState.id === player.id ? 'none' : 'opacity 0.4s ease-out, left 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), top 0.5s cubic-bezier(0.2, 0.8, 0.2, 1)'
            }}
          />
        ))}
      </div>

      {/* Drag Visuals */}
      {dragVisual.isDragging && (
        <div className="absolute inset-0 pointer-events-none z-50">
          <svg className="w-full h-full drop-shadow-[0_0_8px_rgba(34,211,238,0.8)]">
            <line 
              x1={dragVisual.startX} y1={dragVisual.startY} 
              x2={dragVisual.currX} y2={dragVisual.currY} 
              stroke="url(#gradient-line)" strokeWidth="6" strokeLinecap="round" className="opacity-80"
            />
             <defs>
              <linearGradient id="gradient-line" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#22d3ee" />
                <stop offset="100%" stopColor="#a855f7" />
              </linearGradient>
            </defs>
          </svg>
          <div 
            className="absolute w-8 h-8 rounded-full bg-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.8)] border-2 border-white transform -translate-x-1/2 -translate-y-1/2"
            style={{ left: dragVisual.currX, top: dragVisual.currY }}
          ></div>
        </div>
      )}

      {/* Modals */}
      <TransactionModal 
        isOpen={modalState.isOpen}
        initialFromId={modalState.initialFromId}
        initialToId={modalState.initialToId}
        onClose={() => setModalState({ isOpen: false })}
        players={players}
        currency={currency}
        passGoAmount={gameSettings.passGoAmount}
        onTransaction={handleTransaction}
      />

      <HistoryLogModal 
        isOpen={isHistoryOpen}
        onClose={() => setIsHistoryOpen(false)}
        transactions={transactions}
        players={players}
        currency={currency}
        onToggleTransaction={handleToggleTransaction}
      />

      <RulesBot isOpen={isRulesOpen} onClose={() => setIsRulesOpen(false)} />
      <AnalysisModal isOpen={isAnalysisOpen} onClose={() => setIsAnalysisOpen(false)} players={players} />
      <PlayerFormModal 
        isOpen={playerFormState.isOpen}
        onClose={() => setPlayerFormState({ isOpen: false, playerToEdit: undefined })}
        initialData={playerFormState.playerToEdit}
        onSave={handleUpdatePlayerAppearance}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Player, Currency } from '../types';
import { PLAYER_COLORS, PLAYER_BORDER_COLORS } from '../constants';
import { ThemeColor } from '../types';

interface PlayerCardProps {
  player: Player;
  currency: Currency;
  onEditName: (name: string) => void;
  onDragStart: (e: React.PointerEvent, id: string) => void;
  onDeleteClick: (e: React.MouseEvent, id: string) => void;
  showDeleteButton?: boolean;
  deleteProgress?: number; // 0 to 100
  style?: React.CSSProperties;
  className?: string;
}

const PlayerCard: React.FC<PlayerCardProps> = ({ 
  player, 
  currency, 
  onEditName, 
  onDragStart, 
  onDeleteClick,
  showDeleteButton = false,
  deleteProgress = 0,
  style, 
  className = '' 
}) => {
  const colorKey = player.color as ThemeColor;

  const borderColor = PLAYER_BORDER_COLORS[colorKey] || 'border-slate-500';
  const glowColor = PLAYER_COLORS[colorKey] || 'bg-slate-500';

  const formatMoney = (amount: number) => {
    let displayVal = amount.toLocaleString();
    if (Math.abs(amount) >= 10000000) displayVal = `${(amount/1000000).toFixed(1)}M`;
    else if (Math.abs(amount) >= 10000) displayVal = `${(amount/1000).toFixed(1)}k`;

    return currency.position === 'prefix' 
      ? `${currency.symbol}${displayVal}`
      : `${displayVal}${currency.symbol}`;
  };

  const isActivating = deleteProgress > 0 && deleteProgress < 100;
  const jiggleClass = showDeleteButton ? 'animate-jiggle' : '';

  return (
    <div 
      className={`absolute flex flex-col items-center touch-none select-none group cursor-grab active:cursor-grabbing ${className} ${jiggleClass}`}
      style={{
        ...style,
        transform: 'translate(-50%, -50%)',
        width: 'max-content',
        transition: isActivating ? 'none' : (style?.transition || 'all 0.4s ease-out')
      }}
      onPointerDown={(e) => onDragStart(e, player.id)}
      data-id={player.id}
    >
      {/* Avatar Circle */}
      <div 
        className={`relative w-28 h-28 md:w-40 md:h-40 rounded-full border-[6px] md:border-[8px] ${borderColor} shadow-[0_0_30px_rgba(0,0,0,0.6)] z-20 flex items-center justify-center bg-gradient-to-b from-slate-700 to-slate-900`}
      >
        {/* Activation Progress Ring (Feedback for hold) */}
        {isActivating && (
          <div className="absolute inset-0 z-30 pointer-events-none">
            <svg className="w-full h-full rotate-[-90deg]">
              <circle
                cx="50%"
                cy="50%"
                r="48%"
                fill="transparent"
                stroke="rgba(34, 211, 238, 0.6)"
                strokeWidth="8"
                strokeDasharray="301.6"
                strokeDashoffset={301.6 - (301.6 * deleteProgress) / 100}
                className="transition-all duration-75 ease-linear"
              />
            </svg>
          </div>
        )}

        {/* Delete Button (X) */}
        {showDeleteButton && (
          <button
            onClick={(e) => {
              e.stopPropagation();
              onDeleteClick(e, player.id);
            }}
            onPointerDown={(e) => e.stopPropagation()} // Prevent drag start when clicking delete
            className="absolute -top-2 -right-2 w-10 h-10 md:w-12 md:h-12 bg-red-600 border-4 border-slate-900 rounded-full flex items-center justify-center text-white shadow-xl z-50 hover:bg-red-500 hover:scale-110 active:scale-90 transition-all animate-pop-in"
          >
            <svg className="w-6 h-6 md:w-7 md:h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        )}

        <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-white/10 to-transparent pointer-events-none"></div>
        <div className={`absolute -inset-2 rounded-full opacity-0 group-hover:opacity-40 blur-xl transition-opacity duration-300 ${glowColor}`}></div>

        <span className="text-5xl md:text-7xl relative z-10 filter drop-shadow-lg select-none leading-none transform group-hover:rotate-6 transition-transform">
          {player.avatar}
        </span>

        {player.isBankrupt && (
          <div className="absolute inset-0 bg-black/80 rounded-full flex items-center justify-center z-40 border-4 border-red-600">
            <span className="text-4xl md:text-6xl">💀</span>
          </div>
        )}
      </div>

      {/* Info Pill */}
      <div className={`mt-3 flex flex-col items-center z-30 filter drop-shadow-xl scale-125 md:scale-150 origin-top transition-opacity ${showDeleteButton ? 'opacity-40' : 'opacity-100'}`}>
        <input
          value={player.name}
          onChange={(e) => onEditName(e.target.value)}
          onClick={(e) => e.stopPropagation()} 
          className="bg-slate-900/90 backdrop-blur-md rounded-t-lg px-2 py-0.5 text-[10px] md:text-xs text-white font-bold text-center w-20 md:w-24 outline-none border-b border-white/10 focus:bg-black focus:text-cyan-400 transition-colors truncate"
        />
        <div className={`bg-slate-800/95 backdrop-blur-md border border-t-0 border-white/10 rounded-b-lg px-2 py-0.5 min-w-[5rem] md:min-w-[6rem] text-center shadow-md ${player.balance < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
          <span className="text-xs md:text-sm font-black font-mono tracking-tight">
            {formatMoney(player.balance)}
          </span>
        </div>
      </div>

      <style>{`
        @keyframes jiggle {
          0% { transform: translate(-50%, -50%) rotate(-1deg); }
          50% { transform: translate(-50%, -50%) rotate(1deg); }
          100% { transform: translate(-50%, -50%) rotate(-1deg); }
        }
        @keyframes pop-in {
          0% { transform: scale(0); opacity: 0; }
          70% { transform: scale(1.2); opacity: 1; }
          100% { transform: scale(1); opacity: 1; }
        }
        .animate-jiggle { animation: jiggle 0.3s infinite ease-in-out; }
        .animate-pop-in { animation: pop-in 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
      `}</style>
    </div>
  );
};

export default PlayerCard;

import React, { useState, useEffect, useRef } from 'react';
import { Player, Transaction, TransactionType, ThemeColor, Currency, GameSettings } from './types';
import { DEFAULT_STARTING_BALANCE, DEFAULT_PASS_GO_AMOUNT, PLAYER_COLORS, CURRENCIES, AVATARS } from './constants';
import PlayerCard from './components/PlayerCard';
import BankCard from './components/BankCard';
import TransactionModal from './components/TransactionModal';
import HistoryLogModal from './components/HistoryLogModal';
import RulesBot from './components/RulesBot';
import Button from './components/Button';
import PlayerFormModal from './components/PlayerFormModal';
import AnalysisModal from './components/AnalysisModal';

const generateId = () => Math.random().toString(36).substr(2, 9);
const REVEAL_DELETE_THRESHOLD_MS = 600;

const App: React.FC = () => {
  // --- State ---

  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [gameSettings, setGameSettings] = useState<GameSettings>({
    startingBalance: DEFAULT_STARTING_BALANCE,
    passGoAmount: DEFAULT_PASS_GO_AMOUNT
  });

  const [players, setPlayers] = useState<Player[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [gameStarted, setGameStarted] = useState(false);

  const [modalState, setModalState] = useState<{
    isOpen: boolean;
    initialFromId?: string;
    initialToId?: string;
  }>({ isOpen: false });

  const [isRulesOpen, setIsRulesOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isAnalysisOpen, setIsAnalysisOpen] = useState(false);
  const [playerFormState, setPlayerFormState] = useState<{
    isOpen: boolean;
    playerToEdit?: Player;
  }>({ isOpen: false });

  // Long Press State
  const [deleteState, setDeleteState] = useState<{ 
    id: string | null; 
    progress: number;
    revealedId: string | null; 
  }>({ id: null, progress: 0, revealedId: null });
  const deleteTimerRef = useRef<number | null>(null);

  const [dragVisual, setDragVisual] = useState<{
    isDragging: boolean;
    startX: number;
    startY: number;
    currX: number;
    currY: number;
  }>({
    isDragging: false,
    startX: 0,
    startY: 0,
    currX: 0,
    currY: 0,
  });

  const dragRef = useRef<{
    isDragging: boolean;
    sourceId: string | null;
    startX: number;
    startY: number;
    hasMoved: boolean;
  }>({
    isDragging: false,
    sourceId: null,
    startX: 0,
    startY: 0,
    hasMoved: false
  });

  const boardRef = useRef<HTMLDivElement>(null);
  const [playerPositions, setPlayerPositions] = useState<{ [key: string]: { x: number, y: number } }>({});

  // --- Persistence ---

  useEffect(() => {
    const savedGame = localStorage.getItem('bankair_state_v1');
    if (savedGame) {
      try {
        const parsed = JSON.parse(savedGame);
        setPlayers(parsed.players || []);
        setTransactions(parsed.transactions || []);
        setGameStarted(parsed.gameStarted || false);
        setCurrency(parsed.currency || CURRENCIES[0]);
        setGameSettings(parsed.settings || { startingBalance: DEFAULT_STARTING_BALANCE, passGoAmount: DEFAULT_PASS_GO_AMOUNT });
      } catch (e) {
        console.error("Failed to load save", e);
      }
    }
  }, []);

  useEffect(() => {
    const stateToSave = {
      players,
      transactions,
      gameStarted,
      currency,
      settings: gameSettings
    };
    localStorage.setItem('bankair_state_v1', JSON.stringify(stateToSave));
  }, [players, transactions, gameStarted, currency, gameSettings]);

  // --- Logic ---

  const formatMoney = (val: number) => val.toLocaleString();

  const parseMoneyInput = (val: string) => {
    const clean = val.replace(/,/g, '').replace(/[^0-9]/g, '');
    return clean ? parseInt(clean) : 0;
  };

  const handleStartGame = () => {
    if (players.length < 2) return;
    const resetPlayers = players.map(p => ({
      ...p,
      balance: gameSettings.startingBalance,
      isBankrupt: false
    }));
    setPlayers(resetPlayers);
    setTransactions([]);
    setGameStarted(true);
  };

  const handleEndGame = () => {
    if (window.confirm("End current game and return to setup? Players will be preserved.")) {
      setGameStarted(false);
    }
  };

  const handleDeletePlayer = (id: string) => {
    if (players.length <= 2 && gameStarted) {
      alert("Cannot have fewer than 2 players in an active game.");
      return;
    }
    if (window.confirm("Remove this player from the game?")) {
      setPlayers(prev => prev.filter(p => p.id !== id));
      setDeleteState(prev => ({ ...prev, revealedId: null }));
    }
  };

  const handleAddPlayer = () => {
    if (players.length >= 6) return;
    const count = players.length + 1;
    const randomAvatar = AVATARS[Math.floor(Math.random() * AVATARS.length)];
    const colorKeys = Object.keys(PLAYER_COLORS) as ThemeColor[];
    const randomColor = colorKeys[Math.floor(Math.random() * colorKeys.length)];

    const newPlayer: Player = {
      id: generateId(),
      name: `Player ${count}`,
      avatar: randomAvatar,
      balance: gameStarted ? gameSettings.startingBalance : 0,
      color: randomColor,
      isBankrupt: false
    };
    setPlayers([...players, newPlayer]);
  };

  const handleUpdatePlayerName = (id: string, name: string) => {
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const handleUpdatePlayerAppearance = (data: Partial<Player>) => {
    const editId = playerFormState.playerToEdit?.id;
    if (editId) {
      setPlayers(prev => prev.map(p => 
        p.id === editId ? { ...p, ...data } : p
      ));
    }
  };

  // --- Transactions ---

  const handleTransaction = (type: TransactionType, fromId: string, toId: string, amount: number) => {
    const newTx: Transaction = {
      id: generateId(),
      timestamp: Date.now(),
      type,
      fromId,
      toId,
      amount,
      isReverted: false
    };

    setTransactions(prev => [...prev, newTx]);
    applyTransactionEffect(newTx, false);
  };

  const handleToggleTransaction = (id: string) => {
    const txIndex = transactions.findIndex(t => t.id === id);
    if (txIndex === -1) return;

    const tx = transactions[txIndex];
    const isReverting = !tx.isReverted;

    const updatedTransactions = [...transactions];
    updatedTransactions[txIndex] = { ...tx, isReverted: isReverting };
    setTransactions(updatedTransactions);

    applyTransactionEffect(tx, isReverting);
  };

  const applyTransactionEffect = (tx: Transaction, isReversing: boolean) => {
    const { fromId, toId, amount } = tx;

    setPlayers(prevPlayers => prevPlayers.map(p => {
      let newBalance = p.balance;
      if (p.id === fromId) {
        newBalance = isReversing ? p.balance + amount : p.balance - amount;
      }
      if (p.id === toId) {
        newBalance = isReversing ? p.balance - amount : p.balance + amount;
      }
      return { ...p, balance: newBalance };
    }));
  };

  // --- Advanced Layout Calculation ---

  useEffect(() => {
    if (!gameStarted || !boardRef.current) return;

    const updatePositions = () => {
      if (!boardRef.current) return;

      const { width, height } = boardRef.current.getBoundingClientRect();
      if (width === 0 || height === 0) {
        requestAnimationFrame(updatePositions);
        return;
      }

      const cx = width / 2;
      const cy = height / 2;

      const isMobile = width < 768;
      const paddingX = isMobile ? 85 : 180;
      const paddingY = isMobile ? 130 : 180;

      const rx = (width / 2) - paddingX;
      const ry = (height / 2) - paddingY;

      if (rx <= 20 || ry <= 20) return;

      const newPositions: { [key: string]: { x: number, y: number } } = {};
      const numPlayers = players.length;

      const startAngle = numPlayers === 4 ? -Math.PI / 4 : -Math.PI / 2;

      players.forEach((player, index) => {
        const angle = (index / numPlayers) * 2 * Math.PI + startAngle; 
        newPositions[player.id] = {
          x: cx + rx * Math.cos(angle),
          y: cy + ry * Math.sin(angle)
        };
      });

      setPlayerPositions(newPositions);
    };

    const timer = setTimeout(updatePositions, 100);
    const observer = new ResizeObserver(() => requestAnimationFrame(updatePositions));
    observer.observe(boardRef.current);

    return () => {
      clearTimeout(timer);
      observer.disconnect();
    };
  }, [players.length, gameStarted]);

  // --- Long Press Deletion Tracker ---

  const startDeleteTimer = (id: string) => {
    if (id === 'BANK') return;

    setDeleteState(prev => ({ ...prev, id, progress: 0 }));
    const startTime = Date.now();

    if (deleteTimerRef.current) clearInterval(deleteTimerRef.current);

    deleteTimerRef.current = window.setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min((elapsed / REVEAL_DELETE_THRESHOLD_MS) * 100, 100);

      setDeleteState(prev => ({ ...prev, progress }));

      if (progress >= 100) {
        clearInterval(deleteTimerRef.current!);
        deleteTimerRef.current = null;
        if (window.navigator.vibrate) window.navigator.vibrate(50);
        setDeleteState(prev => ({ ...prev, id: null, progress: 0, revealedId: id }));
      }
    }, 50);
  };

  const cancelDeleteTimer = () => {
    if (deleteTimerRef.current) {
      clearInterval(deleteTimerRef.current);
      deleteTimerRef.current = null;
    }
    setDeleteState(prev => ({ ...prev, id: null, progress: 0 }));
  };

  // --- Drag & Drop ---

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return;

    // If we tap on the board/another player while one has X revealed, dismiss it
    if (deleteState.revealedId && deleteState.revealedId !== id) {
       setDeleteState(prev => ({ ...prev, revealedId: null }));
    }

    const clientX = e.clientX;
    const clientY = e.clientY;

    dragRef.current = {
      isDragging: true,
      sourceId: id,
      startX: clientX,
      startY: clientY,
      hasMoved: false
    };

    setDragVisual({
      isDragging: true,
      startX: clientX,
      startY: clientY,
      currX: clientX,
      currY: clientY
    });

    // Start long press detection
    startDeleteTimer(id);

    try {
      (e.target as Element).setPointerCapture(e.pointerId);
    } catch (err) { }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!dragRef.current.isDragging) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;

    if (Math.abs(dx) > 10 || Math.abs(dy) > 10) {
      dragRef.current.hasMoved = true;
      cancelDeleteTimer(); // Moved too much, cancel reveal
    }

    setDragVisual(prev => ({ ...prev, currX: e.clientX, currY: e.clientY }));
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    cancelDeleteTimer();
    if (!dragRef.current.isDragging) return;
    const { sourceId, hasMoved } = dragRef.current;

    if (!hasMoved && sourceId) {
      if (sourceId === 'BANK') {
        setIsHistoryOpen(true);
      } else {
        // If clicking a player while X is visible, toggle it off or edit
        if (deleteState.revealedId === sourceId) {
           setDeleteState(prev => ({ ...prev, revealedId: null }));
        } else {
           const player = players.find(p => p.id === sourceId);
           if (player) setPlayerFormState({ isOpen: true, playerToEdit: player });
        }
      }
    } 
    else if (hasMoved && sourceId) {
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-id'));
      const targetId = targetElement?.getAttribute('data-id');

      if (targetId && targetId !== sourceId) {
        setModalState({ isOpen: true, initialFromId: sourceId, initialToId: targetId });
      }
    }

    dragRef.current = { isDragging: false, sourceId: null, startX: 0, startY: 0, hasMoved: false };
    setDragVisual(prev => ({ ...prev, isDragging: false }));
    try {
      (e.target as Element).releasePointerCapture(e.pointerId);
    } catch (err) { }
  };

  const handleBoardPointerDown = (e: React.PointerEvent) => {
    // Dismiss any revealed delete icons when tapping empty space
    if (deleteState.revealedId) {
      setDeleteState(prev => ({ ...prev, revealedId: null }));
    }
  };


  // --- Render ---

  if (!gameStarted) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 flex flex-col items-center p-4 md:p-8 font-sans text-slate-100 overflow-y-auto">
        <div className="w-full max-w-2xl space-y-8">

          <div className="text-center space-y-2">
            <h1 className="text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-600 drop-shadow-lg tracking-tighter">
              PolyBank AI
            </h1>
            <p className="text-slate-400 text-lg">The Smart Monopoly Banking Assistant</p>
          </div>

          <div className="glass-panel rounded-3xl p-6 md:p-8 shadow-2xl space-y-6">
            <div className="flex items-center gap-3 border-b border-white/10 pb-4">
              <span className="text-2xl">⚙️</span>
              <h2 className="text-xl font-bold text-white">Set up</h2>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Starting Balance</label>
                <div className="relative">
                  <span className="absolute left-4 top-3 text-slate-400">{currency.position === 'prefix' ? currency.symbol : ''}</span>
                  <input 
                    type="text" 
                    value={formatMoney(gameSettings.startingBalance)}
                    onChange={(e) => setGameSettings({...gameSettings, startingBalance: parseMoneyInput(e.target.value)})}
                    className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-10 text-white font-mono focus:ring-2 focus:ring-cyan-500 outline-none transition-all"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Pass Go Amount</label>
                <div className="relative">
                  <span className="absolute left-4 top-3 text-slate-400">{currency.position === 'prefix' ? currency.symbol : ''}</span>
                  <input 
                    type="text" 
                    value={formatMoney(gameSettings.passGoAmount)}
                    onChange={(e) => setGameSettings({...gameSettings, passGoAmount: parseMoneyInput(e.target.value)})}
                    className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-10 text-white font-mono focus:ring-2 focus:ring-cyan-500 outline-none transition-all"
                  />
                </div>
              </div>

               <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Currency</label>
                <select 
                  value={currency.symbol}
                  onChange={(e) => setCurrency(CURRENCIES.find(c => c.symbol === e.target.value) || CURRENCIES[0])}
                  className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-4 text-white focus:ring-2 focus:ring-cyan-500 outline-none appearance-none"
                >
                  {CURRENCIES.map(c => <option key={c.symbol} value={c.symbol}>{c.name}</option>)}
                </select>
              </div>
            </div>
          </div>

          <div className="glass-panel rounded-3xl p-6 md:p-8 shadow-2xl space-y-6">
            <div className="flex items-center justify-between border-b border-white/10 pb-4">
               <div className="flex items-center gap-3">
                <span className="text-2xl">👥</span>
                <h2 className="text-xl font-bold text-white">Players ({players.length}/6)</h2>
              </div>
               <button 
                onClick={handleAddPlayer}
                disabled={players.length >= 6}
                className="bg-white/10 hover:bg-white/20 text-white p-2 rounded-lg transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
              </button>
            </div>

            <div className="space-y-3">
              {players.map((player) => (
                <div 
                  key={player.id} 
                  className={`flex items-center gap-3 bg-white/5 p-3 rounded-xl border border-white/5 hover:bg-white/10 transition-all ${deleteState.id === player.id ? 'bg-red-900/20 border-red-500/30' : ''}`}
                >
                  <div className="relative">
                    <button 
                      onClick={() => setPlayerFormState({ isOpen: true, playerToEdit: player })}
                      className="text-3xl hover:scale-110 transition-transform"
                    >
                      {player.avatar}
                    </button>
                  </div>
                  <div className="flex-1">
                     <input
                      type="text"
                      value={player.name}
                      onChange={(e) => handleUpdatePlayerName(player.id, e.target.value)}
                      className="bg-transparent text-white font-bold w-full outline-none border-b border-transparent focus:border-cyan-400"
                    />
                  </div>
                  <button 
                    onClick={() => handleDeletePlayer(player.id)}
                    className="text-slate-600 hover:text-red-400 transition-colors p-2"
                  >
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                </div>
              ))}
              {players.length === 0 && <div className="text-center text-slate-500 py-4 italic">No players added.</div>}
            </div>
          </div>

          <Button fullWidth size="lg" onClick={handleStartGame} disabled={players.length < 2} className="!bg-gradient-to-r !from-cyan-500 !to-blue-600 !py-4 !text-xl !shadow-xl">
            Start Game 🚀
          </Button>
        </div>

        <PlayerFormModal 
          isOpen={playerFormState.isOpen}
          onClose={() => setPlayerFormState({ isOpen: false, playerToEdit: undefined })}
          initialData={playerFormState.playerToEdit}
          onSave={handleUpdatePlayerAppearance}
        />
      </div>
    );
  }

  return (
    <div 
      className="fixed inset-0 bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 overflow-hidden font-sans text-slate-100 touch-none"
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerDown={handleBoardPointerDown}
      onContextMenu={(e) => e.preventDefault()}
    >
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-blue-900/20 via-transparent to-transparent pointer-events-none"></div>

      {/* HUD Header */}
      <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-start z-40 pointer-events-none">
        <div className="flex gap-2 pointer-events-auto">
          <button onClick={handleEndGame} className="bg-white/10 hover:bg-red-500/20 text-slate-400 p-2 rounded-lg backdrop-blur-md border border-white/5 shadow-lg">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>

          {players.length < 6 && (
             <button onClick={handleAddPlayer} className="bg-white/10 hover:bg-cyan-500/20 text-slate-400 p-2 rounded-lg backdrop-blur-md border border-white/5">
               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
               </svg>
             </button>
          )}
        </div>

        <div className="flex gap-2 pointer-events-auto">
          <button onClick={() => setIsAnalysisOpen(true)} className="bg-purple-600 text-white p-2 rounded-lg shadow-lg"><span className="text-xl">🔮</span></button>
          <button onClick={() => setIsRulesOpen(true)} className="bg-white/10 text-slate-400 p-2 rounded-lg shadow-lg"><span className="text-xl">⚖️</span></button>
          <button onClick={() => setIsHistoryOpen(true)} className="bg-white/10 text-slate-400 p-2 rounded-lg shadow-lg"><span className="text-xl">📜</span></button>
        </div>
      </div>

      {/* Board Layout */}
      <div ref={boardRef} className="absolute inset-0 z-0">
        <BankCard currency={currency} onDragStart={handlePointerDown} />

        {players.map((player) => (
          <PlayerCard 
            key={player.id}
            player={player}
            currency={currency}
            onEditName={handleUpdatePlayerName}
            onDragStart={handlePointerDown}
            onDeleteClick={(e) => handleDeletePlayer(player.id)}
            showDeleteButton={deleteState.revealedId === player.id}
            deleteProgress={deleteState.id === player.id ? deleteState.progress : 0}
            style={{
              left: playerPositions[player.id]?.x || '50%',
              top: playerPositions[player.id]?.y || '50%',
              opacity: playerPositions[player.id] ? 1 : 0, 
              visibility: playerPositions[player.id] ? 'visible' : 'hidden',
              transition: (deleteState.id === player.id) ? 'none' : 'opacity 0.4s ease-out, left 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), top 0.5s cubic-bezier(0.2, 0.8, 0.2, 1)'
            }}
          />
        ))}
      </div>

      {/* Drag Visuals */}
      {dragVisual.isDragging && (
        <div className="absolute inset-0 pointer-events-none z-50">
          <svg className="w-full h-full drop-shadow-[0_0_8px_rgba(34,211,238,0.8)]">
            <line 
              x1={dragVisual.startX} y1={dragVisual.startY} 
              x2={dragVisual.currX} y2={dragVisual.currY} 
              stroke="url(#gradient-line)" strokeWidth="6" strokeLinecap="round" className="opacity-80"
            />
             <defs>
              <linearGradient id="gradient-line" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#22d3ee" />
                <stop offset="100%" stopColor="#a855f7" />
              </linearGradient>
            </defs>
          </svg>
          <div 
            className="absolute w-8 h-8 rounded-full bg-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.8)] border-2 border-white transform -translate-x-1/2 -translate-y-1/2"
            style={{ left: dragVisual.currX, top: dragVisual.currY }}
          ></div>
        </div>
      )}

      {/* Modals */}
      <TransactionModal 
        isOpen={modalState.isOpen}
        initialFromId={modalState.initialFromId}
        initialToId={modalState.initialToId}
        onClose={() => setModalState({ isOpen: false })}
        players={players}
        currency={currency}
        passGoAmount={gameSettings.passGoAmount}
        onTransaction={handleTransaction}
      />

      <HistoryLogModal 
        isOpen={isHistoryOpen}
        onClose={() => setIsHistoryOpen(false)}
        transactions={transactions}
        players={players}
        currency={currency}
        onToggleTransaction={handleToggleTransaction}
      />

      <RulesBot isOpen={isRulesOpen} onClose={() => setIsRulesOpen(false)} />
      <AnalysisModal isOpen={isAnalysisOpen} onClose={() => setIsAnalysisOpen(false)} players={players} />
      <PlayerFormModal 
        isOpen={playerFormState.isOpen}
        onClose={() => setPlayerFormState({ isOpen: false, playerToEdit: undefined })}
        initialData={playerFormState.playerToEdit}
        onSave={handleUpdatePlayerAppearance}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { Player, Currency } from '../types';
import { PLAYER_COLORS, PLAYER_BORDER_COLORS } from '../constants';
import { ThemeColor } from '../types';

interface PlayerCardProps {
  player: Player;
  currency: Currency;
  onEditName: (name: string) => void;
  onDragStart: (e: React.PointerEvent, id: string) => void;
  onDeleteClick: (id: string) => void;
  showDeleteButton?: boolean;
  deleteProgress?: number; // 0 to 100
  style?: React.CSSProperties;
  className?: string;
}

const PlayerCard: React.FC<PlayerCardProps> = ({ 
  player, 
  currency, 
  onEditName, 
  onDragStart, 
  onDeleteClick,
  showDeleteButton = false,
  deleteProgress = 0,
  style, 
  className = '' 
}) => {
  const colorKey = player.color as ThemeColor;

  const borderColor = PLAYER_BORDER_COLORS[colorKey] || 'border-slate-500';
  const glowColor = PLAYER_COLORS[colorKey] || 'bg-slate-500';

  const formatMoney = (amount: number) => {
    const abs = Math.abs(amount);
    let displayVal: string;

    if (abs >= 1000000) {
      displayVal = (amount / 1000000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'M';
    } else if (abs >= 10000) {
      displayVal = (amount / 1000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'K';
    } else {
      displayVal = amount.toLocaleString();
    }

    return currency.position === 'prefix' 
      ? `${currency.symbol}${displayVal}`
      : `${displayVal}${currency.symbol}`;
  };

  const isActivating = deleteProgress > 0 && deleteProgress < 100;
  const jiggleClass = showDeleteButton ? 'animate-jiggle' : '';

  return (
    <div 
      className={`absolute flex flex-col items-center touch-none select-none group cursor-grab active:cursor-grabbing ${className} ${jiggleClass}`}
      style={{
        ...style,
        transform: 'translate(-50%, -50%)',
        width: 'max-content',
        transition: isActivating ? 'none' : (style?.transition || 'all 0.4s ease-out')
      }}
      onPointerDown={(e) => onDragStart(e, player.id)}
      data-id={player.id}
    >
      {/* Avatar Circle */}
      <div 
        className={`relative w-28 h-28 md:w-40 md:h-40 rounded-full border-[6px] md:border-[8px] ${borderColor} shadow-[0_0_30px_rgba(0,0,0,0.6)] z-20 flex items-center justify-center bg-gradient-to-b from-slate-700 to-slate-900`}
      >
        {/* Activation Progress Ring */}
        {isActivating && (
          <div className="absolute inset-0 z-30 pointer-events-none">
            <svg className="w-full h-full rotate-[-90deg]">
              <circle
                cx="50%"
                cy="50%"
                r="48%"
                fill="transparent"
                stroke="rgba(34, 211, 238, 0.6)"
                strokeWidth="8"
                strokeDasharray="301.6"
                strokeDashoffset={301.6 - (301.6 * deleteProgress) / 100}
                className="transition-all duration-75 ease-linear"
              />
            </svg>
          </div>
        )}

        {/* Delete Button (X) - Fixed with Pointer Events */}
        {showDeleteButton && (
          <button
            onPointerDown={(e) => e.stopPropagation()} 
            onPointerUp={(e) => {
              e.stopPropagation();
              onDeleteClick(player.id);
            }}
            className="absolute -top-2 -right-2 w-10 h-10 md:w-12 md:h-12 bg-red-600 border-4 border-slate-900 rounded-full flex items-center justify-center text-white shadow-xl z-[60] hover:bg-red-500 hover:scale-110 active:scale-90 transition-all animate-pop-in pointer-events-auto"
          >
            <svg className="w-6 h-6 md:w-7 md:h-7 pointer-events-none" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        )}

        <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-white/10 to-transparent pointer-events-none"></div>
        <div className={`absolute -inset-2 rounded-full opacity-0 group-hover:opacity-40 blur-xl transition-opacity duration-300 ${glowColor}`}></div>

        <span className="text-5xl md:text-7xl relative z-10 filter drop-shadow-lg select-none leading-none transform group-hover:rotate-6 transition-transform">
          {player.avatar}
        </span>

        {player.isBankrupt && (
          <div className="absolute inset-0 bg-black/80 rounded-full flex items-center justify-center z-40 border-4 border-red-600">
            <span className="text-4xl md:text-6xl">💀</span>
          </div>
        )}
      </div>

      {/* Info Pill */}
      <div className={`mt-3 flex flex-col items-center z-30 filter drop-shadow-xl scale-125 md:scale-150 origin-top transition-opacity ${showDeleteButton ? 'opacity-40' : 'opacity-100'}`}>
        <div className="bg-slate-900/90 backdrop-blur-md rounded-t-lg px-2 py-0.5 text-[10px] md:text-xs text-white font-bold text-center w-20 md:w-24 border-b border-white/10 truncate">
          {player.name}
        </div>
        <div className={`bg-slate-800/95 backdrop-blur-md border border-t-0 border-white/10 rounded-b-lg px-2 py-0.5 min-w-[5rem] md:min-w-[6rem] text-center shadow-md ${player.balance < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
          <span className="text-xs md:text-sm font-black font-mono tracking-tight">
            {formatMoney(player.balance)}
          </span>
        </div>
      </div>

      <style>{`
        @keyframes jiggle {
          0% { transform: translate(-50%, -50%) rotate(-1deg); }
          50% { transform: translate(-50%, -50%) rotate(1deg); }
          100% { transform: translate(-50%, -50%) rotate(-1deg); }
        }
        @keyframes pop-in {
          0% { transform: scale(0); opacity: 0; }
          70% { transform: scale(1.2); opacity: 1; }
          100% { transform: scale(1); opacity: 1; }
        }
        .animate-jiggle { animation: jiggle 0.3s infinite ease-in-out; }
        .animate-pop-in { animation: pop-in 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
      `}</style>
    </div>
  );
};

export default PlayerCard;

import React, { useState, useEffect, useRef } from 'react';
import { Player, Transaction, TransactionType, ThemeColor, Currency, GameSettings } from './types';
import { DEFAULT_STARTING_BALANCE, DEFAULT_PASS_GO_AMOUNT, PLAYER_COLORS, CURRENCIES, AVATARS } from './constants';
import PlayerCard from './components/PlayerCard';
import BankCard from './components/BankCard';
import TransactionModal from './components/TransactionModal';
import HistoryLogModal from './components/HistoryLogModal';
import RulesBot from './components/RulesBot';
import Button from './components/Button';
import PlayerFormModal from './components/PlayerFormModal';
import AnalysisModal from './components/AnalysisModal';

const generateId = () => Math.random().toString(36).substr(2, 9);
const REVEAL_DELETE_THRESHOLD_MS = 600;

const App: React.FC = () => {
  // --- State ---

  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [gameSettings, setGameSettings] = useState<GameSettings>({
    startingBalance: DEFAULT_STARTING_BALANCE,
    passGoAmount: DEFAULT_PASS_GO_AMOUNT
  });

  const [players, setPlayers] = useState<Player[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [gameStarted, setGameStarted] = useState(false);

  const [modalState, setModalState] = useState<{
    isOpen: boolean;
    initialFromId?: string;
    initialToId?: string;
  }>({ isOpen: false });

  const [isRulesOpen, setIsRulesOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isAnalysisOpen, setIsAnalysisOpen] = useState(false);
  const [playerFormState, setPlayerFormState] = useState<{
    isOpen: boolean;
    playerToEdit?: Player;
  }>({ isOpen: false });

  // Long Press State
  const [deleteState, setDeleteState] = useState<{ 
    id: string | null; 
    progress: number;
    revealedId: string | null; 
  }>({ id: null, progress: 0, revealedId: null });
  const deleteTimerRef = useRef<number | null>(null);

  const [dragVisual, setDragVisual] = useState<{
    isDragging: boolean;
    startX: number;
    startY: number;
    currX: number;
    currY: number;
  }>({
    isDragging: false,
    startX: 0,
    startY: 0,
    currX: 0,
    currY: 0,
  });

  const dragRef = useRef<{
    isDragging: boolean;
    sourceId: string | null;
    startX: number;
    startY: number;
    hasMoved: boolean;
  }>({
    isDragging: false,
    sourceId: null,
    startX: 0,
    startY: 0,
    hasMoved: false
  });

  const boardRef = useRef<HTMLDivElement>(null);
  const [playerPositions, setPlayerPositions] = useState<{ [key: string]: { x: number, y: number } }>({});

  // --- Persistence ---

  useEffect(() => {
    const savedGame = localStorage.getItem('bankair_state_v1');
    if (savedGame) {
      try {
        const parsed = JSON.parse(savedGame);
        setPlayers(parsed.players || []);
        setTransactions(parsed.transactions || []);
        setGameStarted(parsed.gameStarted || false);
        setCurrency(parsed.currency || CURRENCIES[0]);
        setGameSettings(parsed.settings || { startingBalance: DEFAULT_STARTING_BALANCE, passGoAmount: DEFAULT_PASS_GO_AMOUNT });
      } catch (e) {
        console.error("Failed to load save", e);
      }
    }
  }, []);

  useEffect(() => {
    const stateToSave = {
      players,
      transactions,
      gameStarted,
      currency,
      settings: gameSettings
    };
    localStorage.setItem('bankair_state_v1', JSON.stringify(stateToSave));
  }, [players, transactions, gameStarted, currency, gameSettings]);

  // --- Logic ---

  const formatMoney = (amount: number) => {
    const abs = Math.abs(amount);
    let val: string;
    if (abs >= 1000000) val = (amount / 1000000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'M';
    else if (abs >= 10000) val = (amount / 1000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'K';
    else val = amount.toLocaleString();

    return currency.position === 'prefix' ? `${currency.symbol}${val}` : `${val}${currency.symbol}`;
  };

  const parseMoneyInput = (val: string) => {
    const clean = val.replace(/,/g, '').replace(/[^0-9]/g, '');
    return clean ? parseInt(clean) : 0;
  };

  const handleStartGame = () => {
    if (players.length < 2) return;
    const resetPlayers = players.map(p => ({
      ...p,
      balance: gameSettings.startingBalance,
      isBankrupt: false
    }));
    setPlayers(resetPlayers);
    setTransactions([]);
    setGameStarted(true);
  };

  const handleEndGame = () => {
    if (window.confirm("End current game and return to setup? Players will be preserved.")) {
      setGameStarted(false);
    }
  };

  const handleDeletePlayer = (id: string) => {
    if (players.length <= 2 && gameStarted) {
      alert("Cannot have fewer than 2 players in an active game.");
      return;
    }
    if (window.confirm("Remove this player from the game?")) {
      setPlayers(prev => prev.filter(p => p.id !== id));
      setDeleteState(prev => ({ ...prev, revealedId: null }));
    }
  };

  const handleAddPlayer = () => {
    if (players.length >= 6) return;
    const count = players.length + 1;
    const randomAvatar = AVATARS[Math.floor(Math.random() * AVATARS.length)];
    const colorKeys = Object.keys(PLAYER_COLORS) as ThemeColor[];
    const randomColor = colorKeys[Math.floor(Math.random() * colorKeys.length)];

    const newPlayer: Player = {
      id: generateId(),
      name: `Player ${count}`,
      avatar: randomAvatar,
      balance: gameStarted ? gameSettings.startingBalance : 0,
      color: randomColor,
      isBankrupt: false
    };
    setPlayers([...players, newPlayer]);
  };

  const handleUpdatePlayerName = (id: string, name: string) => {
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const handleUpdatePlayerAppearance = (data: Partial<Player>) => {
    const editId = playerFormState.playerToEdit?.id;
    if (editId) {
      setPlayers(prev => prev.map(p => 
        p.id === editId ? { ...p, ...data } : p
      ));
    }
  };

  // --- Transactions ---

  const handleTransaction = (type: TransactionType, fromId: string, toId: string, amount: number) => {
    const newTx: Transaction = {
      id: generateId(),
      timestamp: Date.now(),
      type,
      fromId,
      toId,
      amount,
      isReverted: false
    };

    setTransactions(prev => [...prev, newTx]);
    applyTransactionEffect(newTx, false);
  };

  const handleToggleTransaction = (id: string) => {
    const txIndex = transactions.findIndex(t => t.id === id);
    if (txIndex === -1) return;

    const tx = transactions[txIndex];
    const isReverting = !tx.isReverted;

    const updatedTransactions = [...transactions];
    updatedTransactions[txIndex] = { ...tx, isReverted: isReverting };
    setTransactions(updatedTransactions);

    applyTransactionEffect(tx, isReverting);
  };

  const applyTransactionEffect = (tx: Transaction, isReversing: boolean) => {
    const { fromId, toId, amount } = tx;

    setPlayers(prevPlayers => prevPlayers.map(p => {
      let newBalance = p.balance;
      if (p.id === fromId) {
        newBalance = isReversing ? p.balance + amount : p.balance - amount;
      }
      if (p.id === toId) {
        newBalance = isReversing ? p.balance - amount : p.balance + amount;
      }
      return { ...p, balance: newBalance };
    }));
  };

  // --- Advanced Layout Calculation ---

  useEffect(() => {
    if (!gameStarted || !boardRef.current) return;

    const updatePositions = () => {
      if (!boardRef.current) return;

      const { width, height } = boardRef.current.getBoundingClientRect();
      if (width === 0 || height === 0) {
        requestAnimationFrame(updatePositions);
        return;
      }

      const cx = width / 2;
      const cy = height / 2;

      const isMobile = width < 768;
      const paddingX = isMobile ? 85 : 180;
      const paddingY = isMobile ? 130 : 180;

      const rx = (width / 2) - paddingX;
      const ry = (height / 2) - paddingY;

      if (rx <= 20 || ry <= 20) return;

      const newPositions: { [key: string]: { x: number, y: number } } = {};
      const numPlayers = players.length;

      const startAngle = numPlayers === 4 ? -Math.PI / 4 : -Math.PI / 2;

      players.forEach((player, index) => {
        const angle = (index / numPlayers) * 2 * Math.PI + startAngle; 
        newPositions[player.id] = {
          x: cx + rx * Math.cos(angle),
          y: cy + ry * Math.sin(angle)
        };
      });

      setPlayerPositions(newPositions);
    };

    const timer = setTimeout(updatePositions, 100);
    const observer = new ResizeObserver(() => requestAnimationFrame(updatePositions));
    observer.observe(boardRef.current);

    return () => {
      clearTimeout(timer);
      observer.disconnect();
    };
  }, [players.length, gameStarted]);

  // --- Long Press Tracker ---

  const startDeleteTimer = (id: string) => {
    if (id === 'BANK') return;

    setDeleteState(prev => ({ ...prev, id, progress: 0 }));
    const startTime = Date.now();

    if (deleteTimerRef.current) clearInterval(deleteTimerRef.current);

    deleteTimerRef.current = window.setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min((elapsed / REVEAL_DELETE_THRESHOLD_MS) * 100, 100);

      setDeleteState(prev => ({ ...prev, progress }));

      if (progress >= 100) {
        clearInterval(deleteTimerRef.current!);
        deleteTimerRef.current = null;
        if (window.navigator.vibrate) window.navigator.vibrate(50);
        setDeleteState(prev => ({ ...prev, id: null, progress: 0, revealedId: id }));
      }
    }, 50);
  };

  const cancelDeleteTimer = () => {
    if (deleteTimerRef.current) {
      clearInterval(deleteTimerRef.current);
      deleteTimerRef.current = null;
    }
    setDeleteState(prev => ({ ...prev, id: null, progress: 0 }));
  };

  // --- Drag & Drop ---

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return;

    if (deleteState.revealedId && deleteState.revealedId !== id) {
       setDeleteState(prev => ({ ...prev, revealedId: null }));
    }

    const clientX = e.clientX;
    const clientY = e.clientY;

    dragRef.current = {
      isDragging: true,
      sourceId: id,
      startX: clientX,
      startY: clientY,
      hasMoved: false
    };

    setDragVisual({
      isDragging: true,
      startX: clientX,
      startY: clientY,
      currX: clientX,
      currY: clientY
    });

    startDeleteTimer(id);

    try {
      (e.target as Element).setPointerCapture(e.pointerId);
    } catch (err) { }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!dragRef.current.isDragging) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;

    if (Math.abs(dx) > 10 || Math.abs(dy) > 10) {
      dragRef.current.hasMoved = true;
      cancelDeleteTimer();
    }

    setDragVisual(prev => ({ ...prev, currX: e.clientX, currY: e.clientY }));
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    cancelDeleteTimer();
    if (!dragRef.current.isDragging) return;
    const { sourceId, hasMoved } = dragRef.current;

    if (!hasMoved && sourceId) {
      if (sourceId === 'BANK') {
        setIsHistoryOpen(true);
      } else {
        if (deleteState.revealedId === sourceId) {
           setDeleteState(prev => ({ ...prev, revealedId: null }));
        } else {
           const player = players.find(p => p.id === sourceId);
           if (player) setPlayerFormState({ isOpen: true, playerToEdit: player });
        }
      }
    } 
    else if (hasMoved && sourceId) {
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-id'));
      const targetId = targetElement?.getAttribute('data-id');

      if (targetId && targetId !== sourceId) {
        setModalState({ isOpen: true, initialFromId: sourceId, initialToId: targetId });
      }
    }

    dragRef.current = { isDragging: false, sourceId: null, startX: 0, startY: 0, hasMoved: false };
    setDragVisual(prev => ({ ...prev, isDragging: false }));
    try {
      (e.target as Element).releasePointerCapture(e.pointerId);
    } catch (err) { }
  };

  const handleBoardPointerDown = (e: React.PointerEvent) => {
    if (deleteState.revealedId) {
      setDeleteState(prev => ({ ...prev, revealedId: null }));
    }
  };

  // --- Render ---

  if (!gameStarted) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 flex flex-col items-center p-4 md:p-8 font-sans text-slate-100 overflow-y-auto">
        <div className="w-full max-w-2xl space-y-8">
          <div className="text-center space-y-2">
            <h1 className="text-6xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-600 drop-shadow-lg tracking-tighter">
              PolyBank AI
            </h1>
            <p className="text-slate-400 text-lg">The Smart Monopoly Banking Assistant</p>
          </div>

          <div className="glass-panel rounded-3xl p-6 md:p-8 shadow-2xl space-y-6">
            <div className="flex items-center gap-3 border-b border-white/10 pb-4">
              <span className="text-2xl">⚙️</span>
              <h2 className="text-xl font-bold text-white">Set up</h2>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Starting Balance</label>
                <div className="relative">
                  <span className="absolute left-4 top-3 text-slate-400">{currency.position === 'prefix' ? currency.symbol : ''}</span>
                  <input 
                    type="text" 
                    value={gameSettings.startingBalance.toLocaleString()}
                    onChange={(e) => setGameSettings({...gameSettings, startingBalance: parseMoneyInput(e.target.value)})}
                    className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-10 text-white font-mono focus:ring-2 focus:ring-cyan-500 outline-none transition-all"
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Pass Go Amount</label>
                <div className="relative">
                  <span className="absolute left-4 top-3 text-slate-400">{currency.position === 'prefix' ? currency.symbol : ''}</span>
                  <input 
                    type="text" 
                    value={gameSettings.passGoAmount.toLocaleString()}
                    onChange={(e) => setGameSettings({...gameSettings, passGoAmount: parseMoneyInput(e.target.value)})}
                    className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-10 text-white font-mono focus:ring-2 focus:ring-cyan-500 outline-none transition-all"
                  />
                </div>
              </div>

               <div className="space-y-2">
                <label className="text-xs font-bold text-blue-300 uppercase tracking-wider">Currency</label>
                <select 
                  value={currency.symbol}
                  onChange={(e) => setCurrency(CURRENCIES.find(c => c.symbol === e.target.value) || CURRENCIES[0])}
                  className="w-full bg-slate-900/50 border border-white/10 rounded-xl py-3 px-4 text-white focus:ring-2 focus:ring-cyan-500 outline-none appearance-none"
                >
                  {CURRENCIES.map(c => <option key={c.symbol} value={c.symbol}>{c.name}</option>)}
                </select>
              </div>
            </div>
          </div>

          <div className="glass-panel rounded-3xl p-6 md:p-8 shadow-2xl space-y-6">
            <div className="flex items-center justify-between border-b border-white/10 pb-4">
               <div className="flex items-center gap-3">
                <span className="text-2xl">👥</span>
                <h2 className="text-xl font-bold text-white">Players ({players.length}/6)</h2>
              </div>
               <button 
                onClick={handleAddPlayer}
                disabled={players.length >= 6}
                className="bg-white/10 hover:bg-white/20 text-white p-2 rounded-lg transition-colors disabled:opacity-30 disabled:cursor-not-allowed"
              >
                <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
                </svg>
              </button>
            </div>

            <div className="space-y-3">
              {players.map((player) => (
                <div 
                  key={player.id} 
                  className={`flex items-center gap-3 bg-white/5 p-3 rounded-xl border border-white/5 hover:bg-white/10 transition-all`}
                >
                  <div className="relative">
                    <button 
                      onClick={() => setPlayerFormState({ isOpen: true, playerToEdit: player })}
                      className="text-3xl hover:scale-110 transition-transform"
                    >
                      {player.avatar}
                    </button>
                  </div>
                  <div className="flex-1">
                     <input
                      type="text"
                      value={player.name}
                      onChange={(e) => handleUpdatePlayerName(player.id, e.target.value)}
                      className="bg-transparent text-white font-bold w-full outline-none border-b border-transparent focus:border-cyan-400"
                    />
                  </div>
                  <button 
                    onClick={() => handleDeletePlayer(player.id)}
                    className="text-slate-600 hover:text-red-400 transition-colors p-2"
                  >
                    <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
                    </svg>
                  </button>
                </div>
              ))}
              {players.length === 0 && <div className="text-center text-slate-500 py-4 italic">No players added.</div>}
            </div>
          </div>

          <Button fullWidth size="lg" onClick={handleStartGame} disabled={players.length < 2} className="!bg-gradient-to-r !from-cyan-500 !to-blue-600 !py-4 !text-xl !shadow-xl">
            Start Game 🚀
          </Button>
        </div>

        <PlayerFormModal 
          isOpen={playerFormState.isOpen}
          onClose={() => setPlayerFormState({ isOpen: false, playerToEdit: undefined })}
          initialData={playerFormState.playerToEdit}
          onSave={handleUpdatePlayerAppearance}
        />
      </div>
    );
  }

  return (
    <div 
      className="fixed inset-0 bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 overflow-hidden font-sans text-slate-100 touch-none"
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerDown={handleBoardPointerDown}
      onContextMenu={(e) => e.preventDefault()}
    >
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-blue-900/20 via-transparent to-transparent pointer-events-none"></div>

      {/* HUD Header */}
      <div className="absolute top-0 left-0 right-0 p-4 flex justify-between items-start z-40 pointer-events-none">
        <div className="flex gap-2 pointer-events-auto">
          <button onClick={handleEndGame} className="bg-white/10 hover:bg-red-500/20 text-slate-400 p-2 rounded-lg backdrop-blur-md border border-white/5 shadow-lg">
            <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>

          {players.length < 6 && (
             <button onClick={handleAddPlayer} className="bg-white/10 hover:bg-cyan-500/20 text-slate-400 p-2 rounded-lg backdrop-blur-md border border-white/5">
               <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4v16m8-8H4" />
               </svg>
             </button>
          )}
        </div>

        <div className="flex gap-2 pointer-events-auto">
          <button onClick={() => setIsAnalysisOpen(true)} className="bg-purple-600 text-white p-2 rounded-lg shadow-lg"><span className="text-xl">🔮</span></button>
          <button onClick={() => setIsRulesOpen(true)} className="bg-white/10 text-slate-400 p-2 rounded-lg shadow-lg"><span className="text-xl">⚖️</span></button>
          <button onClick={() => setIsHistoryOpen(true)} className="bg-white/10 text-slate-400 p-2 rounded-lg shadow-lg"><span className="text-xl">📜</span></button>
        </div>
      </div>

      <div ref={boardRef} className="absolute inset-0 z-0">
        <BankCard currency={currency} onDragStart={handlePointerDown} />

        {players.map((player) => (
          <PlayerCard 
            key={player.id}
            player={player}
            currency={currency}
            onEditName={handleUpdatePlayerName}
            onDragStart={handlePointerDown}
            onDeleteClick={handleDeletePlayer}
            showDeleteButton={deleteState.revealedId === player.id}
            deleteProgress={deleteState.id === player.id ? deleteState.progress : 0}
            style={{
              left: playerPositions[player.id]?.x || '50%',
              top: playerPositions[player.id]?.y || '50%',
              opacity: playerPositions[player.id] ? 1 : 0, 
              visibility: playerPositions[player.id] ? 'visible' : 'hidden',
              transition: (deleteState.id === player.id) ? 'none' : 'opacity 0.4s ease-out, left 0.5s cubic-bezier(0.2, 0.8, 0.2, 1), top 0.5s cubic-bezier(0.2, 0.8, 0.2, 1)'
            }}
          />
        ))}
      </div>

      {dragVisual.isDragging && (
        <div className="absolute inset-0 pointer-events-none z-50">
          <svg className="w-full h-full drop-shadow-[0_0_8px_rgba(34,211,238,0.8)]">
            <line 
              x1={dragVisual.startX} y1={dragVisual.startY} 
              x2={dragVisual.currX} y2={dragVisual.currY} 
              stroke="url(#gradient-line)" strokeWidth="6" strokeLinecap="round" className="opacity-80"
            />
             <defs>
              <linearGradient id="gradient-line" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#22d3ee" />
                <stop offset="100%" stopColor="#a855f7" />
              </linearGradient>
            </defs>
          </svg>
          <div 
            className="absolute w-8 h-8 rounded-full bg-cyan-400 shadow-[0_0_15px_rgba(34,211,238,0.8)] border-2 border-white transform -translate-x-1/2 -translate-y-1/2"
            style={{ left: dragVisual.currX, top: dragVisual.currY }}
          ></div>
        </div>
      )}

      <TransactionModal 
        isOpen={modalState.isOpen}
        initialFromId={modalState.initialFromId}
        initialToId={modalState.initialToId}
        onClose={() => setModalState({ isOpen: false })}
        players={players}
        currency={currency}
        passGoAmount={gameSettings.passGoAmount}
        onTransaction={handleTransaction}
      />

      <HistoryLogModal 
        isOpen={isHistoryOpen}
        onClose={() => setIsHistoryOpen(false)}
        transactions={transactions}
        players={players}
        currency={currency}
        onToggleTransaction={handleToggleTransaction}
      />

      <RulesBot isOpen={isRulesOpen} onClose={() => setIsRulesOpen(false)} />
      <AnalysisModal isOpen={isAnalysisOpen} onClose={() => setIsAnalysisOpen(false)} players={players} />
      <PlayerFormModal 
        isOpen={playerFormState.isOpen}
        onClose={() => setPlayerFormState({ isOpen: false, playerToEdit: undefined })}
        initialData={playerFormState.playerToEdit}
        onSave={handleUpdatePlayerAppearance}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Player, TransactionType, Currency } from '../types';
import Button from './Button';

interface TransactionModalProps {
  isOpen: boolean;
  initialFromId?: string;
  initialToId?: string;
  onClose: () => void;
  players: Player[];
  currency: Currency;
  passGoAmount: number;
  onTransaction: (type: TransactionType, fromId: string, toId: string, amount: number) => void;
}

const TransactionModal: React.FC<TransactionModalProps> = ({ 
  isOpen, 
  initialFromId, 
  initialToId, 
  onClose, 
  players, 
  currency,
  passGoAmount,
  onTransaction 
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'bank' | 'go'>('transfer');

  const [fromId, setFromId] = useState<string>('');
  const [toId, setToId] = useState<string>('');
  const [amount, setAmount] = useState<string>('');

  const [bankPlayerId, setBankPlayerId] = useState<string>('');
  const [bankAction, setBankAction] = useState<'pay' | 'receive'>('pay');
  const [bankAmount, setBankAmount] = useState<string>('');

  const [goPlayerId, setGoPlayerId] = useState<string>('');

  useEffect(() => {
    if (isOpen) {
      if (initialFromId === 'BANK' && initialToId && initialToId !== 'BANK') {
        setActiveTab('bank');
        setBankAction('receive');
        setBankPlayerId(initialToId);
      } else if (initialToId === 'BANK' && initialFromId && initialFromId !== 'BANK') {
        setActiveTab('bank');
        setBankAction('pay');
        setBankPlayerId(initialFromId);
      } else if (initialFromId && initialToId && initialFromId !== 'BANK' && initialToId !== 'BANK') {
        setActiveTab('transfer');
        setFromId(initialFromId);
        setToId(initialToId);
      } else {
        setActiveTab('transfer');
        setFromId('');
        setToId('');
        setBankPlayerId('');
      }
      setAmount('');
      setBankAmount('');
      setGoPlayerId('');
    }
  }, [isOpen, initialFromId, initialToId]);

  if (!isOpen) return null;

  const handleTransfer = (e: React.FormEvent) => {
    e.preventDefault();
    if (fromId && toId && amount && fromId !== toId) {
      onTransaction(TransactionType.TRANSFER, fromId, toId, parseInt(amount));
      onClose();
    }
  };

  const handleBankTransaction = (e: React.FormEvent) => {
    e.preventDefault();
    if (bankPlayerId && bankAmount) {
      if (bankAction === 'pay') {
        onTransaction(TransactionType.BANK_DEPOSIT, bankPlayerId, 'BANK', parseInt(bankAmount));
      } else {
        onTransaction(TransactionType.BANK_WITHDRAWAL, 'BANK', bankPlayerId, parseInt(bankAmount));
      }
      onClose();
    }
  };

  const handlePassGo = () => {
    if (goPlayerId) {
      onTransaction(TransactionType.PASS_GO, 'BANK', goPlayerId, passGoAmount);
      onClose();
    }
  };

  const formatMoney = (amount: number) => {
    const abs = Math.abs(amount);
    let val: string;
    if (abs >= 1000000) val = (amount / 1000000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'M';
    else if (abs >= 10000) val = (amount / 1000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'K';
    else val = amount.toLocaleString();

    return currency.position === 'prefix' ? `${currency.symbol}${val}` : `${val}${currency.symbol}`;
  }

  const quickAmounts = [50, 100, 200, 500];

  const renderPlayerSelect = (value: string, onChange: (val: string) => void, excludeId?: string, label?: string) => (
    <div>
      {label && <label className="block text-xs font-semibold text-blue-200 uppercase tracking-wider mb-2">{label}</label>}
      <div className="relative">
        <select 
          value={value} 
          onChange={(e) => onChange(e.target.value)}
          className="w-full bg-black/20 border border-white/20 text-white rounded-xl p-3 pl-10 appearance-none focus:ring-2 focus:ring-cyan-500 focus:border-transparent outline-none transition-all backdrop-blur-sm"
          required
        >
          <option value="" className="text-slate-900 bg-white">Select Player</option>
          {players.filter(p => p.id !== excludeId).map(p => (
            <option key={p.id} value={p.id} className="text-slate-900 bg-white">{p.name} ({formatMoney(p.balance)})</option>
          ))}
        </select>
        <div className="absolute left-3 top-3.5 pointer-events-none">
          {value ? players.find(p => p.id === value)?.avatar : '👤'}
        </div>
      </div>
    </div>
  );

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-md">
      <div className="bg-gradient-to-br from-slate-900/90 to-blue-900/90 border border-white/20 rounded-3xl w-full max-w-md shadow-2xl overflow-hidden backdrop-blur-xl">
        <div className="flex border-b border-white/10 bg-black/20">
          <button onClick={() => setActiveTab('transfer')} className={`flex-1 py-4 text-sm font-bold transition-all ${activeTab === 'transfer' ? 'bg-white/10 text-cyan-300 border-b-2 border-cyan-400' : 'text-slate-400 hover:text-white'}`}>Pay Player</button>
          <button onClick={() => setActiveTab('bank')} className={`flex-1 py-4 text-sm font-bold transition-all ${activeTab === 'bank' ? 'bg-white/10 text-cyan-300 border-b-2 border-cyan-400' : 'text-slate-400 hover:text-white'}`}>Bank</button>
          <button onClick={() => setActiveTab('go')} className={`flex-1 py-4 text-sm font-bold transition-all ${activeTab === 'go' ? 'bg-white/10 text-cyan-300 border-b-2 border-cyan-400' : 'text-slate-400 hover:text-white'}`}>Pass Go</button>
        </div>
        <div className="p-6">
          {activeTab === 'transfer' && (
            <form onSubmit={handleTransfer} className="space-y-4">
              {renderPlayerSelect(fromId, setFromId, undefined, "From")}
              <div className="flex justify-center -my-2 relative z-10">
                <div className="bg-slate-800 rounded-full p-2 border border-slate-600 shadow-lg text-cyan-400">
                  <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 14l-7 7m0 0l-7-7m7 7V3" /></svg>
                </div>
              </div>
              {renderPlayerSelect(toId, setToId, fromId, "To")}
              <div>
                <label className="block text-xs font-semibold text-blue-200 uppercase tracking-wider mb-2">Amount ({currency.symbol})</label>
                <input type="number" value={amount} onChange={(e) => setAmount(e.target.value)} className="w-full bg-black/20 border border-white/20 text-white rounded-xl p-3 text-3xl font-mono text-center focus:ring-2 focus:ring-cyan-500 outline-none" placeholder="0" required />
                <div className="flex gap-2 mt-2">
                  {quickAmounts.map(amt => <button key={amt} type="button" onClick={() => setAmount(amt.toString())} className="flex-1 bg-white/5 hover:bg-white/10 text-xs text-blue-200 font-bold py-2 rounded-lg border border-white/5 transition-colors">{amt}</button>)}
                </div>
              </div>
              <div className="pt-2 flex gap-3">
                <Button type="button" variant="ghost" fullWidth onClick={onClose}>Cancel</Button>
                <Button type="submit" fullWidth disabled={!fromId || !toId || !amount} className="bg-cyan-600">Pay</Button>
              </div>
            </form>
          )}
          {activeTab === 'bank' && (
            <form onSubmit={handleBankTransaction} className="space-y-6">
              <div>
                <label className="block text-xs font-semibold text-blue-200 uppercase tracking-wider mb-2">Action</label>
                <select value={bankAction} onChange={(e) => setBankAction(e.target.value as 'pay' | 'receive')} className="w-full bg-black/20 border border-white/20 text-white rounded-xl p-3 focus:ring-2 focus:ring-cyan-500 outline-none">
                  <option value="pay" className="text-slate-900 bg-white">Pay to Bank</option>
                  <option value="receive" className="text-slate-900 bg-white">Collect from Bank</option>
                </select>
              </div>
              {renderPlayerSelect(bankPlayerId, setBankPlayerId, undefined, "Player")}
              <div>
                <label className="block text-xs font-semibold text-blue-200 uppercase tracking-wider mb-2">Amount ({currency.symbol})</label>
                <input type="number" value={bankAmount} onChange={(e) => setBankAmount(e.target.value)} className="w-full bg-black/20 border border-white/20 text-white rounded-xl p-3 text-3xl font-mono text-center focus:ring-2 focus:ring-cyan-500 outline-none" placeholder="0" required />
                <div className="flex gap-2 mt-2">
                  {quickAmounts.map(amt => <button key={amt} type="button" onClick={() => setBankAmount(amt.toString())} className="flex-1 bg-white/5 hover:bg-white/10 text-xs text-blue-200 font-bold py-2 rounded-lg border border-white/5 transition-colors">{amt}</button>)}
                </div>
              </div>
              <div className="pt-2 flex gap-3">
                <Button type="button" variant="ghost" fullWidth onClick={onClose}>Cancel</Button>
                <Button type="submit" fullWidth disabled={!bankPlayerId || !bankAmount} className={bankAction === 'pay' ? "bg-red-500" : "bg-emerald-500"}>{bankAction === 'pay' ? 'Pay Bank' : 'Collect'}</Button>
              </div>
            </form>
          )}
          {activeTab === 'go' && (
            <div className="space-y-6 text-center">
              <div className="bg-emerald-500/10 border border-emerald-500/30 rounded-xl p-6">
                <h3 className="text-xl font-bold text-emerald-400">Collect {formatMoney(passGoAmount)}</h3>
              </div>
              {renderPlayerSelect(goPlayerId, setGoPlayerId, undefined, "Who passed GO?")}
              <div className="pt-2 flex gap-3">
                <Button variant="ghost" fullWidth onClick={onClose}>Cancel</Button>
                <Button fullWidth onClick={handlePassGo} disabled={!goPlayerId} className="bg-emerald-500">Collect</Button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default TransactionModal;

import React, { useRef } from 'react';
import { Transaction, Player, TransactionType, Currency } from '../types';

interface HistoryLogProps {
  transactions: Transaction[];
  players: Player[];
  currency: Currency;
  onToggleTransaction: (id: string) => void;
}

const HistoryLog: React.FC<HistoryLogProps> = ({ transactions, players, currency, onToggleTransaction }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  const getPlayer = (id: string) => {
    if (id === 'BANK') return { name: 'Bank', avatar: '🏛️' };
    const p = players.find(p => p.id === id);
    return p ? { name: p.name, avatar: p.avatar } : { name: 'Unknown', avatar: '❓' };
  };

  const formatMoney = (amount: number) => {
    const abs = Math.abs(amount);
    let val: string;
    if (abs >= 1000000) val = (amount / 1000000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'M';
    else if (abs >= 10000) val = (amount / 1000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'K';
    else val = amount.toLocaleString();

    return currency.position === 'prefix' ? `${currency.symbol}${val}` : `${val}${currency.symbol}`;
  };

  if (transactions.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-slate-500 p-8 text-center">
        <span className="text-4xl mb-2 opacity-30">📜</span>
        <p className="text-sm">No transactions yet.</p>
      </div>
    );
  }

  const displayTransactions = [...transactions].reverse();

  return (
    <div ref={scrollRef} className="h-full overflow-y-auto space-y-3 pr-2 custom-scrollbar">
      {displayTransactions.map((tx) => {
        const isDeposit = tx.toId !== 'BANK' && tx.fromId === 'BANK';
        const isPayment = tx.fromId !== 'BANK' && tx.toId === 'BANK';

        const fromPlayer = getPlayer(tx.fromId);
        const toPlayer = getPlayer(tx.toId);

        let icon = '';
        let colorClass = 'text-slate-300';

        if (tx.type === TransactionType.PASS_GO) {
          icon = '🏁';
          colorClass = 'text-emerald-400';
        } else if (isDeposit) {
          icon = '🏦';
          colorClass = 'text-emerald-400';
        } else if (isPayment) {
          icon = '📉';
          colorClass = 'text-red-400';
        } else {
            icon = '💸';
        }

        const isReverted = tx.isReverted;

        return (
          <div 
            key={tx.id} 
            className={`rounded-lg p-3 border transition-all ${
              isReverted 
                ? 'bg-red-900/10 border-red-500/20 opacity-60' 
                : 'bg-slate-800/50 border-slate-700/50'
            }`}
          >
            <div className="flex justify-between items-start mb-2">
              <div className="flex items-center gap-2">
                 <span className={`text-lg ${isReverted ? 'grayscale' : ''}`}>{icon}</span>
                 {isReverted && <span className="text-xs font-bold text-red-500 uppercase tracking-wider border border-red-500/50 px-1 rounded">Undone</span>}
              </div>
               <span className={`font-mono font-bold ${isReverted ? 'line-through text-slate-500' : colorClass}`}>
                 {formatMoney(tx.amount)}
               </span>
            </div>

            <div className={`flex items-center justify-between p-2 rounded ${isReverted ? 'bg-black/20 text-slate-500' : 'text-slate-300 bg-slate-900/50'}`}>
              <div className="flex items-center gap-1.5 overflow-hidden">
                <span className="text-base">{fromPlayer.avatar}</span>
                <span className="truncate">{fromPlayer.name}</span>
              </div>
              <span className="text-slate-600 px-1">➜</span>
              <div className="flex items-center gap-1.5 overflow-hidden justify-end">
                <span className="truncate">{toPlayer.name}</span>
                <span className="text-base">{toPlayer.avatar}</span>
              </div>
            </div>

            <div className="flex justify-between items-center mt-2">
               <span className="text-[10px] text-slate-600">
                {new Date(tx.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>

              <button 
                onClick={() => onToggleTransaction(tx.id)}
                className={`text-xs px-2 py-1 rounded border transition-colors ${
                  isReverted
                    ? 'bg-emerald-500/20 border-emerald-500/30 text-emerald-400 hover:bg-emerald-500/30'
                    : 'bg-slate-700/50 border-slate-600 text-slate-400 hover:bg-red-500/20 hover:text-red-400 hover:border-red-500/30'
                }`}
              >
                {isReverted ? 'Redo' : 'Undo'}
              </button>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default HistoryLog;

import React, { useState, useEffect } from 'react';
import { Player, TransactionType, Currency } from '../types';
import Button from './Button';

interface TransactionModalProps {
  isOpen: boolean;
  initialFromId?: string;
  initialToId?: string;
  onClose: () => void;
  players: Player[];
  currency: Currency;
  passGoAmount: number;
  onTransaction: (type: TransactionType, fromId: string, toId: string, amount: number) => void;
}

const TransactionModal: React.FC<TransactionModalProps> = ({ 
  isOpen, 
  initialFromId, 
  initialToId, 
  onClose, 
  players, 
  currency,
  passGoAmount,
  onTransaction 
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'bank' | 'go'>('transfer');

  const [fromId, setFromId] = useState<string>('');
  const [toId, setToId] = useState<string>('');
  const [amount, setAmount] = useState<string>(''); // Kept as string for raw typing

  const [bankPlayerId, setBankPlayerId] = useState<string>('');
  const [bankAction, setBankAction] = useState<'pay' | 'receive'>('pay');

  useEffect(() => {
    if (isOpen) {
      if (initialFromId === 'BANK' && initialToId && initialToId !== 'BANK') {
        setActiveTab('bank');
        setBankAction('receive');
        setBankPlayerId(initialToId);
      } else if (initialToId === 'BANK' && initialFromId && initialFromId !== 'BANK') {
        setActiveTab('bank');
        setBankAction('pay');
        setBankPlayerId(initialFromId);
      } else if (initialFromId && initialToId && initialFromId !== 'BANK' && initialToId !== 'BANK') {
        setActiveTab('transfer');
        setFromId(initialFromId);
        setToId(initialToId);
      } else {
        setActiveTab('transfer');
        setFromId('');
        setToId('');
        setBankPlayerId('');
      }
      setAmount('');
    }
  }, [isOpen, initialFromId, initialToId]);

  if (!isOpen) return null;

  const parseValue = (val: string) => {
    return parseInt(val.replace(/,/g, '')) || 0;
  };

  const handleTransfer = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = parseValue(amount);
    if (fromId && toId && numericAmount > 0 && fromId !== toId) {
      onTransaction(TransactionType.TRANSFER, fromId, toId, numericAmount);
      onClose();
    }
  };

  const handleBankTransaction = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = parseValue(amount);
    if (bankPlayerId && numericAmount > 0) {
      if (bankAction === 'pay') {
        onTransaction(TransactionType.BANK_DEPOSIT, bankPlayerId, 'BANK', numericAmount);
      } else {
        onTransaction(TransactionType.BANK_WITHDRAWAL, 'BANK', bankPlayerId, numericAmount);
      }
      onClose();
    }
  };

  const handlePassGo = () => {
    const p = players.find(p => p.id === bankPlayerId);
    if (bankPlayerId) {
      onTransaction(TransactionType.PASS_GO, 'BANK', bankPlayerId, passGoAmount);
      onClose();
    }
  };

  const formatWithCommas = (val: string) => {
    const num = val.replace(/[^0-9]/g, '');
    if (!num) return '';
    return parseInt(num).toLocaleString();
  };

  const applyUnit = (unit: 'K' | 'M') => {
    const current = parseValue(amount);
    if (current === 0) return;
    const multiplied = unit === 'K' ? current * 1000 : current * 1000000;
    setAmount(multiplied.toString());
  };

  const formatMoneyDisplay = (amount: number) => {
    const abs = Math.abs(amount);
    let val: string;
    if (abs >= 1000000) val = (amount / 1000000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'M';
    else if (abs >= 10000) val = (amount / 1000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'K';
    else val = amount.toLocaleString();

    return currency.position === 'prefix' ? `${currency.symbol}${val}` : `${val}${currency.symbol}`;
  }

  const renderAmountInput = (value: string, setter: (v: string) => void) => (
    <div className="space-y-3">
      <label className="block text-xs font-semibold text-blue-200 uppercase tracking-wider">Amount ({currency.symbol})</label>
      <div className="relative group">
        <input 
          type="text" 
          inputMode="numeric"
          value={formatWithCommas(value)} 
          onChange={(e) => setter(e.target.value.replace(/,/g, ''))} 
          className="w-full bg-black/40 border border-white/20 text-white rounded-2xl p-4 text-4xl font-mono text-center focus:ring-4 focus:ring-cyan-500/50 outline-none transition-all" 
          placeholder="0" 
          required 
        />
        {/* Floating Unit Buttons */}
        <div className="absolute right-2 top-1/2 -translate-y-1/2 flex flex-col gap-1">
          <button type="button" onClick={() => applyUnit('K')} className="bg-cyan-600 hover:bg-cyan-500 text-white font-bold px-3 py-1 rounded-lg text-xs shadow-lg transition-transform active:scale-90">K</button>
          <button type="button" onClick={() => applyUnit('M')} className="bg-purple-600 hover:bg-purple-500 text-white font-bold px-3 py-1 rounded-lg text-xs shadow-lg transition-transform active:scale-90">M</button>
        </div>
      </div>
      {/* Live Shorthand Preview */}
      {parseValue(value) > 0 && (
        <div className="text-center">
          <span className="text-xs font-bold text-cyan-400/70 animate-pulse">
            Transaction: {formatMoneyDisplay(parseValue(value))}
          </span>
        </div>
      )}
      <div className="flex gap-2">
        {[50, 100, 200, 500].map(amt => (
          <button key={amt} type="button" onClick={() => setter(amt.toString())} className="flex-1 bg-white/5 hover:bg-white/10 text-xs text-blue-200 font-bold py-3 rounded-xl border border-white/5 transition-all active:bg-cyan-500/20">
            {amt}
          </button>
        ))}
      </div>
    </div>
  );

  const renderPlayerSelect = (value: string, onChange: (val: string) => void, excludeId?: string, label?: string) => (
    <div className="space-y-2">
      {label && <label className="block text-xs font-semibold text-blue-200 uppercase tracking-wider">{label}</label>}
      <div className="relative">
        <select 
          value={value} 
          onChange={(e) => onChange(e.target.value)}
          className="w-full bg-black/40 border border-white/20 text-white rounded-2xl p-4 pl-12 appearance-none focus:ring-4 focus:ring-cyan-500/20 focus:border-cyan-500/50 outline-none transition-all backdrop-blur-sm"
          required
        >
          <option value="" className="bg-slate-900">Select Player</option>
          {players.filter(p => p.id !== excludeId).map(p => (
            <option key={p.id} value={p.id} className="bg-slate-900">{p.name} ({formatMoneyDisplay(p.balance)})</option>
          ))}
        </select>
        <div className="absolute left-4 top-1/2 -translate-y-1/2 text-2xl pointer-events-none">
          {value ? players.find(p => p.id === value)?.avatar : '👤'}
        </div>
        <div className="absolute right-4 top-1/2 -translate-y-1/2 pointer-events-none text-white/30">
          <svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" /></svg>
        </div>
      </div>
    </div>
  );

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/80 backdrop-blur-sm animate-in fade-in duration-200">
      <div className="bg-gradient-to-br from-slate-900 via-slate-900 to-indigo-950 border border-white/10 rounded-[2.5rem] w-full max-w-md shadow-2xl overflow-hidden backdrop-blur-xl">

        {/* Tab Header */}
        <div className="flex bg-black/20 p-2 gap-1">
          {(['transfer', 'bank', 'go'] as const).map(tab => (
            <button 
              key={tab}
              onClick={() => setActiveTab(tab)} 
              className={`flex-1 py-3 rounded-2xl text-xs font-black uppercase tracking-widest transition-all ${
                activeTab === tab 
                  ? 'bg-cyan-500 text-white shadow-lg shadow-cyan-500/20' 
                  : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'
              }`}
            >
              {tab === 'transfer' ? 'Pay' : tab === 'bank' ? 'Bank' : 'Go'}
            </button>
          ))}
        </div>

        <div className="p-8">
          {activeTab === 'transfer' && (
            <form onSubmit={handleTransfer} className="space-y-6">
              {renderPlayerSelect(fromId, setFromId, undefined, "Sender")}
              <div className="flex justify-center -my-3 relative z-10">
                <div className="bg-slate-800 rounded-full p-2 border border-slate-700 shadow-xl text-cyan-400 rotate-0">
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 14l-7 7m0 0l-7-7m7 7V3" /></svg>
                </div>
              </div>
              {renderPlayerSelect(toId, setToId, fromId, "Recipient")}
              {renderAmountInput(amount, setAmount)}
              <div className="pt-4 flex gap-3">
                <Button type="button" variant="ghost" fullWidth onClick={onClose} className="rounded-2xl">Cancel</Button>
                <Button type="submit" fullWidth disabled={!fromId || !toId || parseValue(amount) <= 0} className="bg-cyan-600 rounded-2xl shadow-xl shadow-cyan-500/20 h-14 text-lg">Send Payment</Button>
              </div>
            </form>
          )}

          {activeTab === 'bank' && (
            <form onSubmit={handleBankTransaction} className="space-y-6">
              <div className="flex bg-black/40 rounded-2xl p-1">
                {(['pay', 'receive'] as const).map(action => (
                  <button 
                    key={action}
                    type="button"
                    onClick={() => setBankAction(action)}
                    className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-tighter transition-all ${
                      bankAction === action 
                        ? (action === 'pay' ? 'bg-red-500' : 'bg-emerald-500') + ' text-white'
                        : 'text-slate-500'
                    }`}
                  >
                    {action === 'pay' ? 'Paying Bank' : 'Collecting'}
                  </button>
                ))}
              </div>
              {renderPlayerSelect(bankPlayerId, setBankPlayerId, undefined, "Player")}
              {renderAmountInput(amount, setAmount)}
              <div className="pt-4 flex gap-3">
                <Button type="button" variant="ghost" fullWidth onClick={onClose} className="rounded-2xl">Cancel</Button>
                <Button 
                  type="submit" 
                  fullWidth 
                  disabled={!bankPlayerId || parseValue(amount) <= 0} 
                  className={`${bankAction === 'pay' ? "bg-red-500 shadow-red-500/20" : "bg-emerald-500 shadow-emerald-500/20"} rounded-2xl h-14 text-lg shadow-xl`}
                >
                  {bankAction === 'pay' ? 'Pay Bank' : 'Collect Funds'}
                </Button>
              </div>
            </form>
          )}

          {activeTab === 'go' && (
            <div className="space-y-8 text-center">
              <div className="bg-emerald-500/10 border border-emerald-500/20 rounded-[2rem] p-8 space-y-2">
                <span className="text-4xl">🏁</span>
                <h3 className="text-2xl font-black text-emerald-400">Collect {formatMoneyDisplay(passGoAmount)}</h3>
                <p className="text-slate-500 text-xs">Standard Pass GO reward</p>
              </div>
              {renderPlayerSelect(bankPlayerId, setBankPlayerId, undefined, "Select Player")}
              <div className="pt-4 flex gap-3">
                <Button variant="ghost" fullWidth onClick={onClose} className="rounded-2xl">Cancel</Button>
                <Button fullWidth onClick={handlePassGo} disabled={!bankPlayerId} className="bg-emerald-500 rounded-2xl h-14 text-lg shadow-xl shadow-emerald-500/20">Collect GO</Button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default TransactionModal;

import React from 'react';
import { Player, Currency } from '../types';
import { PLAYER_COLORS, PLAYER_BORDER_COLORS } from '../constants';
import { ThemeColor } from '../types';

interface PlayerCardProps {
  player: Player;
  currency: Currency;
  onEditName: (name: string) => void;
  onDragStart: (e: React.PointerEvent, id: string) => void;
  onDeleteClick: (id: string) => void;
  showDeleteButton?: boolean;
  deleteProgress?: number; // 0 to 100
  style?: React.CSSProperties;
  className?: string;
}

const PlayerCard: React.FC<PlayerCardProps> = ({ 
  player, 
  currency, 
  onEditName, 
  onDragStart, 
  onDeleteClick,
  showDeleteButton = false,
  deleteProgress = 0,
  style, 
  className = '' 
}) => {
  const colorKey = player.color as ThemeColor;

  const borderColor = PLAYER_BORDER_COLORS[colorKey] || 'border-slate-500';
  const glowColor = PLAYER_COLORS[colorKey] || 'bg-slate-500';

  const formatMoney = (amount: number) => {
    const abs = Math.abs(amount);
    let displayVal: string;

    if (abs >= 1000000) {
      displayVal = (amount / 1000000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'M';
    } else if (abs >= 10000) {
      displayVal = (amount / 1000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'K';
    } else {
      displayVal = amount.toLocaleString();
    }

    return currency.position === 'prefix' 
      ? `${currency.symbol}${displayVal}`
      : `${displayVal}${currency.symbol}`;
  };

  const isActivating = deleteProgress > 0 && deleteProgress < 100;
  const jiggleClass = showDeleteButton ? 'animate-jiggle' : '';

  return (
    <div 
      className={`absolute flex flex-col items-center touch-none select-none group cursor-grab active:cursor-grabbing ${className} ${jiggleClass}`}
      style={{
        ...style,
        transform: 'translate(-50%, -50%)',
        width: 'max-content',
        transition: isActivating ? 'none' : (style?.transition || 'all 0.4s ease-out'),
        zIndex: showDeleteButton ? 100 : style?.zIndex
      }}
      onPointerDown={(e) => onDragStart(e, player.id)}
      data-id={player.id}
    >
      {/* Avatar Circle */}
      <div 
        className={`relative w-28 h-28 md:w-40 md:h-40 rounded-full border-[6px] md:border-[8px] ${borderColor} shadow-[0_0_30px_rgba(0,0,0,0.6)] z-20 flex items-center justify-center bg-gradient-to-b from-slate-700 to-slate-900`}
      >
        {/* Activation Progress Ring */}
        {isActivating && (
          <div className="absolute inset-0 z-30 pointer-events-none">
            <svg className="w-full h-full rotate-[-90deg]">
              <circle
                cx="50%"
                cy="50%"
                r="48%"
                fill="transparent"
                stroke="rgba(34, 211, 238, 0.6)"
                strokeWidth="8"
                strokeDasharray="301.6"
                strokeDashoffset={301.6 - (301.6 * deleteProgress) / 100}
                className="transition-all duration-75 ease-linear"
              />
            </svg>
          </div>
        )}

        {/* Delete Button (X) - Layered for High Response */}
        {showDeleteButton && (
          <button
            onPointerDown={(e) => {
              e.stopPropagation();
            }} 
            onPointerUp={(e) => {
              e.stopPropagation();
              onDeleteClick(player.id);
            }}
            className="absolute -top-3 -right-3 w-12 h-12 md:w-16 md:h-16 bg-red-600 border-4 border-slate-900 rounded-full flex items-center justify-center text-white shadow-[0_8px_20px_rgba(220,38,38,0.5)] z-[110] hover:bg-red-500 hover:scale-110 active:scale-90 transition-all animate-pop-in pointer-events-auto"
          >
            <svg className="w-7 h-7 md:w-9 md:h-9" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        )}

        <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-white/10 to-transparent pointer-events-none"></div>
        <div className={`absolute -inset-2 rounded-full opacity-0 group-hover:opacity-40 blur-xl transition-opacity duration-300 ${glowColor}`}></div>

        <span className="text-5xl md:text-7xl relative z-10 filter drop-shadow-lg select-none leading-none transform group-hover:rotate-6 transition-transform">
          {player.avatar}
        </span>

        {player.isBankrupt && (
          <div className="absolute inset-0 bg-black/80 rounded-full flex items-center justify-center z-40 border-4 border-red-600">
            <span className="text-4xl md:text-6xl">💀</span>
          </div>
        )}
      </div>

      {/* Info Pill */}
      <div className={`mt-3 flex flex-col items-center z-30 filter drop-shadow-xl scale-125 md:scale-150 origin-top transition-all ${showDeleteButton ? 'opacity-30 blur-[2px]' : 'opacity-100'}`}>
        <div className="bg-slate-900/90 backdrop-blur-md rounded-t-lg px-2 py-0.5 text-[10px] md:text-xs text-white font-bold text-center w-20 md:w-24 border-b border-white/10 truncate">
          {player.name}
        </div>
        <div className={`bg-slate-800/95 backdrop-blur-md border border-t-0 border-white/10 rounded-b-lg px-2 py-0.5 min-w-[5rem] md:min-w-[6rem] text-center shadow-md ${player.balance < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
          <span className="text-xs md:text-sm font-black font-mono tracking-tight">
            {formatMoney(player.balance)}
          </span>
        </div>
      </div>

      <style>{`
        @keyframes jiggle {
          0% { transform: translate(-50%, -50%) rotate(-1deg); }
          50% { transform: translate(-50%, -50%) rotate(1deg); }
          100% { transform: translate(-50%, -50%) rotate(-1deg); }
        }
        @keyframes pop-in {
          0% { transform: scale(0); opacity: 0; }
          70% { transform: scale(1.2); opacity: 1; }
          100% { transform: scale(1); opacity: 1; }
        }
        .animate-jiggle { animation: jiggle 0.3s infinite ease-in-out; }
        .animate-pop-in { animation: pop-in 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
      `}</style>
    </div>
  );
};

export default PlayerCard;

import React, { useState, useEffect, useRef } from 'react';
import { Player, Transaction, TransactionType, ThemeColor, Currency, GameSettings } from './types';
import { DEFAULT_STARTING_BALANCE, DEFAULT_PASS_GO_AMOUNT, PLAYER_COLORS, CURRENCIES, AVATARS } from './constants';
import PlayerCard from './components/PlayerCard';
import BankCard from './components/BankCard';
import TransactionModal from './components/TransactionModal';
import HistoryLogModal from './components/HistoryLogModal';
import RulesBot from './components/RulesBot';
import Button from './components/Button';
import PlayerFormModal from './components/PlayerFormModal';
import AnalysisModal from './components/AnalysisModal';

const generateId = () => Math.random().toString(36).substr(2, 9);
const REVEAL_DELETE_THRESHOLD_MS = 600;

const App: React.FC = () => {
  // --- State ---

  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [gameSettings, setGameSettings] = useState<GameSettings>({
    startingBalance: DEFAULT_STARTING_BALANCE,
    passGoAmount: DEFAULT_PASS_GO_AMOUNT
  });

  const [players, setPlayers] = useState<Player[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [gameStarted, setGameStarted] = useState(false);

  const [modalState, setModalState] = useState<{
    isOpen: boolean;
    initialFromId?: string;
    initialToId?: string;
  }>({ isOpen: false });

  const [isRulesOpen, setIsRulesOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isAnalysisOpen, setIsAnalysisOpen] = useState(false);
  const [playerFormState, setPlayerFormState] = useState<{
    isOpen: boolean;
    playerToEdit?: Player;
  }>({ isOpen: false });

  // Long Press State
  const [deleteState, setDeleteState] = useState<{ 
    id: string | null; 
    progress: number;
    revealedId: string | null; 
  }>({ id: null, progress: 0, revealedId: null });
  const deleteTimerRef = useRef<number | null>(null);

  const [dragVisual, setDragVisual] = useState<{
    isDragging: boolean;
    startX: number;
    startY: number;
    currX: number;
    currY: number;
  }>({
    isDragging: false,
    startX: 0,
    startY: 0,
    currX: 0,
    currY: 0,
  });

  const dragRef = useRef<{
    isDragging: boolean;
    sourceId: string | null;
    startX: number;
    startY: number;
    hasMoved: boolean;
  }>({
    isDragging: false,
    sourceId: null,
    startX: 0,
    startY: 0,
    hasMoved: false
  });

  const boardRef = useRef<HTMLDivElement>(null);
  const [playerPositions, setPlayerPositions] = useState<{ [key: string]: { x: number, y: number } }>({});

  // --- Persistence ---

  useEffect(() => {
    const savedGame = localStorage.getItem('bankair_state_v1');
    if (savedGame) {
      try {
        const parsed = JSON.parse(savedGame);
        setPlayers(parsed.players || []);
        setTransactions(parsed.transactions || []);
        setGameStarted(parsed.gameStarted || false);
        setCurrency(parsed.currency || CURRENCIES[0]);
        setGameSettings(parsed.settings || { startingBalance: DEFAULT_STARTING_BALANCE, passGoAmount: DEFAULT_PASS_GO_AMOUNT });
      } catch (e) {
        console.error("Failed to load save", e);
      }
    }
  }, []);

  useEffect(() => {
    const stateToSave = {
      players,
      transactions,
      gameStarted,
      currency,
      settings: gameSettings
    };
    localStorage.setItem('bankair_state_v1', JSON.stringify(stateToSave));
  }, [players, transactions, gameStarted, currency, gameSettings]);

  // --- Logic ---

  const formatMoney = (amount: number) => {
    const abs = Math.abs(amount);
    let val: string;
    if (abs >= 1000000) val = (amount / 1000000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'M';
    else if (abs >= 10000) val = (amount / 1000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'K';
    else val = amount.toLocaleString();

    return currency.position === 'prefix' ? `${currency.symbol}${val}` : `${val}${currency.symbol}`;
  };

  const parseMoneyInput = (val: string) => {
    const clean = val.replace(/,/g, '').replace(/[^0-9]/g, '');
    return clean ? parseInt(clean) : 0;
  };

  const handleStartGame = () => {
    if (players.length < 2) return;
    const resetPlayers = players.map(p => ({
      ...p,
      balance: gameSettings.startingBalance,
      isBankrupt: false
    }));
    setPlayers(resetPlayers);
    setTransactions([]);
    setGameStarted(true);
  };

  const handleEndGame = () => {
    if (window.confirm("End current game? All transaction history for this session will be cleared.")) {
      setGameStarted(false);
    }
  };

  const handleDeletePlayer = (id: string) => {
    if (players.length <= 2 && gameStarted) {
      alert("Minimum 2 players required for an active game.");
      return;
    }
    if (window.confirm("Remove this player from the game?")) {
      setPlayers(prev => prev.filter(p => p.id !== id));
      setDeleteState(prev => ({ ...prev, revealedId: null }));
      if (window.navigator.vibrate) window.navigator.vibrate([30, 30, 30]);
    }
  };

  const handleAddPlayer = () => {
    if (players.length >= 6) return;
    const count = players.length + 1;
    const randomAvatar = AVATARS[Math.floor(Math.random() * AVATARS.length)];
    const colorKeys = Object.keys(PLAYER_COLORS) as ThemeColor[];
    const randomColor = colorKeys[Math.floor(Math.random() * colorKeys.length)];

    const newPlayer: Player = {
      id: generateId(),
      name: `Player ${count}`,
      avatar: randomAvatar,
      balance: gameStarted ? gameSettings.startingBalance : 0,
      color: randomColor,
      isBankrupt: false
    };
    setPlayers([...players, newPlayer]);
  };

  const handleUpdatePlayerName = (id: string, name: string) => {
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const handleUpdatePlayerAppearance = (data: Partial<Player>) => {
    const editId = playerFormState.playerToEdit?.id;
    if (editId) {
      setPlayers(prev => prev.map(p => 
        p.id === editId ? { ...p, ...data } : p
      ));
    }
  };

  // --- Transactions ---

  const handleTransaction = (type: TransactionType, fromId: string, toId: string, amount: number) => {
    const newTx: Transaction = {
      id: generateId(),
      timestamp: Date.now(),
      type,
      fromId,
      toId,
      amount,
      isReverted: false
    };

    setTransactions(prev => [...prev, newTx]);
    applyTransactionEffect(newTx, false);
  };

  const handleToggleTransaction = (id: string) => {
    const txIndex = transactions.findIndex(t => t.id === id);
    if (txIndex === -1) return;

    const tx = transactions[txIndex];
    const isReverting = !tx.isReverted;

    const updatedTransactions = [...transactions];
    updatedTransactions[txIndex] = { ...tx, isReverted: isReverting };
    setTransactions(updatedTransactions);

    applyTransactionEffect(tx, isReverting);
  };

  const applyTransactionEffect = (tx: Transaction, isReversing: boolean) => {
    const { fromId, toId, amount } = tx;

    setPlayers(prevPlayers => prevPlayers.map(p => {
      let newBalance = p.balance;
      if (p.id === fromId) {
        newBalance = isReversing ? p.balance + amount : p.balance - amount;
      }
      if (p.id === toId) {
        newBalance = isReversing ? p.balance - amount : p.balance + amount;
      }
      return { ...p, balance: newBalance };
    }));
  };

  // --- Layout Calculation ---

  useEffect(() => {
    if (!gameStarted || !boardRef.current) return;

    const updatePositions = () => {
      if (!boardRef.current) return;

      const { width, height } = boardRef.current.getBoundingClientRect();
      if (width === 0 || height === 0) {
        requestAnimationFrame(updatePositions);
        return;
      }

      const cx = width / 2;
      const cy = height / 2;

      const isMobile = width < 768;
      const paddingX = isMobile ? 85 : 180;
      const paddingY = isMobile ? 130 : 180;

      const rx = (width / 2) - paddingX;
      const ry = (height / 2) - paddingY;

      if (rx <= 20 || ry <= 20) return;

      const newPositions: { [key: string]: { x: number, y: number } } = {};
      const numPlayers = players.length;

      const startAngle = numPlayers === 4 ? -Math.PI / 4 : -Math.PI / 2;

      players.forEach((player, index) => {
        const angle = (index / numPlayers) * 2 * Math.PI + startAngle; 
        newPositions[player.id] = {
          x: cx + rx * Math.cos(angle),
          y: cy + ry * Math.sin(angle)
        };
      });

      setPlayerPositions(newPositions);
    };

    const timer = setTimeout(updatePositions, 100);
    const observer = new ResizeObserver(() => requestAnimationFrame(updatePositions));
    observer.observe(boardRef.current);

    return () => {
      clearTimeout(timer);
      observer.disconnect();
    };
  }, [players.length, gameStarted]);

  // --- Interaction Logic ---

  const startDeleteTimer = (id: string) => {
    if (id === 'BANK') return;

    setDeleteState(prev => ({ ...prev, id, progress: 0 }));
    const startTime = Date.now();

    if (deleteTimerRef.current) clearInterval(deleteTimerRef.current);

    deleteTimerRef.current = window.setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min((elapsed / REVEAL_DELETE_THRESHOLD_MS) * 100, 100);

      setDeleteState(prev => ({ ...prev, progress }));

      if (progress >= 100) {
        clearInterval(deleteTimerRef.current!);
        deleteTimerRef.current = null;
        if (window.navigator.vibrate) window.navigator.vibrate(50);
        setDeleteState(prev => ({ ...prev, id: null, progress: 0, revealedId: id }));
      }
    }, 50);
  };

  const cancelDeleteTimer = () => {
    if (deleteTimerRef.current) {
      clearInterval(deleteTimerRef.current);
      deleteTimerRef.current = null;
    }
    setDeleteState(prev => ({ ...prev, id: null, progress: 0 }));
  };

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return;

    if (deleteState.revealedId && deleteState.revealedId !== id) {
       setDeleteState(prev => ({ ...prev, revealedId: null }));
    }

    const clientX = e.clientX;
    const clientY = e.clientY;

    dragRef.current = {
      isDragging: true,
      sourceId: id,
      startX: clientX,
      startY: clientY,
      hasMoved: false
    };

    setDragVisual({
      isDragging: true,
      startX: clientX,
      startY: clientY,
      currX: clientX,
      currY: clientY
    });

    startDeleteTimer(id);

    try {
      (e.target as Element).setPointerCapture(e.pointerId);
    } catch (err) { }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!dragRef.current.isDragging) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;

    if (Math.abs(dx) > 15 || Math.abs(dy) > 15) {
      dragRef.current.hasMoved = true;
      cancelDeleteTimer();
    }

    setDragVisual(prev => ({ ...prev, currX: e.clientX, currY: e.clientY }));
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    cancelDeleteTimer();
    if (!dragRef.current.isDragging) return;
    const { sourceId, hasMoved } = dragRef.current;

    if (!hasMoved && sourceId) {
      if (sourceId === 'BANK') {
        setIsHistoryOpen(true);
      } else {
        if (deleteState.revealedId === sourceId) {
           setDeleteState(prev => ({ ...prev, revealedId: null }));
        } else {
           const player = players.find(p => p.id === sourceId);
           if (player) setPlayerFormState({ isOpen: true, playerToEdit: player });
        }
      }
    } 
    else if (hasMoved && sourceId) {
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetElement = elements.find(el => el.getAttribute('data-id'));
      const targetId = targetElement?.getAttribute('data-id');

      if (targetId && targetId !== sourceId) {
        setModalState({ isOpen: true, initialFromId: sourceId, initialToId: targetId });
      }
    }

    dragRef.current = { isDragging: false, sourceId: null, startX: 0, startY: 0, hasMoved: false };
    setDragVisual(prev => ({ ...prev, isDragging: false }));
    try {
      (e.target as Element).releasePointerCapture(e.pointerId);
    } catch (err) { }
  };

  const handleBoardPointerDown = (e: React.PointerEvent) => {
    if (deleteState.revealedId) {
      setDeleteState(prev => ({ ...prev, revealedId: null }));
    }
  };

  if (!gameStarted) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 flex flex-col items-center p-4 md:p-8 font-sans text-slate-100 overflow-y-auto">
        <div className="w-full max-w-2xl space-y-8">
          <div className="text-center space-y-2 py-8">
            <h1 className="text-7xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-600 drop-shadow-2xl tracking-tighter">
              PolyBank
            </h1>
            <p className="text-slate-400 text-xl font-medium tracking-tight">AI Monopoly Banking System</p>
          </div>

          <div className="glass-panel rounded-[2rem] p-8 shadow-2xl space-y-8 border-white/5 bg-white/5">
            <div className="flex items-center gap-4 border-b border-white/10 pb-6">
              <span className="text-3xl">⚙️</span>
              <h2 className="text-2xl font-black text-white tracking-tight">Rules Configuration</h2>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-3">
                <label className="text-xs font-black text-blue-300 uppercase tracking-[0.2em]">Initial Balance</label>
                <div className="relative">
                  <span className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-500 text-lg font-mono">
                    {currency.position === 'prefix' ? currency.symbol : ''}
                  </span>
                  <input 
                    type="text" 
                    value={gameSettings.startingBalance.toLocaleString()}
                    onChange={(e) => setGameSettings({...gameSettings, startingBalance: parseMoneyInput(e.target.value)})}
                    className="w-full bg-black/40 border border-white/10 rounded-2xl py-5 px-12 text-white font-mono text-xl focus:ring-4 focus:ring-cyan-500/20 outline-none transition-all"
                  />
                </div>
              </div>
              <div className="space-y-3">
                <label className="text-xs font-black text-blue-300 uppercase tracking-[0.2em]">GO Reward</label>
                <div className="relative">
                  <span className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-500 text-lg font-mono">
                    {currency.position === 'prefix' ? currency.symbol : ''}
                  </span>
                  <input 
                    type="text" 
                    value={gameSettings.passGoAmount.toLocaleString()}
                    onChange={(e) => setGameSettings({...gameSettings, passGoAmount: parseMoneyInput(e.target.value)})}
                    className="w-full bg-black/40 border border-white/10 rounded-2xl py-5 px-12 text-white font-mono text-xl focus:ring-4 focus:ring-cyan-500/20 outline-none transition-all"
                  />
                </div>
              </div>
              <div className="space-y-3 md:col-span-2">
                <label className="text-xs font-black text-blue-300 uppercase tracking-[0.2em]">Game Currency</label>
                <select 
                  value={currency.symbol}
                  onChange={(e) => setCurrency(CURRENCIES.find(c => c.symbol === e.target.value) || CURRENCIES[0])}
                  className="w-full bg-black/40 border border-white/10 rounded-2xl py-5 px-6 text-white text-lg focus:ring-4 focus:ring-cyan-500/20 outline-none appearance-none cursor-pointer"
                >
                  {CURRENCIES.map(c => <option key={c.symbol} value={c.symbol} className="bg-slate-900">{c.name}</option>)}
                </select>
              </div>
            </div>
          </div>

          <div className="glass-panel rounded-[2rem] p-8 shadow-2xl space-y-6 border-white/5 bg-white/5">
            <div className="flex items-center justify-between border-b border-white/10 pb-6">
               <div className="flex items-center gap-4">
                <span className="text-3xl">👥</span>
                <h2 className="text-2xl font-black text-white tracking-tight">Players ({players.length}/6)</h2>
              </div>
               <button 
                onClick={handleAddPlayer}
                disabled={players.length >= 6}
                className="bg-cyan-500 hover:bg-cyan-400 text-white p-3 rounded-2xl shadow-lg shadow-cyan-500/20 transition-all disabled:opacity-20 active:scale-90"
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" />
                </svg>
              </button>
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {players.map((player) => (
                <div 
                  key={player.id} 
                  className="flex items-center gap-4 bg-white/5 p-4 rounded-2xl border border-white/5 hover:bg-white/10 transition-all group"
                >
                  <button 
                    onClick={() => setPlayerFormState({ isOpen: true, playerToEdit: player })}
                    className="text-4xl bg-black/20 p-2 rounded-xl group-hover:scale-110 transition-transform"
                  >
                    {player.avatar}
                  </button>
                  <div className="flex-1 min-w-0">
                     <input
                      type="text"
                      value={player.name}
                      onChange={(e) => handleUpdatePlayerName(player.id, e.target.value)}
                      className="bg-transparent text-white font-black w-full outline-none border-b border-transparent focus:border-cyan-400 truncate"
                    />
                  </div>
                  <button 
                    onClick={() => handleDeletePlayer(player.id)}
                    className="text-slate-600 hover:text-red-500 transition-colors p-2"
                  >
                    <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                    </svg>
                  </button>
                </div>
              ))}
              {players.length === 0 && <div className="col-span-2 text-center text-slate-500 py-6 italic font-medium">Add at least 2 players to begin...</div>}
            </div>
          </div>

          <Button fullWidth size="lg" onClick={handleStartGame} disabled={players.length < 2} className="rounded-[2rem] !py-6 !text-2xl !font-black !bg-gradient-to-r !from-cyan-500 !to-blue-600 !shadow-[0_20px_40px_rgba(6,182,212,0.3)] hover:scale-[1.02] active:scale-95 transition-all">
            Start Session 🚀
          </Button>
        </div>

        <PlayerFormModal 
          isOpen={playerFormState.isOpen}
          onClose={() => setPlayerFormState({ isOpen: false, playerToEdit: undefined })}
          initialData={playerFormState.playerToEdit}
          onSave={handleUpdatePlayerAppearance}
        />
      </div>
    );
  }

  return (
    <div 
      className="fixed inset-0 bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 overflow-hidden font-sans text-slate-100 touch-none"
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onPointerDown={handleBoardPointerDown}
      onContextMenu={(e) => e.preventDefault()}
    >
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-blue-900/10 via-transparent to-transparent pointer-events-none"></div>

      {/* HUD Header */}
      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between items-start z-[100] pointer-events-none">
        <div className="flex gap-3 pointer-events-auto">
          <button onClick={handleEndGame} className="bg-black/40 hover:bg-red-500/20 text-slate-400 p-4 rounded-3xl backdrop-blur-xl border border-white/10 shadow-2xl group transition-all">
            <svg className="w-6 h-6 group-hover:scale-110" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
          </button>

          {players.length < 6 && (
             <button onClick={handleAddPlayer} className="bg-black/40 hover:bg-cyan-500/20 text-slate-400 p-4 rounded-3xl backdrop-blur-xl border border-white/10 shadow-2xl transition-all">
               <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                 <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" />
               </svg>
             </button>
          )}
        </div>

        <div className="flex gap-3 pointer-events-auto">
          <button onClick={() => setIsAnalysisOpen(true)} className="bg-purple-600/90 text-white p-4 rounded-3xl shadow-2xl hover:scale-105 active:scale-95 transition-all"><span className="text-2xl">🔮</span></button>
          <button onClick={() => setIsRulesOpen(true)} className="bg-black/40 text-slate-400 p-4 rounded-3xl backdrop-blur-xl border border-white/10 shadow-2xl hover:text-white transition-all"><span className="text-2xl">⚖️</span></button>
          <button onClick={() => setIsHistoryOpen(true)} className="bg-black/40 text-slate-400 p-4 rounded-3xl backdrop-blur-xl border border-white/10 shadow-2xl hover:text-white transition-all"><span className="text-2xl">📜</span></button>
        </div>
      </div>

      <div ref={boardRef} className="absolute inset-0 z-0">
        <BankCard currency={currency} onDragStart={handlePointerDown} />

        {players.map((player) => (
          <PlayerCard 
            key={player.id}
            player={player}
            currency={currency}
            onEditName={handleUpdatePlayerName}
            onDragStart={handlePointerDown}
            onDeleteClick={handleDeletePlayer}
            showDeleteButton={deleteState.revealedId === player.id}
            deleteProgress={deleteState.id === player.id ? deleteState.progress : 0}
            style={{
              left: playerPositions[player.id]?.x || '50%',
              top: playerPositions[player.id]?.y || '50%',
              opacity: playerPositions[player.id] ? 1 : 0, 
              visibility: playerPositions[player.id] ? 'visible' : 'hidden',
              transition: (deleteState.id === player.id) ? 'none' : 'opacity 0.4s ease-out, left 0.6s cubic-bezier(0.34, 1.56, 0.64, 1), top 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)'
            }}
          />
        ))}
      </div>

      {dragVisual.isDragging && (
        <div className="absolute inset-0 pointer-events-none z-[110]">
          <svg className="w-full h-full filter blur-[1px]">
            <line 
              x1={dragVisual.startX} y1={dragVisual.startY} 
              x2={dragVisual.currX} y2={dragVisual.currY} 
              stroke="url(#drag-grad)" strokeWidth="8" strokeLinecap="round" className="opacity-60"
              strokeDasharray="12 12"
            />
             <defs>
              <linearGradient id="drag-grad" x1="0%" y1="0%" x2="100%" y2="0%">
                <stop offset="0%" stopColor="#22d3ee" />
                <stop offset="100%" stopColor="#818cf8" />
              </linearGradient>
            </defs>
          </svg>
          <div 
            className="absolute w-12 h-12 rounded-full bg-cyan-400 shadow-[0_0_30px_rgba(34,211,238,1)] border-4 border-white transform -translate-x-1/2 -translate-y-1/2 opacity-40 animate-ping"
            style={{ left: dragVisual.currX, top: dragVisual.currY }}
          ></div>
        </div>
      )}

      <TransactionModal 
        isOpen={modalState.isOpen}
        initialFromId={modalState.initialFromId}
        initialToId={modalState.initialToId}
        onClose={() => setModalState({ isOpen: false })}
        players={players}
        currency={currency}
        passGoAmount={gameSettings.passGoAmount}
        onTransaction={handleTransaction}
      />

      <HistoryLogModal 
        isOpen={isHistoryOpen}
        onClose={() => setIsHistoryOpen(false)}
        transactions={transactions}
        players={players}
        currency={currency}
        onToggleTransaction={handleToggleTransaction}
      />

      <RulesBot isOpen={isRulesOpen} onClose={() => setIsRulesOpen(false)} />
      <AnalysisModal isOpen={isAnalysisOpen} onClose={() => setIsAnalysisOpen(false)} players={players} />
      <PlayerFormModal 
        isOpen={playerFormState.isOpen}
        onClose={() => setPlayerFormState({ isOpen: false, playerToEdit: undefined })}
        initialData={playerFormState.playerToEdit}
        onSave={handleUpdatePlayerAppearance}
      />
    </div>
  );
};

