                <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                  <button onClick={() => appendShorthand(setGoInput, goInput, 'K')} className="bg-white/10 hover:bg-white/20 px-2 py-1 rounded text-[10px] font-black">K</button>
