};

export default SettingsModal;

import React, { useState, useEffect, useRef } from 'react';
import { Player, Transaction, TransactionType, ThemeColor, Currency, GameSettings } from './types';
import { DEFAULT_STARTING_BALANCE, DEFAULT_PASS_GO_AMOUNT, PLAYER_COLORS, CURRENCIES, AVATARS } from './constants';
import PlayerCard from './components/PlayerCard';
import BankCard from './components/BankCard';
import TransactionModal from './components/TransactionModal';
import HistoryLogModal from './components/HistoryLogModal';
import RulesBot from './components/RulesBot';
import StrategyModal from './components/StrategyModal';
import Button from './components/Button';
import PlayerFormModal from './components/PlayerFormModal';
import SettingsModal from './components/SettingsModal';
import { getTransactionCommentary } from './services/geminiService';

const generateId = () => Math.random().toString(36).substr(2, 9);
const REVEAL_DELETE_THRESHOLD_MS = 600;

// Utility to parse money shorthand (1.5k -> 1500)
const parseMoneyInput = (val: string): number => {
  const clean = val.toLowerCase().replace(/,/g, '').trim();
  if (!clean) return 0;
  let multiplier = 1;
  let numericPart = clean;
  if (clean.endsWith('m')) {
    multiplier = 1000000;
    numericPart = clean.slice(0, -1);
  } else if (clean.endsWith('k')) {
    multiplier = 1000;
    numericPart = clean.slice(0, -1);
  }
  const num = parseFloat(numericPart);
  return isNaN(num) ? 0 : Math.floor(num * multiplier);
};

const formatFullAmount = (amount: number, currency: Currency) => {
  const formatted = amount.toLocaleString();
  return currency.position === 'prefix' ? `${currency.symbol}${formatted}` : `${formatted}${currency.symbol}`;
};

const App: React.FC = () => {
  // --- State ---
  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [gameSettings, setGameSettings] = useState<GameSettings>({
    startingBalance: DEFAULT_STARTING_BALANCE,
    passGoAmount: DEFAULT_PASS_GO_AMOUNT
  });

  const [setupBalanceInput, setSetupBalanceInput] = useState(DEFAULT_STARTING_BALANCE.toString());
  const [setupGoInput, setSetupGoInput] = useState(DEFAULT_PASS_GO_AMOUNT.toString());

  const [players, setPlayers] = useState<Player[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [gameStarted, setGameStarted] = useState(false);

  const [modalState, setModalState] = useState<{
    isOpen: boolean;
    initialFromId?: string;
    initialToId?: string;
  }>({ isOpen: false });

  const [isRulesOpen, setIsRulesOpen] = useState(false);
  const [isStrategyOpen, setIsStrategyOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [playerFormState, setPlayerFormState] = useState<{
    isOpen: boolean;
    playerToEdit?: Player;
  }>({ isOpen: false });

  // AI Commentary State
  const [liveCommentary, setLiveCommentary] = useState<{text: string, id: string} | null>(null);
  const commentaryTimeoutRef = useRef<number | null>(null);

  // Long Press & Drag State
  const [deleteState, setDeleteState] = useState<{ 
    id: string | null; 
    progress: number;
    revealedId: string | null; 
  }>({ id: null, progress: 0, revealedId: null });
  const deleteTimerRef = useRef<number | null>(null);

  const [dragVisual, setDragVisual] = useState<{
    isDragging: boolean;
    startX: number;
    startY: number;
    currX: number;
    currY: number;
  }>({
    isDragging: false,
    startX: 0,
    startY: 0,
    currX: 0,
    currY: 0,
  });

  const dragRef = useRef<{
    isDragging: boolean;
    sourceId: string | null;
    startX: number;
    startY: number;
    hasMoved: boolean;
  }>({
    isDragging: false,
    sourceId: null,
    startX: 0,
    startY: 0,
    hasMoved: false
  });

  const boardRef = useRef<HTMLDivElement>(null);
  const [playerPositions, setPlayerPositions] = useState<{ [key: string]: { x: number, y: number } }>({});

  // --- Persistence ---
  useEffect(() => {
    const savedGame = localStorage.getItem('bankair_state_v1');
    if (savedGame) {
      try {
        const parsed = JSON.parse(savedGame);
        setPlayers(parsed.players || []);
        setTransactions(parsed.transactions || []);
        setGameStarted(parsed.gameStarted || false);
        setCurrency(parsed.currency || CURRENCIES[0]);
        const settings = parsed.settings || { startingBalance: DEFAULT_STARTING_BALANCE, passGoAmount: DEFAULT_PASS_GO_AMOUNT };
        setGameSettings(settings);
        setSetupBalanceInput(settings.startingBalance.toString());
        setSetupGoInput(settings.passGoAmount.toString());
      } catch (e) {
        console.error("Failed to load save", e);
      }
    }
  }, []);

  useEffect(() => {
    const stateToSave = {
      players,
      transactions,
      gameStarted,
      currency,
      settings: gameSettings
    };
    localStorage.setItem('bankair_state_v1', JSON.stringify(stateToSave));
  }, [players, transactions, gameStarted, currency, gameSettings]);

  useEffect(() => {
    if (!gameStarted) {
      setGameSettings({
        startingBalance: parseMoneyInput(setupBalanceInput),
        passGoAmount: parseMoneyInput(setupGoInput)
      });
    }
  }, [setupBalanceInput, setupGoInput, gameStarted]);

  // --- Game Control ---
  const handleStartGame = () => {
    if (players.length < 2) return;
    const finalSettings = {
      startingBalance: parseMoneyInput(setupBalanceInput),
      passGoAmount: parseMoneyInput(setupGoInput)
    };
    setGameSettings(finalSettings);
    const resetPlayers = players.map(p => ({
      ...p,
      balance: finalSettings.startingBalance,
      isBankrupt: false
    }));
    setPlayers(resetPlayers);
    setTransactions([]);
    setGameStarted(true);
  };

  const handleResetGame = () => {
    if (window.confirm("Are you sure? This will clear all transactions and reset balances. Player customizations will be kept.")) {
      setTransactions([]);
      setPlayers(prev => prev.map(p => ({
        ...p,
        balance: 0,
        isBankrupt: false
      })));
      setGameStarted(false);
      setIsSettingsOpen(false);
    }
  };

  const handleDeletePlayer = (id: string) => {
    if (players.length <= 2 && gameStarted) {
      alert("Minimum 2 players required.");
      return;
    }
    if (window.confirm("Remove this player?")) {
      setPlayers(prev => prev.filter(p => p.id !== id));
      setDeleteState(prev => ({ ...prev, revealedId: null }));
      if (window.navigator.vibrate) window.navigator.vibrate([20, 40, 20]);
    }
  };

  const handleAddPlayer = () => {
    if (players.length >= 6) return;
    const count = players.length + 1;
    const randomAvatar = AVATARS[Math.floor(Math.random() * AVATARS.length)];
    const colorKeys = Object.keys(PLAYER_COLORS) as ThemeColor[];
    const randomColor = colorKeys[Math.floor(Math.random() * colorKeys.length)];

    const newPlayer: Player = {
      id: generateId(),
      name: `Player ${count}`,
      avatar: randomAvatar,
      balance: gameStarted ? gameSettings.startingBalance : 0,
      color: randomColor,
      isBankrupt: false
    };
    setPlayers([...players, newPlayer]);
  };

  const handleUpdatePlayerName = (id: string, name: string) => {
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const handleUpdatePlayerAppearance = (data: Partial<Player>) => {
    const editId = playerFormState.playerToEdit?.id;
    if (editId) {
      setPlayers(prev => prev.map(p => p.id === editId ? { ...p, ...data } : p));
    }
  };

  const handleTransaction = async (type: TransactionType, fromId: string, toId: string, amount: number) => {
    const sender = fromId === 'BANK' ? 'The Bank' : players.find(p => p.id === fromId)?.name || 'Someone';
    const receiver = toId === 'BANK' ? 'The Bank' : players.find(p => p.id === toId)?.name || 'Someone';

    const newTx: Transaction = {
      id: generateId(),
      timestamp: Date.now(),
      type,
      fromId: fromId as any,
      toId: toId as any,
      amount,
      isReverted: false
    };

    // UI Feedback for "thinking"
    setLiveCommentary({ text: "...", id: newTx.id });

    // Attempt AI Commentary
    const comment = await getTransactionCommentary(newTx, players, sender, receiver);
    if (comment) {
      newTx.aiCommentary = comment;
      setLiveCommentary({ text: comment, id: newTx.id });

      // Auto-clear commentary after 8 seconds
      if (commentaryTimeoutRef.current) window.clearTimeout(commentaryTimeoutRef.current);
      commentaryTimeoutRef.current = window.setTimeout(() => setLiveCommentary(null), 8000);
    } else {
      setLiveCommentary(null);
    }

    setTransactions(prev => [...prev, newTx]);
    applyTransactionEffect(newTx, false);
  };

  const applyTransactionEffect = (tx: Transaction, isReversing: boolean) => {
    const { fromId, toId, amount } = tx;
    setPlayers(prevPlayers => prevPlayers.map(p => {
      let newBalance = p.balance;
      if (p.id === fromId) newBalance = isReversing ? p.balance + amount : p.balance - amount;
      if (p.id === toId) newBalance = isReversing ? p.balance - amount : p.balance + amount;
      return { ...p, balance: newBalance };
    }));
  };

  const handleToggleTransaction = (id: string) => {
    const txIndex = transactions.findIndex(t => t.id === id);
    if (txIndex === -1) return;
    const tx = transactions[txIndex];
    const isReverting = !tx.isReverted;
    const updatedTransactions = [...transactions];
    updatedTransactions[txIndex] = { ...tx, isReverted: isReverting };
    setTransactions(updatedTransactions);
    applyTransactionEffect(tx, isReverting);
  };

  // --- Interaction Logic ---
  const startDeleteTimer = (id: string) => {
    if (id === 'BANK') return;
    setDeleteState(prev => ({ ...prev, id, progress: 0 }));
    const startTime = Date.now();
    if (deleteTimerRef.current) clearInterval(deleteTimerRef.current);
    deleteTimerRef.current = window.setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min((elapsed / REVEAL_DELETE_THRESHOLD_MS) * 100, 100);
      setDeleteState(prev => ({ ...prev, progress }));
      if (progress >= 100) {
        clearInterval(deleteTimerRef.current!);
        deleteTimerRef.current = null;
        if (window.navigator.vibrate) window.navigator.vibrate(50);
        setDeleteState(prev => ({ ...prev, id: null, progress: 0, revealedId: id }));
      }
    }, 50);
  };

  const cancelDeleteTimer = () => {
    if (deleteTimerRef.current) {
      clearInterval(deleteTimerRef.current);
      deleteTimerRef.current = null;
    }
    setDeleteState(prev => ({ ...prev, id: null, progress: 0 }));
  };

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return;
    if (deleteState.revealedId && deleteState.revealedId !== id) {
       setDeleteState(prev => ({ ...prev, revealedId: null }));
    }
    const clientX = e.clientX;
    const clientY = e.clientY;
    dragRef.current = { isDragging: true, sourceId: id, startX: clientX, startY: clientY, hasMoved: false };
    setDragVisual({ isDragging: true, startX: clientX, startY: clientY, currX: clientX, currY: clientY });
    startDeleteTimer(id);
    try { (e.target as Element).setPointerCapture(e.pointerId); } catch (err) { }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!dragRef.current.isDragging) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;
    if (Math.abs(dx) > 15 || Math.abs(dy) > 15) {
      dragRef.current.hasMoved = true;
      cancelDeleteTimer();
    }
    setDragVisual(prev => ({ ...prev, currX: e.clientX, currY: e.clientY }));
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    cancelDeleteTimer();
    if (!dragRef.current.isDragging) return;
    const { sourceId, hasMoved } = dragRef.current;
    if (!hasMoved && sourceId) {
      if (sourceId === 'BANK') setIsHistoryOpen(true);
      else if (deleteState.revealedId !== sourceId) {
        const player = players.find(p => p.id === sourceId);
        if (player) setPlayerFormState({ isOpen: true, playerToEdit: player });
      }
    } else if (hasMoved && sourceId) {
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetId = elements.find(el => el.getAttribute('data-id'))?.getAttribute('data-id');
      if (targetId && targetId !== sourceId) {
        setModalState({ isOpen: true, initialFromId: sourceId, initialToId: targetId });
      }
    }
    dragRef.current = { isDragging: false, sourceId: null, startX: 0, startY: 0, hasMoved: false };
    setDragVisual(prev => ({ ...prev, isDragging: false }));
    try { (e.target as Element).releasePointerCapture(e.pointerId); } catch (err) { }
  };

  useEffect(() => {
    if (!gameStarted || !boardRef.current) return;
    const updatePositions = () => {
      if (!boardRef.current) return;
      const { width, height } = boardRef.current.getBoundingClientRect();
      if (width === 0) return;
      const cx = width / 2;
      const cy = height / 2;
      const isMobile = width < 768;
      const rx = (width / 2) - (isMobile ? 85 : 180);
      const ry = (height / 2) - (isMobile ? 130 : 180);
      if (rx <= 20 || ry <= 20) return;
      const newPositions: { [key: string]: { x: number, y: number } } = {};
      const numPlayers = players.length;
      const startAngle = numPlayers === 4 ? -Math.PI / 4 : -Math.PI / 2;
      players.forEach((player, index) => {
        const angle = (index / numPlayers) * 2 * Math.PI + startAngle; 
        newPositions[player.id] = { x: cx + rx * Math.cos(angle), y: cy + ry * Math.sin(angle) };
      });
      setPlayerPositions(newPositions);
    };
    updatePositions();
    const observer = new ResizeObserver(() => updatePositions());
    observer.observe(boardRef.current);
    return () => observer.disconnect();
  }, [players.length, gameStarted]);

  // Helper to append shorthand
  const appendShorthand = (setter: React.Dispatch<React.SetStateAction<string>>, current: string, unit: 'K' | 'M') => {
    const upper = current.toUpperCase();
    if (!upper.endsWith('K') && !upper.endsWith('M')) {
      setter(current + unit);
    } else {
      setter(current.slice(0, -1) + unit);
    }
  };

  if (!gameStarted) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 flex flex-col items-center p-4 md:p-8 font-sans text-slate-100 overflow-y-auto">
        <div className="w-full max-w-2xl space-y-8">
          <div className="text-center space-y-2 py-8">
            <h1 className="text-7xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-600 drop-shadow-2xl tracking-tighter">PolyBank</h1>
            <p className="text-slate-400 text-xl font-medium tracking-tight">Lite Banking Assistant</p>
          </div>

          <div className="glass-panel rounded-[2rem] p-8 shadow-2xl space-y-8 border-white/5 bg-white/5">
            <div className="flex items-center gap-4 border-b border-white/10 pb-6">
              <span className="text-3xl">⚙️</span>
              <h2 className="text-2xl font-black text-white tracking-tight">Game Configuration</h2>
            </div>

            <div className="space-y-4">
              <label className="text-xs font-black text-blue-300 uppercase tracking-[0.2em]">Select Currency</label>
              <div className="grid grid-cols-4 sm:grid-cols-8 gap-2">
                {CURRENCIES.map((c) => (
                  <button
                    key={c.name}
                    onClick={() => setCurrency(c)}
                    className={`flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all ${
                      currency.name === c.name 
                        ? 'bg-cyan-500 border-cyan-400 shadow-lg shadow-cyan-500/20' 
                        : 'bg-white/5 border-white/5 hover:border-white/10 text-slate-400'
                    }`}
                  >
                    <span className="text-xl font-black">{c.symbol}</span>
                    <span className="text-[8px] mt-1 font-bold truncate w-full text-center">{c.name.split(' ')[0]}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-3">
                <label className="text-xs font-black text-blue-300 uppercase tracking-[0.2em]">Initial Balance</label>
                <div className="relative">
                  <input 
                    type="text" 
                    inputMode="numeric"
                    pattern="[0-9]*"
                    value={setupBalanceInput}
                    onChange={(e) => setSetupBalanceInput(e.target.value)}
                    className="w-full bg-black/40 border border-white/10 rounded-2xl py-5 pl-6 pr-16 text-white font-mono text-xl focus:ring-4 focus:ring-cyan-500/20 outline-none uppercase transition-all"
                    placeholder="e.g. 1.5M"
                  />
                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                    <button onClick={() => appendShorthand(setSetupBalanceInput, setupBalanceInput, 'K')} className="bg-white/10 hover:bg-white/20 px-2 py-1 rounded text-[10px] font-black">K</button>
                    <button onClick={() => appendShorthand(setSetupBalanceInput, setupBalanceInput, 'M')} className="bg-white/10 hover:bg-white/20 px-2 py-1 rounded text-[10px] font-black">M</button>
                  </div>
                  <div className="absolute left-6 -bottom-5 text-[10px] font-black text-cyan-400 opacity-60">
                    {formatFullAmount(parseMoneyInput(setupBalanceInput), currency)}
                  </div>
                </div>
              </div>
              <div className="space-y-3">
                <label className="text-xs font-black text-blue-300 uppercase tracking-[0.2em]">GO Reward</label>
                <div className="relative">
                  <input 
                    type="text" 
                    inputMode="numeric"
                    pattern="[0-9]*"
                    value={setupGoInput}
                    onChange={(e) => setSetupGoInput(e.target.value)}
                    className="w-full bg-black/40 border border-white/10 rounded-2xl py-5 pl-6 pr-16 text-white font-mono text-xl focus:ring-4 focus:ring-cyan-500/20 outline-none uppercase transition-all"
                    placeholder="e.g. 200"
                  />
                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                    <button onClick={() => appendShorthand(setSetupGoInput, setupGoInput, 'K')} className="bg-white/10 hover:bg-white/20 px-2 py-1 rounded text-[10px] font-black">K</button>
                    <button onClick={() => appendShorthand(setSetupGoInput, setupGoInput, 'M')} className="bg-white/10 hover:bg-white/20 px-2 py-1 rounded text-[10px] font-black">M</button>
                  </div>
                  <div className="absolute left-6 -bottom-5 text-[10px] font-black text-cyan-400 opacity-60">
                    {formatFullAmount(parseMoneyInput(setupGoInput), currency)}
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="glass-panel rounded-[2rem] p-8 shadow-2xl space-y-6 border-white/5 bg-white/5">
            <div className="flex items-center justify-between border-b border-white/10 pb-6">
