export default SettingsModal;

import React, { useState, useEffect, useRef } from 'react';
import { Player, Transaction, TransactionType, ThemeColor, Currency, GameSettings } from './types';
import { DEFAULT_STARTING_BALANCE, DEFAULT_PASS_GO_AMOUNT, PLAYER_COLORS, CURRENCIES, AVATARS } from './constants';
import PlayerCard from './components/PlayerCard';
import BankCard from './components/BankCard';
import TransactionModal from './components/TransactionModal';
import HistoryLogModal from './components/HistoryLogModal';
import RulesBot from './components/RulesBot';
import StrategyModal from './components/StrategyModal';
import Button from './components/Button';
import PlayerFormModal from './components/PlayerFormModal';
import SettingsModal from './components/SettingsModal';
import { getTransactionCommentary } from './services/geminiService';

const generateId = () => Math.random().toString(36).substr(2, 9);
const REVEAL_DELETE_THRESHOLD_MS = 600;

// Utility to parse money shorthand (1.5k -> 1500)
const parseMoneyInput = (val: string): number => {
  const clean = val.toLowerCase().replace(/,/g, '').trim();
  if (!clean) return 0;
  let multiplier = 1;
  let numericPart = clean;
  if (clean.endsWith('m')) {
    multiplier = 1000000;
    numericPart = clean.slice(0, -1);
  } else if (clean.endsWith('k')) {
    multiplier = 1000;
    numericPart = clean.slice(0, -1);
  }
  const num = parseFloat(numericPart);
  return isNaN(num) ? 0 : Math.floor(num * multiplier);
};

const formatFullAmount = (amount: number, currency: Currency) => {
  const formatted = amount.toLocaleString();
  return currency.position === 'prefix' ? `${currency.symbol}${formatted}` : `${formatted}${currency.symbol}`;
};

const App: React.FC = () => {
  // --- State ---
  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [gameSettings, setGameSettings] = useState<GameSettings>({
    startingBalance: DEFAULT_STARTING_BALANCE,
    passGoAmount: DEFAULT_PASS_GO_AMOUNT
  });

  const [setupBalanceInput, setSetupBalanceInput] = useState(DEFAULT_STARTING_BALANCE.toString());
  const [setupGoInput, setSetupGoInput] = useState(DEFAULT_PASS_GO_AMOUNT.toString());

  const [players, setPlayers] = useState<Player[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [gameStarted, setGameStarted] = useState(false);

  const [modalState, setModalState] = useState<{
    isOpen: boolean;
    initialFromId?: string;
    initialToId?: string;
  }>({ isOpen: false });

  const [isRulesOpen, setIsRulesOpen] = useState(false);
  const [isStrategyOpen, setIsStrategyOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [playerFormState, setPlayerFormState] = useState<{
    isOpen: boolean;
    playerToEdit?: Player;
  }>({ isOpen: false });

  // AI Commentary State
  const [liveCommentary, setLiveCommentary] = useState<{text: string, id: string} | null>(null);
  const commentaryTimeoutRef = useRef<number | null>(null);

  // Long Press & Drag State
  const [deleteState, setDeleteState] = useState<{ 
    id: string | null; 
    progress: number;
    revealedId: string | null; 
  }>({ id: null, progress: 0, revealedId: null });
  const deleteTimerRef = useRef<number | null>(null);

  const [dragVisual, setDragVisual] = useState<{
    isDragging: boolean;
    startX: number;
    startY: number;
    currX: number;
    currY: number;
  }>({
    isDragging: false,
    startX: 0,
    startY: 0,
    currX: 0,
    currY: 0,
  });

  const dragRef = useRef<{
    isDragging: boolean;
    sourceId: string | null;
    startX: number;
    startY: number;
    hasMoved: boolean;
  }>({
    isDragging: false,
    sourceId: null,
    startX: 0,
    startY: 0,
    hasMoved: false
  });

  const boardRef = useRef<HTMLDivElement>(null);
  const [playerPositions, setPlayerPositions] = useState<{ [key: string]: { x: number, y: number } }>({});

  // --- Persistence ---
  useEffect(() => {
    const savedGame = localStorage.getItem('bankair_state_v1');
    if (savedGame) {
      try {
        const parsed = JSON.parse(savedGame);
        setPlayers(parsed.players || []);
        setTransactions(parsed.transactions || []);
        setGameStarted(parsed.gameStarted || false);
        setCurrency(parsed.currency || CURRENCIES[0]);
        const settings = parsed.settings || { startingBalance: DEFAULT_STARTING_BALANCE, passGoAmount: DEFAULT_PASS_GO_AMOUNT };
        setGameSettings(settings);
        setSetupBalanceInput(settings.startingBalance.toString());
        setSetupGoInput(settings.passGoAmount.toString());
      } catch (e) {
        console.error("Failed to load save", e);
      }
    }
  }, []);

  useEffect(() => {
    const stateToSave = {
      players,
      transactions,
      gameStarted,
      currency,
      settings: gameSettings
    };
    localStorage.setItem('bankair_state_v1', JSON.stringify(stateToSave));
  }, [players, transactions, gameStarted, currency, gameSettings]);

  useEffect(() => {
    if (!gameStarted) {
      setGameSettings({
        startingBalance: parseMoneyInput(setupBalanceInput),
        passGoAmount: parseMoneyInput(setupGoInput)
      });
    }
  }, [setupBalanceInput, setupGoInput, gameStarted]);

  // --- Game Control ---
  const handleStartGame = () => {
    if (players.length < 2) return;
    const finalSettings = {
      startingBalance: parseMoneyInput(setupBalanceInput),
      passGoAmount: parseMoneyInput(setupGoInput)
    };
    setGameSettings(finalSettings);
    const resetPlayers = players.map(p => ({
      ...p,
      balance: finalSettings.startingBalance,
      isBankrupt: false
    }));
    setPlayers(resetPlayers);
    setTransactions([]);
    setGameStarted(true);
  };

  const handleResetGame = () => {
    if (window.confirm("Are you sure? This will clear all transactions and reset balances. Player customizations will be kept.")) {
      setTransactions([]);
      setPlayers(prev => prev.map(p => ({
        ...p,
        balance: 0,
        isBankrupt: false
      })));
      setGameStarted(false);
      setIsSettingsOpen(false);
    }
  };

  const handleDeletePlayer = (id: string) => {
    if (players.length <= 2 && gameStarted) {
      alert("Minimum 2 players required.");
      return;
    }
    if (window.confirm("Remove this player?")) {
      setPlayers(prev => prev.filter(p => p.id !== id));
      setDeleteState(prev => ({ ...prev, revealedId: null }));
      if (window.navigator.vibrate) window.navigator.vibrate([20, 40, 20]);
    }
  };

  const handleAddPlayer = () => {
    if (players.length >= 6) return;
    const count = players.length + 1;
    const randomAvatar = AVATARS[Math.floor(Math.random() * AVATARS.length)];
    const colorKeys = Object.keys(PLAYER_COLORS) as ThemeColor[];
    const randomColor = colorKeys[Math.floor(Math.random() * colorKeys.length)];

    const newPlayer: Player = {
      id: generateId(),
      name: `Player ${count}`,
      avatar: randomAvatar,
      balance: gameStarted ? gameSettings.startingBalance : 0,
      color: randomColor,
      isBankrupt: false
    };
    setPlayers([...players, newPlayer]);
  };

  const handleUpdatePlayerName = (id: string, name: string) => {
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const handleUpdatePlayerAppearance = (data: Partial<Player>) => {
    const editId = playerFormState.playerToEdit?.id;
    if (editId) {
      setPlayers(prev => prev.map(p => p.id === editId ? { ...p, ...data } : p));
    }
  };

  const handleTransaction = async (type: TransactionType, fromId: string, toId: string, amount: number) => {
    const sender = fromId === 'BANK' ? 'The Bank' : players.find(p => p.id === fromId)?.name || 'Someone';
    const receiver = toId === 'BANK' ? 'The Bank' : players.find(p => p.id === toId)?.name || 'Someone';

    const newTx: Transaction = {
      id: generateId(),
      timestamp: Date.now(),
      type,
      fromId: fromId as any,
      toId: toId as any,
      amount,
      isReverted: false
    };

    // 1. UPDATE STATE IMMEDIATELY (Banking first)
    setTransactions(prev => [...prev, newTx]);
    applyTransactionEffect(newTx, false);

    // 2. FETCH AI COMMENTARY IN BACKGROUND
    setLiveCommentary({ text: "...", id: newTx.id });

    // We do not 'await' this for the main transaction loop
    getTransactionCommentary(newTx, players, sender, receiver).then(comment => {
      if (comment) {
        // Update transaction in list with commentary
        setTransactions(prev => prev.map(t => t.id === newTx.id ? { ...t, aiCommentary: comment } : t));
        setLiveCommentary({ text: comment, id: newTx.id });

        if (commentaryTimeoutRef.current) window.clearTimeout(commentaryTimeoutRef.current);
        commentaryTimeoutRef.current = window.setTimeout(() => setLiveCommentary(null), 8000);
      } else {
        setLiveCommentary(null);
      }
    }).catch(() => {
      setLiveCommentary(null);
    });
  };

  const applyTransactionEffect = (tx: Transaction, isReversing: boolean) => {
    const { fromId, toId, amount } = tx;
    setPlayers(prevPlayers => prevPlayers.map(p => {
      let newBalance = p.balance;
      if (p.id === fromId) newBalance = isReversing ? p.balance + amount : p.balance - amount;
      if (p.id === toId) newBalance = isReversing ? p.balance - amount : p.balance + amount;
      return { ...p, balance: newBalance };
    }));
  };

  const handleToggleTransaction = (id: string) => {
    const txIndex = transactions.findIndex(t => t.id === id);
    if (txIndex === -1) return;
    const tx = transactions[txIndex];
    const isReverting = !tx.isReverted;
    const updatedTransactions = [...transactions];
    updatedTransactions[txIndex] = { ...tx, isReverted: isReverting };
    setTransactions(updatedTransactions);
    applyTransactionEffect(tx, isReverting);
  };

  // --- Interaction Logic ---
  const startDeleteTimer = (id: string) => {
    if (id === 'BANK') return;
    setDeleteState(prev => ({ ...prev, id, progress: 0 }));
    const startTime = Date.now();
    if (deleteTimerRef.current) clearInterval(deleteTimerRef.current);
    deleteTimerRef.current = window.setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min((elapsed / REVEAL_DELETE_THRESHOLD_MS) * 100, 100);
      setDeleteState(prev => ({ ...prev, progress }));
      if (progress >= 100) {
        clearInterval(deleteTimerRef.current!);
        deleteTimerRef.current = null;
        if (window.navigator.vibrate) window.navigator.vibrate(50);
        setDeleteState(prev => ({ ...prev, id: null, progress: 0, revealedId: id }));
      }
    }, 50);
  };

  const cancelDeleteTimer = () => {
    if (deleteTimerRef.current) {
      clearInterval(deleteTimerRef.current);
      deleteTimerRef.current = null;
    }
    setDeleteState(prev => ({ ...prev, id: null, progress: 0 }));
  };

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return;
    if (deleteState.revealedId && deleteState.revealedId !== id) {
       setDeleteState(prev => ({ ...prev, revealedId: null }));
    }
    const clientX = e.clientX;
    const clientY = e.clientY;
    dragRef.current = { isDragging: true, sourceId: id, startX: clientX, startY: clientY, hasMoved: false };
    setDragVisual({ isDragging: true, startX: clientX, startY: clientY, currX: clientX, currY: clientY });
    startDeleteTimer(id);
    try { (e.target as Element).setPointerCapture(e.pointerId); } catch (err) { }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!dragRef.current.isDragging) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;
    if (Math.abs(dx) > 15 || Math.abs(dy) > 15) {
      dragRef.current.hasMoved = true;
      cancelDeleteTimer();
    }
    setDragVisual(prev => ({ ...prev, currX: e.clientX, currY: e.clientY }));
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    cancelDeleteTimer();
    if (!dragRef.current.isDragging) return;
    const { sourceId, hasMoved } = dragRef.current;
    if (!hasMoved && sourceId) {
      if (sourceId === 'BANK') setIsHistoryOpen(true);
      else if (deleteState.revealedId !== sourceId) {
        const player = players.find(p => p.id === sourceId);
        if (player) setPlayerFormState({ isOpen: true, playerToEdit: player });
      }
    } else if (hasMoved && sourceId) {
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetId = elements.find(el => el.getAttribute('data-id'))?.getAttribute('data-id');
      if (targetId && targetId !== sourceId) {
        setModalState({ isOpen: true, initialFromId: sourceId, initialToId: targetId });
      }
    }
    dragRef.current = { isDragging: false, sourceId: null, startX: 0, startY: 0, hasMoved: false };
    setDragVisual(prev => ({ ...prev, isDragging: false }));
    try { (e.target as Element).releasePointerCapture(e.pointerId); } catch (err) { }
  };

  useEffect(() => {
    if (!gameStarted || !boardRef.current) return;
    const updatePositions = () => {
      if (!boardRef.current) return;
      const { width, height } = boardRef.current.getBoundingClientRect();
      if (width === 0) return;
      const cx = width / 2;
      const cy = height / 2;
      const isMobile = width < 768;
      const rx = (width / 2) - (isMobile ? 85 : 180);
      const ry = (height / 2) - (isMobile ? 130 : 180);
      if (rx <= 20 || ry <= 20) return;
      const newPositions: { [key: string]: { x: number, y: number } } = {};
      const numPlayers = players.length;
      const startAngle = numPlayers === 4 ? -Math.PI / 4 : -Math.PI / 2;
      players.forEach((player, index) => {
        const angle = (index / numPlayers) * 2 * Math.PI + startAngle; 
        newPositions[player.id] = { x: cx + rx * Math.cos(angle), y: cy + ry * Math.sin(angle) };
      });
      setPlayerPositions(newPositions);
    };
    updatePositions();
    const observer = new ResizeObserver(() => updatePositions());
    observer.observe(boardRef.current);
    return () => observer.disconnect();
  }, [players.length, gameStarted]);

  // Helper to append shorthand
  const appendShorthand = (setter: React.Dispatch<React.SetStateAction<string>>, current: string, unit: 'K' | 'M') => {
    const upper = current.toUpperCase();
    if (!upper.endsWith('K') && !upper.endsWith('M')) {
      setter(current + unit);
    } else {
      setter(current.slice(0, -1) + unit);
    }
  };

  if (!gameStarted) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 flex flex-col items-center p-4 md:p-8 font-sans text-slate-100 overflow-y-auto">
        <div className="w-full max-w-2xl space-y-8">
          <div className="text-center space-y-2 py-8">
            <h1 className="text-7xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-600 drop-shadow-2xl tracking-tighter">PolyBank</h1>
            <p className="text-slate-400 text-xl font-medium tracking-tight">Lite Banking Assistant</p>
          </div>

          <div className="glass-panel rounded-[2rem] p-8 shadow-2xl space-y-8 border-white/5 bg-white/5">
            <div className="flex items-center gap-4 border-b border-white/10 pb-6">
              <span className="text-3xl">⚙️</span>
              <h2 className="text-2xl font-black text-white tracking-tight">Game Configuration</h2>
            </div>

            <div className="space-y-4">
              <label className="text-xs font-black text-blue-300 uppercase tracking-[0.2em]">Select Currency</label>
              <div className="grid grid-cols-4 sm:grid-cols-8 gap-2">
                {CURRENCIES.map((c) => (
                  <button
                    key={c.name}
                    onClick={() => setCurrency(c)}
                    className={`flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all ${
                      currency.name === c.name 
                        ? 'bg-cyan-500 border-cyan-400 shadow-lg shadow-cyan-500/20' 
                        : 'bg-white/5 border-white/5 hover:border-white/10 text-slate-400'
                    }`}
                  >
                    <span className="text-xl font-black">{c.symbol}</span>
                    <span className="text-[8px] mt-1 font-bold truncate w-full text-center">{c.name.split(' ')[0]}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-3">
                <label className="text-xs font-black text-blue-300 uppercase tracking-[0.2em]">Initial Balance</label>
                <div className="relative">
                  <input 
                    type="text" 
                    inputMode="numeric"
                    value={setupBalanceInput}
                    onChange={(e) => setSetupBalanceInput(e.target.value)}
                    className="w-full bg-black/40 border border-white/10 rounded-2xl py-5 pl-6 pr-16 text-white font-mono text-xl focus:ring-4 focus:ring-cyan-500/20 outline-none uppercase transition-all"
                    placeholder="e.g. 1.5M"
                  />
                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                    <button onClick={() => appendShorthand(setSetupBalanceInput, setupBalanceInput, 'K')} className="bg-white/10 hover:bg-white/20 px-2 py-1 rounded text-[10px] font-black">K</button>
                    <button onClick={() => appendShorthand(setSetupBalanceInput, setupBalanceInput, 'M')} className="bg-white/10 hover:bg-white/20 px-2 py-1 rounded text-[10px] font-black">M</button>
                  </div>
                  <div className="absolute left-6 -bottom-5 text-[10px] font-black text-cyan-400 opacity-60">
                    {formatFullAmount(parseMoneyInput(setupBalanceInput), currency)}
                  </div>
                </div>
              </div>
              <div className="space-y-3">
                <label className="text-xs font-black text-blue-300 uppercase tracking-[0.2em]">GO Reward</label>
                <div className="relative">
                  <input 
                    type="text" 
                    inputMode="numeric"
                    value={setupGoInput}
                    onChange={(e) => setSetupGoInput(e.target.value)}
                    className="w-full bg-black/40 border border-white/10 rounded-2xl py-5 pl-6 pr-16 text-white font-mono text-xl focus:ring-4 focus:ring-cyan-500/20 outline-none uppercase transition-all"
                    placeholder="e.g. 200"
                  />
                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                    <button onClick={() => appendShorthand(setSetupGoInput, setupGoInput, 'K')} className="bg-white/10 hover:bg-white/20 px-2 py-1 rounded text-[10px] font-black">K</button>
                    <button onClick={() => appendShorthand(setSetupGoInput, setupGoInput, 'M')} className="bg-white/10 hover:bg-white/20 px-2 py-1 rounded text-[10px] font-black">M</button>
                  </div>
                  <div className="absolute left-6 -bottom-5 text-[10px] font-black text-cyan-400 opacity-60">
                    {formatFullAmount(parseMoneyInput(setupGoInput), currency)}
                  </div>
                </div>
              </div>
            </div>
          </div>

          <div className="glass-panel rounded-[2rem] p-8 shadow-2xl space-y-6 border-white/5 bg-white/5">
            <div className="flex items-center justify-between border-b border-white/10 pb-6">
               <h2 className="text-2xl font-black text-white tracking-tight">Players ({players.length}/6)</h2>
               <button onClick={handleAddPlayer} disabled={players.length >= 6} className="bg-cyan-500 text-white p-3 rounded-2xl active:scale-90 transition-transform">
                 <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
               </button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {players.map((player) => (
                <div key={player.id} className="flex items-center gap-4 bg-white/5 p-4 rounded-2xl border border-white/5">
                  <span className="text-4xl">{player.avatar}</span>
                  <input
                    type="text"
                    value={player.name}
                    onChange={(e) => handleUpdatePlayerName(player.id, e.target.value)}
                    className="bg-transparent text-white font-black w-full outline-none"
                  />
                  <button onClick={() => handleDeletePlayer(player.id)} className="text-slate-600 hover:text-red-500"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              ))}
            </div>
          </div>
          <Button fullWidth size="lg" onClick={handleStartGame} disabled={players.length < 2} className="rounded-[2rem] !py-6 !text-2xl !font-black !bg-gradient-to-r !from-cyan-500 !to-blue-600">Start Session 🚀</Button>
        </div>
        <PlayerFormModal isOpen={playerFormState.isOpen} onClose={() => setPlayerFormState({ isOpen: false })} initialData={playerFormState.playerToEdit} onSave={handleUpdatePlayerAppearance} />
      </div>
    );
  }

  return (
    <div 
      className="fixed inset-0 bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 overflow-hidden touch-none"
      onPointerMove={handlePointerMove}
      onPointerUp={handlePointerUp}
      onContextMenu={(e) => e.preventDefault()}
    >
      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between items-start z-[100] pointer-events-none">
        <div className="flex gap-3 pointer-events-auto">
          <button onClick={() => setIsSettingsOpen(true)} className="bg-black/40 text-slate-400 p-4 rounded-3xl border border-white/10 hover:text-white transition-all">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            </svg>
          </button>
        </div>
        <div className="flex gap-3 pointer-events-auto">
          <button onClick={() => setIsStrategyOpen(true)} className="bg-purple-600 text-white p-4 rounded-3xl shadow-xl hover:scale-110 transition-transform active:scale-90">🔮</button>
          <button onClick={() => setIsRulesOpen(true)} className="bg-black/40 text-slate-400 p-4 rounded-3xl border border-white/10">⚖️</button>
          <button onClick={() => setIsHistoryOpen(true)} className="bg-black/40 text-slate-400 p-4 rounded-3xl border border-white/10">📜</button>
        </div>
      </div>

      {/* AI Commentary Toast */}
      {liveCommentary && (
        <div className="absolute bottom-12 left-1/2 -translate-x-1/2 z-[150] w-[90%] max-w-md animate-in slide-in-from-bottom-8 fade-in duration-500 pointer-events-none">
          <div className="bg-slate-900/90 border-2 border-cyan-500/50 backdrop-blur-xl rounded-2xl p-4 shadow-2xl flex items-start gap-4 ring-4 ring-cyan-500/10">
            <span className="text-3xl mt-1">🤖</span>
            <div>
              <p className="text-cyan-400 text-[10px] font-black uppercase tracking-[0.2em] mb-1">AI Narrator</p>
              <p className="text-white font-medium text-sm italic leading-relaxed">
                {liveCommentary.text === '...' ? (
                  <span className="flex gap-1">
                    <span className="animate-bounce">.</span>
                    <span className="animate-bounce delay-100">.</span>
                    <span className="animate-bounce delay-200">.</span>
                  </span>
                ) : `"${liveCommentary.text}"`}
              </p>
            </div>
          </div>
        </div>
      )}

      <div ref={boardRef} className="absolute inset-0 z-0">
        <BankCard currency={currency} onDragStart={handlePointerDown} />
        {players.map((player) => (
          <PlayerCard 
            key={player.id}
            player={player}
            currency={currency}
            onEditName={handleUpdatePlayerName}
            onDragStart={handlePointerDown}
            onDeleteClick={handleDeletePlayer}
            showDeleteButton={deleteState.revealedId === player.id}
            deleteProgress={deleteState.id === player.id ? deleteState.progress : 0}
            style={{
              left: playerPositions[player.id]?.x || '50%',
              top: playerPositions[player.id]?.y || '50%',
              opacity: playerPositions[player.id] ? 1 : 0, 
              transition: (deleteState.id === player.id) ? 'none' : 'opacity 0.4s, left 0.6s cubic-bezier(0.34, 1.56, 0.64, 1), top 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)'
            }}
          />
        ))}
      </div>

      {dragVisual.isDragging && (
        <div className="absolute inset-0 pointer-events-none z-[110]">
          <svg className="w-full h-full"><line x1={dragVisual.startX} y1={dragVisual.startY} x2={dragVisual.currX} y2={dragVisual.currY} stroke="#22d3ee" strokeWidth="4" strokeDasharray="10 10" className="opacity-40" /></svg>
        </div>
      )}

      <TransactionModal isOpen={modalState.isOpen} initialFromId={modalState.initialFromId} initialToId={modalState.initialToId} onClose={() => setModalState({ isOpen: false })} players={players} currency={currency} passGoAmount={gameSettings.passGoAmount} onTransaction={handleTransaction} />
      <HistoryLogModal isOpen={isHistoryOpen} onClose={() => setIsHistoryOpen(false)} transactions={transactions} players={players} currency={currency} onToggleTransaction={handleToggleTransaction} />
      <RulesBot isOpen={isRulesOpen} onClose={() => setIsRulesOpen(false)} />
      <StrategyModal isOpen={isStrategyOpen} onClose={() => setIsStrategyOpen(false)} players={players} />
      <PlayerFormModal isOpen={playerFormState.isOpen} onClose={() => setPlayerFormState({ isOpen: false })} initialData={playerFormState.playerToEdit} onSave={handleUpdatePlayerAppearance} />

      <SettingsModal 
        isOpen={isSettingsOpen} 
        onClose={() => setIsSettingsOpen(false)} 
        settings={gameSettings}
        onUpdateSettings={setGameSettings}
        onResetGame={handleResetGame}
        currency={currency}
        onUpdateCurrency={setCurrency}
        onAddPlayer={handleAddPlayer}
        playerCount={players.length}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Player, TransactionType, Currency } from '../types';
import Button from './Button';

interface TransactionModalProps {
  isOpen: boolean;
  initialFromId?: string;
  initialToId?: string;
  onClose: () => void;
  players: Player[];
  currency: Currency;
  passGoAmount: number;
  onTransaction: (type: TransactionType, fromId: string, toId: string, amount: number) => void;
}

const TransactionModal: React.FC<TransactionModalProps> = ({ 
  isOpen, 
  initialFromId, 
  initialToId, 
  onClose, 
  players, 
  currency,
  passGoAmount,
  onTransaction 
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'bank' | 'go'>('transfer');

  const [fromId, setFromId] = useState<string>('');
  const [toId, setToId] = useState<string>('');
  const [amount, setAmount] = useState<string>(''); 

  const [bankPlayerId, setBankPlayerId] = useState<string>('');
  const [bankAction, setBankAction] = useState<'pay' | 'receive'>('pay');

  useEffect(() => {
    if (isOpen) {
      if (initialFromId === 'BANK' && initialToId && initialToId !== 'BANK') {
        setActiveTab('bank');
        setBankAction('receive');
        setBankPlayerId(initialToId);
      } else if (initialToId === 'BANK' && initialFromId && initialFromId !== 'BANK') {
        setActiveTab('bank');
        setBankAction('pay');
        setBankPlayerId(initialFromId);
      } else if (initialFromId && initialToId && initialFromId !== 'BANK' && initialToId !== 'BANK') {
        setActiveTab('transfer');
        setFromId(initialFromId);
        setToId(initialToId);
      } else {
        setActiveTab('transfer');
        setFromId('');
        setToId('');
        setBankPlayerId('');
      }
      setAmount('');
    }
  }, [isOpen, initialFromId, initialToId]);

  if (!isOpen) return null;

  const parseValue = (val: string): number => {
    const clean = val.toLowerCase().replace(/,/g, '').trim();
    if (!clean) return 0;

    let multiplier = 1;
    let numericPart = clean;

    if (clean.endsWith('m')) {
      multiplier = 1000000;
      numericPart = clean.slice(0, -1);
    } else if (clean.endsWith('k')) {
      multiplier = 1000;
      numericPart = clean.slice(0, -1);
    }

    const num = parseFloat(numericPart);
    return isNaN(num) ? 0 : Math.floor(num * multiplier);
  };

  const handleTransfer = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = parseValue(amount);
    if (fromId && toId && numericAmount > 0 && fromId !== toId) {
      onTransaction(TransactionType.TRANSFER, fromId, toId, numericAmount);
      onClose();
    }
  };

  const handleBankTransaction = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = parseValue(amount);
    if (bankPlayerId && numericAmount > 0) {
      if (bankAction === 'pay') {
        onTransaction(TransactionType.BANK_DEPOSIT, bankPlayerId, 'BANK', numericAmount);
      } else {
        onTransaction(TransactionType.BANK_WITHDRAWAL, 'BANK', bankPlayerId, numericAmount);
      }
      onClose();
    }
  };

  const handlePassGo = () => {
    if (bankPlayerId) {
      onTransaction(TransactionType.PASS_GO, 'BANK', bankPlayerId, passGoAmount);
      onClose();
    }
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    // Allow numeric, dots, commas, and k/m shorthand
    if (/^[0-9.,kmKM]*$/.test(val)) {
      setAmount(val);
    }
  };

  const formatMoneyDisplay = (amount: number) => {
    const abs = Math.abs(amount);
    let val: string;
    if (abs >= 1000000) val = (amount / 1000000).toLocaleString(undefined, { maximumFractionDigits: 2 }) + 'M';
    else if (abs >= 10000) val = (amount / 1000).toLocaleString(undefined, { maximumFractionDigits: 1 }) + 'K';
    else val = amount.toLocaleString();

    return currency.position === 'prefix' ? `${currency.symbol}${val}` : `${val}${currency.symbol}`;
  };

  const formatFullAmountPreview = (amount: number) => {
    return currency.position === 'prefix' 
      ? `${currency.symbol}${amount.toLocaleString()}` 
      : `${amount.toLocaleString()}${currency.symbol}`;
  };

  const appendUnit = (unit: 'K' | 'M') => {
    const cleanAmount = amount.toUpperCase();
    if (!cleanAmount.endsWith('K') && !cleanAmount.endsWith('M')) {
      setAmount(amount + unit);
    } else {
      setAmount(amount.slice(0, -1) + unit);
    }
  };

  const renderAmountInput = (value: string, setter: (v: string) => void) => {
    const numericValue = parseValue(value);

    return (
      <div className="space-y-4">
        <label className="block text-xs font-black text-blue-300 uppercase tracking-widest">Amount</label>
        <div className="relative group">
          <input 
            type="text" 
            inputMode="numeric"
            value={value} 
            onChange={handleAmountChange}
            className="w-full bg-black/40 border-2 border-white/10 text-white rounded-[1.5rem] p-6 text-5xl font-mono text-center focus:ring-4 focus:ring-cyan-500/20 focus:border-cyan-500/50 outline-none transition-all shadow-inner uppercase placeholder:opacity-20" 
            placeholder="0" 
            required 
          />
          <div className="absolute right-3 top-1/2 -translate-y-1/2 flex flex-col gap-2">
            <button 
              type="button" 
              onClick={() => appendUnit('K')} 
              className="bg-cyan-600 hover:bg-cyan-500 text-white font-black px-4 py-2 rounded-xl text-sm shadow-lg transition-transform active:scale-90 border border-white/10"
            >
              K
            </button>
            <button 
              type="button" 
              onClick={() => appendUnit('M')} 
              className="bg-purple-600 hover:bg-purple-500 text-white font-black px-4 py-2 rounded-xl text-sm shadow-lg transition-transform active:scale-90 border border-white/10"
            >
              M
            </button>
          </div>
        </div>

        {numericValue > 0 && (
          <div className="flex justify-center">
            <div className="bg-cyan-500/10 border-2 border-cyan-500/30 px-6 py-2 rounded-full animate-in fade-in slide-in-from-top-2 duration-300 shadow-[0_0_15px_rgba(34,211,238,0.2)]">
              <span className="text-base font-black text-cyan-400">
                Resolved: {formatFullAmountPreview(numericValue)}
              </span>
            </div>
          </div>
        )}

        <div className="grid grid-cols-4 gap-2">
          {[50, 100, 200, 500].map(amt => (
            <button 
              key={amt} 
              type="button" 
              onClick={() => setter(amt.toString())} 
              className="bg-white/5 hover:bg-white/10 text-blue-200 font-black py-4 rounded-xl border border-white/5 transition-all active:bg-cyan-500/20 text-sm"
            >
              {amt}
            </button>
          ))}
        </div>
      </div>
    );
  };

  const renderPlayerSelect = (value: string, onChange: (val: string) => void, excludeId?: string, label?: string) => (
    <div className="space-y-2">
      {label && <label className="block text-xs font-black text-blue-300 uppercase tracking-widest">{label}</label>}
      <div className="relative">
        <select 
          value={value} 
          onChange={(e) => onChange(e.target.value)}
          className="w-full bg-black/40 border-2 border-white/10 text-white rounded-2xl p-5 pl-14 appearance-none focus:ring-4 focus:ring-cyan-500/20 focus:border-cyan-500/50 outline-none transition-all backdrop-blur-sm cursor-pointer"
          required
        >
          <option value="" className="bg-slate-900">Select Player</option>
          {players.filter(p => p.id !== excludeId).map(p => (
            <option key={p.id} value={p.id} className="bg-slate-900">{p.name} ({formatMoneyDisplay(p.balance)})</option>
          ))}
        </select>
        <div className="absolute left-5 top-1/2 -translate-y-1/2 text-3xl pointer-events-none">
          {value ? players.find(p => p.id === value)?.avatar : '👤'}
        </div>
        <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-white/20">
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
        </div>
      </div>
    </div>
  );

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in zoom-in duration-200">
      <div className="bg-slate-900 border border-white/10 rounded-[2.5rem] w-full max-w-md shadow-2xl overflow-hidden backdrop-blur-2xl">

        {/* Modern Tab HUD */}
        <div className="flex bg-black/30 p-2 gap-1">
          {(['transfer', 'bank', 'go'] as const).map(tab => (
            <button 
              key={tab}
              onClick={() => setActiveTab(tab)} 
              className={`flex-1 py-4 rounded-2xl text-xs font-black uppercase tracking-[0.2em] transition-all ${
                activeTab === tab 
                  ? 'bg-gradient-to-r from-cyan-600 to-blue-600 text-white shadow-lg' 
                  : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'
              }`}
            >
              {tab === 'transfer' ? 'Transfer' : tab === 'bank' ? 'Bank' : 'Go'}
            </button>
          ))}
        </div>

        <div className="p-8">
          {activeTab === 'transfer' && (
            <form onSubmit={handleTransfer} className="space-y-6">
              {renderPlayerSelect(fromId, setFromId, undefined, "Sender")}
              <div className="flex justify-center -my-3 relative z-10">
                <div className="bg-slate-800 rounded-full p-3 border-2 border-slate-700 shadow-xl text-cyan-400">
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 14l-7 7m0 0l-7-7m7 7V3" /></svg>
                </div>
              </div>
              {renderPlayerSelect(toId, setToId, fromId, "Recipient")}
              {renderAmountInput(amount, setAmount)}
              <div className="pt-6 flex gap-4">
                <Button type="button" variant="ghost" fullWidth onClick={onClose} className="rounded-2xl py-4">Cancel</Button>
                <Button type="submit" fullWidth disabled={!fromId || !toId || parseValue(amount) <= 0} className="bg-cyan-600 rounded-2xl py-4 text-lg shadow-xl shadow-cyan-500/20">Send</Button>
              </div>
            </form>
          )}

          {activeTab === 'bank' && (
            <form onSubmit={handleBankTransaction} className="space-y-6">
              <div className="flex bg-black/40 rounded-[1.2rem] p-1.5 gap-1">
                {(['pay', 'receive'] as const).map(action => (
                  <button 
                    key={action}
                    type="button"
                    onClick={() => setBankAction(action)}
                    className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${
                      bankAction === action 
                        ? (action === 'pay' ? 'bg-red-500' : 'bg-emerald-500') + ' text-white shadow-lg'
                        : 'text-slate-500 hover:text-slate-400'
                    }`}
                  >
                    {action === 'pay' ? 'Pay Bank' : 'Collect'}
                  </button>
                ))}
              </div>
              {renderPlayerSelect(bankPlayerId, setBankPlayerId, undefined, "Select Player")}
              {renderAmountInput(amount, setAmount)}
              <div className="pt-6 flex gap-4">
                <Button type="button" variant="ghost" fullWidth onClick={onClose} className="rounded-2xl py-4">Cancel</Button>
                <Button 
                  type="submit" 
                  fullWidth 
                  disabled={!bankPlayerId || parseValue(amount) <= 0} 
                  className={`${bankAction === 'pay' ? "bg-red-500" : "bg-emerald-500"} rounded-2xl py-4 text-lg shadow-xl transition-colors`}
                >
                  {bankAction === 'pay' ? 'Pay Bank' : 'Receive Funds'}
                </Button>
              </div>
            </form>
          )}

          {activeTab === 'go' && (
            <div className="space-y-8 text-center">
              <div className="bg-emerald-500/10 border-2 border-emerald-500/20 rounded-[2.5rem] p-10 space-y-4 shadow-inner">
                <div className="text-6xl animate-bounce">🏁</div>
                <h3 className="text-3xl font-black text-emerald-400">Collect {formatMoneyDisplay(passGoAmount)}</h3>
                <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Passed Go Reward</p>
              </div>
              {renderPlayerSelect(bankPlayerId, setBankPlayerId, undefined, "Player reaching GO")}
              <div className="pt-6 flex gap-4">
                <Button variant="ghost" fullWidth onClick={onClose} className="rounded-2xl py-4">Cancel</Button>
                <Button fullWidth onClick={handlePassGo} disabled={!bankPlayerId} className="bg-emerald-500 rounded-2xl py-4 text-lg shadow-xl shadow-emerald-500/20">Collect</Button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default TransactionModal;

import React, { useState, useEffect, useRef } from 'react';
import { Player, Transaction, TransactionType, ThemeColor, Currency, GameSettings } from './types';
import { DEFAULT_STARTING_BALANCE, DEFAULT_PASS_GO_AMOUNT, PLAYER_COLORS, CURRENCIES, AVATARS } from './constants';
import PlayerCard from './components/PlayerCard';
import BankCard from './components/BankCard';
import TransactionModal from './components/TransactionModal';
import HistoryLogModal from './components/HistoryLogModal';
import RulesBot from './components/RulesBot';
import StrategyModal from './components/StrategyModal';
import Button from './components/Button';
import PlayerFormModal from './components/PlayerFormModal';
import SettingsModal from './components/SettingsModal';

const generateId = () => Math.random().toString(36).substr(2, 9);
const REVEAL_DELETE_THRESHOLD_MS = 600;

// Utility to parse money shorthand (1.5k -> 1500)
const parseMoneyInput = (val: string): number => {
  const clean = val.toLowerCase().replace(/,/g, '').trim();
  if (!clean) return 0;
  let multiplier = 1;
  let numericPart = clean;
  if (clean.endsWith('m')) {
    multiplier = 1000000;
    numericPart = clean.slice(0, -1);
  } else if (clean.endsWith('k')) {
    multiplier = 1000;
    numericPart = clean.slice(0, -1);
  }
  const num = parseFloat(numericPart);
  return isNaN(num) ? 0 : Math.floor(num * multiplier);
};

const formatFullAmount = (amount: number, currency: Currency) => {
  const formatted = amount.toLocaleString();
  return currency.position === 'prefix' ? `${currency.symbol}${formatted}` : `${formatted}${currency.symbol}`;
};

const App: React.FC = () => {
  // --- State ---
  const [currency, setCurrency] = useState<Currency>(CURRENCIES[0]);
  const [gameSettings, setGameSettings] = useState<GameSettings>({
    startingBalance: DEFAULT_STARTING_BALANCE,
    passGoAmount: DEFAULT_PASS_GO_AMOUNT
  });

  const [setupBalanceInput, setSetupBalanceInput] = useState(DEFAULT_STARTING_BALANCE.toString());
  const [setupGoInput, setSetupGoInput] = useState(DEFAULT_PASS_GO_AMOUNT.toString());

  const [players, setPlayers] = useState<Player[]>([]);
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [gameStarted, setGameStarted] = useState(false);

  const [modalState, setModalState] = useState<{
    isOpen: boolean;
    initialFromId?: string;
    initialToId?: string;
  }>({ isOpen: false });

  const [isRulesOpen, setIsRulesOpen] = useState(false);
  const [isStrategyOpen, setIsStrategyOpen] = useState(false);
  const [isHistoryOpen, setIsHistoryOpen] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [playerFormState, setPlayerFormState] = useState<{
    isOpen: boolean;
    playerToEdit?: Player;
  }>({ isOpen: false });

  // Long Press & Drag State
  const [deleteState, setDeleteState] = useState<{ 
    id: string | null; 
    progress: number;
    revealedId: string | null; 
  }>({ id: null, progress: 0, revealedId: null });
  const deleteTimerRef = useRef<number | null>(null);

  const [dragVisual, setDragVisual] = useState<{
    isDragging: boolean;
    startX: number;
    startY: number;
    currX: number;
    currY: number;
  }>({
    isDragging: false,
    startX: 0,
    startY: 0,
    currX: 0,
    currY: 0,
  });

  const dragRef = useRef<{
    isDragging: boolean;
    sourceId: string | null;
    startX: number;
    startY: number;
    hasMoved: boolean;
  }>({
    isDragging: false,
    sourceId: null,
    startX: 0,
    startY: 0,
    hasMoved: false
  });

  const boardRef = useRef<HTMLDivElement>(null);
  const [playerPositions, setPlayerPositions] = useState<{ [key: string]: { x: number, y: number } }>({});

  // --- Persistence ---
  useEffect(() => {
    const savedGame = localStorage.getItem('bankair_state_v1');
    if (savedGame) {
      try {
        const parsed = JSON.parse(savedGame);
        setPlayers(parsed.players || []);
        setTransactions(parsed.transactions || []);
        setGameStarted(parsed.gameStarted || false);
        setCurrency(parsed.currency || CURRENCIES[0]);
        const settings = parsed.settings || { startingBalance: DEFAULT_STARTING_BALANCE, passGoAmount: DEFAULT_PASS_GO_AMOUNT };
        setGameSettings(settings);
        setSetupBalanceInput(settings.startingBalance.toString());
        setSetupGoInput(settings.passGoAmount.toString());
      } catch (e) {
        console.error("Failed to load save", e);
      }
    }
  }, []);

  useEffect(() => {
    const stateToSave = {
      players,
      transactions,
      gameStarted,
      currency,
      settings: gameSettings
    };
    localStorage.setItem('bankair_state_v1', JSON.stringify(stateToSave));
  }, [players, transactions, gameStarted, currency, gameSettings]);

  useEffect(() => {
    if (!gameStarted) {
      setGameSettings({
        startingBalance: parseMoneyInput(setupBalanceInput),
        passGoAmount: parseMoneyInput(setupGoInput)
      });
    }
  }, [setupBalanceInput, setupGoInput, gameStarted]);

  // --- Game Control ---
  const handleStartGame = () => {
    if (players.length < 2) return;
    const finalSettings = {
      startingBalance: parseMoneyInput(setupBalanceInput),
      passGoAmount: parseMoneyInput(setupGoInput)
    };
    setGameSettings(finalSettings);
    const resetPlayers = players.map(p => ({
      ...p,
      balance: finalSettings.startingBalance,
      isBankrupt: false
    }));
    setPlayers(resetPlayers);
    setTransactions([]);
    setGameStarted(true);
  };

  const handleResetGame = () => {
    if (window.confirm("Are you sure? This will clear all transactions and reset balances. Player customizations will be kept.")) {
      setTransactions([]);
      setPlayers(prev => prev.map(p => ({
        ...p,
        balance: 0,
        isBankrupt: false
      })));
      setGameStarted(false);
      setIsSettingsOpen(false);
    }
  };

  const handleDeletePlayer = (id: string) => {
    if (players.length <= 2 && gameStarted) {
      alert("Minimum 2 players required.");
      return;
    }
    if (window.confirm("Remove this player?")) {
      setPlayers(prev => prev.filter(p => p.id !== id));
      setDeleteState(prev => ({ ...prev, revealedId: null }));
      if (window.navigator.vibrate) window.navigator.vibrate([20, 40, 20]);
    }
  };

  const handleAddPlayer = () => {
    if (players.length >= 6) return;
    const count = players.length + 1;
    const randomAvatar = AVATARS[Math.floor(Math.random() * AVATARS.length)];
    const colorKeys = Object.keys(PLAYER_COLORS) as ThemeColor[];
    const randomColor = colorKeys[Math.floor(Math.random() * colorKeys.length)];

    const newPlayer: Player = {
      id: generateId(),
      name: `Player ${count}`,
      avatar: randomAvatar,
      balance: gameStarted ? gameSettings.startingBalance : 0,
      color: randomColor,
      isBankrupt: false
    };
    setPlayers([...players, newPlayer]);
  };

  const handleUpdatePlayerName = (id: string, name: string) => {
    setPlayers(prev => prev.map(p => p.id === id ? { ...p, name } : p));
  };

  const handleUpdatePlayerAppearance = (data: Partial<Player>) => {
    const editId = playerFormState.playerToEdit?.id;
    if (editId) {
      setPlayers(prev => prev.map(p => p.id === editId ? { ...p, ...data } : p));
    }
  };

  const handleTransaction = (type: TransactionType, fromId: string, toId: string, amount: number) => {
    const newTx: Transaction = {
      id: generateId(),
      timestamp: Date.now(),
      type,
      fromId: fromId as any,
      toId: toId as any,
      amount,
      isReverted: false
    };

    // UPDATE STATE IMMEDIATELY (Banking first)
    setTransactions(prev => [...prev, newTx]);
    applyTransactionEffect(newTx, false);
  };

  const applyTransactionEffect = (tx: Transaction, isReversing: boolean) => {
    const { fromId, toId, amount } = tx;
    setPlayers(prevPlayers => prevPlayers.map(p => {
      let newBalance = p.balance;
      if (p.id === fromId) newBalance = isReversing ? p.balance + amount : p.balance - amount;
      if (p.id === toId) newBalance = isReversing ? p.balance - amount : p.balance + amount;
      return { ...p, balance: newBalance };
    }));
  };

  const handleToggleTransaction = (id: string) => {
    const txIndex = transactions.findIndex(t => t.id === id);
    if (txIndex === -1) return;
    const tx = transactions[txIndex];
    const isReverting = !tx.isReverted;
    const updatedTransactions = [...transactions];
    updatedTransactions[txIndex] = { ...tx, isReverted: isReverting };
    setTransactions(updatedTransactions);
    applyTransactionEffect(tx, isReverting);
  };

  // --- Interaction Logic ---
  const startDeleteTimer = (id: string) => {
    if (id === 'BANK') return;
    setDeleteState(prev => ({ ...prev, id, progress: 0 }));
    const startTime = Date.now();
    if (deleteTimerRef.current) clearInterval(deleteTimerRef.current);
    deleteTimerRef.current = window.setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min((elapsed / REVEAL_DELETE_THRESHOLD_MS) * 100, 100);
      setDeleteState(prev => ({ ...prev, progress }));
      if (progress >= 100) {
        clearInterval(deleteTimerRef.current!);
        deleteTimerRef.current = null;
        if (window.navigator.vibrate) window.navigator.vibrate(50);
        setDeleteState(prev => ({ ...prev, id: null, progress: 0, revealedId: id }));
      }
    }, 50);
  };

  const cancelDeleteTimer = () => {
    if (deleteTimerRef.current) {
      clearInterval(deleteTimerRef.current);
      deleteTimerRef.current = null;
    }
    setDeleteState(prev => ({ ...prev, id: null, progress: 0 }));
  };

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return;
    if (deleteState.revealedId && deleteState.revealedId !== id) {
       setDeleteState(prev => ({ ...prev, revealedId: null }));
    }
    const clientX = e.clientX;
    const clientY = e.clientY;
    dragRef.current = { isDragging: true, sourceId: id, startX: clientX, startY: clientY, hasMoved: false };
    setDragVisual({ isDragging: true, startX: clientX, startY: clientY, currX: clientX, currY: clientY });
    startDeleteTimer(id);
    try { (e.target as Element).setPointerCapture(e.pointerId); } catch (err) { }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!dragRef.current.isDragging) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;
    if (Math.abs(dx) > 15 || Math.abs(dy) > 15) {
      dragRef.current.hasMoved = true;
      cancelDeleteTimer();
    }
    setDragVisual(prev => ({ ...prev, currX: e.clientX, currY: e.clientY }));
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    cancelDeleteTimer();
    if (!dragRef.current.isDragging) return;
    const { sourceId, hasMoved } = dragRef.current;
    if (!hasMoved && sourceId) {
      if (sourceId === 'BANK') setIsHistoryOpen(true);
      else if (deleteState.revealedId !== sourceId) {
        const player = players.find(p => p.id === sourceId);
        if (player) setPlayerFormState({ isOpen: true, playerToEdit: player });
      }
    } else if (hasMoved && sourceId) {
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetId = elements.find(el => el.getAttribute('data-id'))?.getAttribute('data-id');
      if (targetId && targetId !== sourceId) {
        setModalState({ isOpen: true, initialFromId: sourceId, initialToId: targetId });
      }
    }
    dragRef.current = { isDragging: false, sourceId: null, startX: 0, startY: 0, hasMoved: false };
    setDragVisual(prev => ({ ...prev, isDragging: false }));
    try { (e.target as Element).releasePointerCapture(e.pointerId); } catch (err) { }
  };

  useEffect(() => {
    if (!gameStarted || !boardRef.current) return;
    const updatePositions = () => {
      if (!boardRef.current) return;
      const { width, height } = boardRef.current.getBoundingClientRect();
      if (width === 0) return;
      const cx = width / 2;
      const cy = height / 2;
      const isMobile = width < 768;
      const rx = (width / 2) - (isMobile ? 85 : 180);
      const ry = (height / 2) - (isMobile ? 130 : 180);
      if (rx <= 20 || ry <= 20) return;
      const newPositions: { [key: string]: { x: number, y: number } } = {};
      const numPlayers = players.length;
      const startAngle = numPlayers === 4 ? -Math.PI / 4 : -Math.PI / 2;
      players.forEach((player, index) => {
        const angle = (index / numPlayers) * 2 * Math.PI + startAngle; 
        newPositions[player.id] = { x: cx + rx * Math.cos(angle), y: cy + ry * Math.sin(angle) };
      });
      setPlayerPositions(newPositions);
    };
    updatePositions();
    const observer = new ResizeObserver(() => updatePositions());
    observer.observe(boardRef.current);
    return () => observer.disconnect();
  }, [players.length, gameStarted]);

  // Helper to append shorthand
  const appendShorthand = (setter: React.Dispatch<React.SetStateAction<string>>, current: string, unit: 'K' | 'M') => {
    const upper = current.toUpperCase();
    if (!upper.endsWith('K') && !upper.endsWith('M')) {
      setter(current + unit);
    } else {
      setter(current.slice(0, -1) + unit);
    }
  };

  if (!gameStarted) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-indigo-950 via-slate-900 to-fuchsia-950 flex flex-col items-center p-4 md:p-8 font-sans text-slate-100 overflow-y-auto">
        <div className="w-full max-w-2xl space-y-8">
          <div className="text-center space-y-2 py-8">
            <h1 className="text-7xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-400 via-blue-500 to-purple-600 drop-shadow-2xl tracking-tighter">PolyBank</h1>
            <p className="text-slate-400 text-xl font-medium tracking-tight">Lite Banking Assistant</p>
          </div>

          <div className="glass-panel rounded-[2rem] p-8 shadow-2xl space-y-8 border-white/5 bg-white/5">
            <div className="flex items-center gap-4 border-b border-white/10 pb-6">
              <span className="text-3xl">⚙️</span>
              <h2 className="text-2xl font-black text-white tracking-tight">Game Configuration</h2>
            </div>

            <div className="space-y-4">
              <label className="text-xs font-black text-blue-300 uppercase tracking-[0.2em]">Select Currency</label>
              <div className="grid grid-cols-4 sm:grid-cols-8 gap-2">
                {CURRENCIES.map((c) => (
                  <button
                    key={c.name}
                    onClick={() => setCurrency(c)}
                    className={`flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all ${
                      currency.name === c.name 
                        ? 'bg-cyan-500 border-cyan-400 shadow-lg shadow-cyan-500/20' 
                        : 'bg-white/5 border-white/5 hover:border-white/10 text-slate-400'
                    }`}
                  >
                    <span className="text-xl font-black">{c.symbol}</span>
                    <span className="text-[8px] mt-1 font-bold truncate w-full text-center">{c.name.split(' ')[0]}</span>
                  </button>
                ))}
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-3">
                <label className="text-xs font-black text-blue-300 uppercase tracking-[0.2em]">Initial Balance</label>
                <div className="relative">
                  <input 
                    type="text" 
                    inputMode="numeric"
                    value={setupBalanceInput}
                    onChange={(e) => setSetupBalanceInput(e.target.value)}
                    className="w-full bg-black/40 border border-white/10 rounded-2xl py-5 pl-6 pr-16 text-white font-mono text-xl focus:ring-4 focus:ring-cyan-500/20 outline-none uppercase transition-all"
                    placeholder="e.g. 1.5M"
                  />
                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                    <button onClick={() => appendShorthand(setSetupBalanceInput, setupBalanceInput, 'K')} className="bg-white/10 hover:bg-white/20 px-2 py-1 rounded text-[10px] font-black">K</button>
                    <button onClick={() => appendShorthand(setSetupBalanceInput, setupBalanceInput, 'M')} className="bg-white/10 hover:bg-white/20 px-2 py-1 rounded text-[10px] font-black">M</button>
                  </div>
                  <div className="absolute left-6 -bottom-5 text-[10px] font-black text-cyan-400 opacity-60">
                    {formatFullAmount(parseMoneyInput(setupBalanceInput), currency)}
                  </div>
                </div>
              </div>
              <div className="space-y-3">
