import React, { useState, useEffect } from 'react';
import { GameSettings, Currency } from '../types';
import { CURRENCIES } from '../constants';
import Button from './Button';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: GameSettings;
  onUpdateSettings: (settings: GameSettings) => void;
  onResetGame: () => void;
  currency: Currency;
  onUpdateCurrency: (currency: Currency) => void;
  playerCount?: number;
}

const parseMoneyInput = (val: string): number => {
  const clean = val.toLowerCase().replace(/,/g, '').trim();
  if (!clean) return 0;
  let multiplier = 1;
  let numericPart = clean;
  if (clean.endsWith('m')) {
    multiplier = 1000000;
    numericPart = clean.slice(0, -1);
  } else if (clean.endsWith('k')) {
    multiplier = 1000;
    numericPart = clean.slice(0, -1);
  }
  const num = parseFloat(numericPart);
  return isNaN(num) ? 0 : Math.floor(num * multiplier);
};

const formatFullAmount = (amount: number, currency: Currency) => {
  const formatted = amount.toLocaleString();
  return currency.position === 'prefix' ? `${currency.symbol}${formatted}` : `${formatted}${currency.symbol}`;
};

const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen,
  onClose,
  settings,
  onUpdateSettings,
  onResetGame,
  currency,
  onUpdateCurrency,
  playerCount = 0
}) => {
  const [balanceInput, setBalanceInput] = useState(settings.startingBalance.toString());
  const [goInput, setGoInput] = useState(settings.passGoAmount.toString());

  useEffect(() => {
    if (isOpen) {
      setBalanceInput(settings.startingBalance.toString());
      setGoInput(settings.passGoAmount.toString());
    }
  }, [isOpen, settings]);

  const handleUpdate = () => {
    onUpdateSettings({
      startingBalance: parseMoneyInput(balanceInput),
      passGoAmount: parseMoneyInput(goInput)
    });
  };

  const appendShorthand = (setter: React.Dispatch<React.SetStateAction<string>>, current: string, unit: 'K' | 'M') => {
    const upper = current.toUpperCase();
    if (!upper.endsWith('K') && !upper.endsWith('M')) {
      setter(current + unit);
    } else {
      setter(current.slice(0, -1) + unit);
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md">
      <div className="bg-slate-900 border border-white/10 rounded-[2.5rem] w-full max-w-md shadow-2xl overflow-hidden backdrop-blur-2xl flex flex-col max-h-[90vh]">
        <div className="p-6 border-b border-white/10 flex justify-between items-center bg-white/5 flex-shrink-0">
          <div className="flex items-center gap-3">
            <span className="text-2xl">⚙️</span>
            <h3 className="text-xl font-black text-white tracking-tight">Game Settings</h3>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
          </button>
        </div>

        <div className="p-8 space-y-8 overflow-y-auto custom-scrollbar">
          <div className="space-y-4">
            <label className="text-xs font-black text-cyan-400 uppercase tracking-[0.2em]">Active Currency</label>
            <div className="grid grid-cols-4 gap-2">
              {CURRENCIES.map((c) => (
                <button key={c.name} onClick={() => onUpdateCurrency(c)} className={`flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all ${currency.name === c.name ? 'bg-cyan-500 border-cyan-400 text-white shadow-lg' : 'bg-white/5 border-white/5 text-slate-400'}`}>
                  <span className="text-lg font-black">{c.symbol}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-6">
            <div className="space-y-3">
              <label className="text-xs font-black text-cyan-400 uppercase tracking-[0.2em]">Initial Balance</label>
              <div className="relative">
                <input 
                  type="text" 
                  inputMode="numeric"
                  value={balanceInput}
                  onChange={(e) => setBalanceInput(e.target.value)}
                  onBlur={handleUpdate}
                  className="w-full bg-black/40 border-2 border-white/10 rounded-2xl py-4 pl-6 pr-16 text-white font-mono focus:ring-4 focus:ring-cyan-500/20 outline-none transition-all uppercase"
                />
                <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                  <button onClick={() => appendShorthand(setBalanceInput, balanceInput, 'K')} className="bg-white/10 px-2 py-1 rounded text-[10px] font-black">K</button>
                  <button onClick={() => appendShorthand(setBalanceInput, balanceInput, 'M')} className="bg-white/10 px-2 py-1 rounded text-[10px] font-black">M</button>
                </div>
                <div className="absolute left-6 -bottom-5 text-[10px] font-black text-cyan-400 opacity-60">
                  {formatFullAmount(parseMoneyInput(balanceInput), currency)}
                </div>
              </div>
            </div>

            <div className="space-y-3">
              <label className="text-xs font-black text-cyan-400 uppercase tracking-[0.2em]">Pass GO Amount</label>
              <div className="relative">
                <input 
                  type="text" 
                  inputMode="numeric"
                  value={goInput}
                  onChange={(e) => setGoInput(e.target.value)}
                  onBlur={handleUpdate}
                  className="w-full bg-black/40 border-2 border-white/10 rounded-2xl py-4 pl-6 pr-16 text-white font-mono focus:ring-4 focus:ring-cyan-500/20 outline-none transition-all uppercase"
                />
                <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                  <button onClick={() => appendShorthand(setGoInput, goInput, 'K')} className="bg-white/10 px-2 py-1 rounded text-[10px] font-black">K</button>
                  <button onClick={() => appendShorthand(setGoInput, goInput, 'M')} className="bg-white/10 px-2 py-1 rounded text-[10px] font-black">M</button>
                </div>
                <div className="absolute left-6 -bottom-5 text-[10px] font-black text-cyan-400 opacity-60">
                  {formatFullAmount(parseMoneyInput(goInput), currency)}
                </div>
              </div>
            </div>
          </div>

          <div className="pt-4 border-t border-white/10 space-y-4">
            <div className="p-4 bg-red-500/5 rounded-2xl border border-red-500/10">
              <Button 
                variant="danger" 
                fullWidth 
                onClick={onResetGame}
                className="rounded-2xl py-4 font-black uppercase tracking-widest shadow-lg shadow-red-500/20"
              >
                Reset Game Session
              </Button>
            </div>
            <Button variant="ghost" fullWidth onClick={onClose} className="rounded-2xl py-3 text-slate-400 hover:text-white">
              Back to Game
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

