interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: GameSettings;
  onUpdateSettings: (settings: GameSettings) => void;
  onResetGame: () => void;
  currency: Currency;
  onUpdateCurrency: (currency: Currency) => void;
  playerCount: number;
  onAddPlayer: () => void;
}

const parseMoneyInput = (val: string): number => {
  const clean = val.toLowerCase().replace(/,/g, '').trim();
  if (!clean) return 0;
  let multiplier = 1;
  let numericPart = clean;
  if (clean.endsWith('m')) {
    multiplier = 1000000;
    numericPart = clean.slice(0, -1);
  } else if (clean.endsWith('k')) {
    multiplier = 1000;
    numericPart = clean.slice(0, -1);
  }
  const num = parseFloat(numericPart);
  return isNaN(num) ? 0 : Math.floor(num * multiplier);
};

const formatFullAmount = (amount: number, currency: Currency) => {
  const formatted = amount.toLocaleString();
  return currency.position === 'prefix' ? `${currency.symbol}${formatted}` : `${formatted}${currency.symbol}`;
};

const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen,
  onClose,
  settings,
  onUpdateSettings,
  onResetGame,
  currency,
  onUpdateCurrency,
  playerCount,
  onAddPlayer
}) => {
  const [balanceInput, setBalanceInput] = useState(settings.startingBalance.toString());
  const [goInput, setGoInput] = useState(settings.passGoAmount.toString());

  useEffect(() => {
    if (isOpen) {
      setBalanceInput(settings.startingBalance.toString());
      setGoInput(settings.passGoAmount.toString());
    }
  }, [isOpen, settings]);

  const handleInputChange = (type: 'balance' | 'go', value: string) => {
    if (type === 'balance') {
      setBalanceInput(value);
      onUpdateSettings({ ...settings, startingBalance: parseMoneyInput(value) });
    } else {
      setGoInput(value);
      onUpdateSettings({ ...settings, passGoAmount: parseMoneyInput(value) });
    }
  };

  const appendShorthand = (type: 'balance' | 'go', unit: 'K' | 'M') => {
    const current = type === 'balance' ? balanceInput : goInput;
    const upper = current.toUpperCase();
    let newVal = '';
    if (!upper.endsWith('K') && !upper.endsWith('M')) {
      newVal = current + unit;
    } else {
      newVal = current.slice(0, -1) + unit;
    }
    handleInputChange(type, newVal);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-slate-900 border border-white/10 rounded-[2.5rem] w-full max-w-md shadow-2xl overflow-hidden backdrop-blur-2xl flex flex-col max-h-[90vh]">
