  const [dragVisual, setDragVisual] = useState<{
    isDragging: boolean;
    startX: number;
    startY: number;
    currX: number;
    currY: number;
  }>({ isDragging: false, startX: 0, startY: 0, currX: 0, currY: 0 });

  const dragRef = useRef<{
    isDragging: boolean;
    sourceId: string | null;
    startX: number;
    startY: number;
    hasMoved: boolean;
  }>({ isDragging: false, sourceId: null, startX: 0, startY: 0, hasMoved: false });

  const boardRef = useRef<HTMLDivElement>(null);
  const [playerPositions, setPlayerPositions] = useState<{ [key: string]: { x: number, y: number } }>({});

  // Initialize from LocalStorage (with rebrand migration support)
  useEffect(() => {
    let savedGame = localStorage.getItem(STORAGE_KEY);

    // If no new brand state, try to migrate from PolyBank
    if (!savedGame) {
      savedGame = localStorage.getItem(OLD_STORAGE_KEY);
    }

    if (savedGame) {
      try {
        const parsed = JSON.parse(savedGame);
        if (parsed.players) setPlayers(parsed.players);
        if (parsed.transactions) setTransactions(parsed.transactions);
        if (typeof parsed.gameStarted === 'boolean') setGameStarted(parsed.gameStarted);
        if (parsed.currency) setCurrency(parsed.currency);
        if (parsed.settings) {
          setGameSettings(parsed.settings);
          setSetupBalanceInput(parsed.settings.startingBalance.toString());
          setSetupGoInput(parsed.settings.passGoAmount.toString());
        }
      } catch (e) {
        console.error("Failed to load saved state", e);
      }
    }
  }, []);

  // Persist to LocalStorage
  useEffect(() => {
    const stateToSave = { players, transactions, gameStarted, currency, settings: gameSettings };
    localStorage.setItem(STORAGE_KEY, JSON.stringify(stateToSave));
  }, [players, transactions, gameStarted, currency, gameSettings]);

  const handleAddPlayer = () => {
    if (players.length >= 6) return;
    const count = players.length + 1;
    const colorKeys = Object.keys(PLAYER_COLORS) as ThemeColor[];
    const randomColor = colorKeys[Math.floor(Math.random() * colorKeys.length)];

    const newPlayer: Player = {
      id: generateId(),
      name: `Player ${count}`,
      avatar: AVATARS[Math.floor(Math.random() * AVATARS.length)],
      balance: gameStarted ? gameSettings.startingBalance : 0,
      color: randomColor,
      isBankrupt: false
    };
    setPlayers(prev => [...prev, newPlayer]);
  };

  const handleStartGame = () => {
    if (players.length < 2) return;
    const finalStartingBalance = parseMoneyInput(setupBalanceInput);
    const finalPassGoAmount = parseMoneyInput(setupGoInput);

    const finalSettings = {
      startingBalance: finalStartingBalance,
      passGoAmount: finalPassGoAmount
    };

    setGameSettings(finalSettings);
    setPlayers(prev => prev.map(p => ({ ...p, balance: finalStartingBalance, isBankrupt: false })));
    setTransactions([]);
    setGameStarted(true);
  };

  const handleRestartMatch = () => {
    if (window.confirm("Restart current match? This will reset all balances and clear history, but keep players.")) {
      setTransactions([]);
      setPlayers(prev => prev.map(p => ({
        ...p,
        balance: gameSettings.startingBalance,
        isBankrupt: false
      })));
      setIsSettingsOpen(false);
    }
  };

  const handleResetGame = () => {
    if (window.confirm("Return to setup screen? Players and customizations will be preserved, but match data will be cleared.")) {
      setTransactions([]);
      setPlayers(prev => prev.map(p => ({
        ...p,
        balance: gameSettings.startingBalance,
        isBankrupt: false
      })));
      setGameStarted(false);
      setIsSettingsOpen(false);
      setSetupBalanceInput(gameSettings.startingBalance.toString());
      setSetupGoInput(gameSettings.passGoAmount.toString());
    }
  };

  const handleTransaction = (type: TransactionType, fromId: string, toId: string, amount: number) => {
    const newTx: Transaction = {
      id: generateId(),
      timestamp: Date.now(),
      type,
      fromId: fromId as any,
      toId: toId as any,
      amount,
      isReverted: false
    };
    setTransactions(prev => [...prev, newTx]);
    applyTransactionEffect(newTx, false);

    // Trigger Satisfying Feedback
    setShowFeedback(false);
    setTimeout(() => {
      setShowFeedback(true);
      // Auto-hide feedback component after animation completes
      setTimeout(() => setShowFeedback(false), 3000);
    }, 10);
  };

  const applyTransactionEffect = (tx: Transaction, isReversing: boolean) => {
    const { fromId, toId, amount } = tx;
    setPlayers(prevPlayers => prevPlayers.map(p => {
      let newBalance = p.balance;
      if (p.id === fromId) newBalance = isReversing ? p.balance + amount : p.balance - amount;
      if (p.id === toId) newBalance = isReversing ? p.balance - amount : p.balance + amount;
      return { ...p, balance: newBalance };
    }));
  };

  const handleToggleTransaction = (id: string) => {
    const txIndex = transactions.findIndex(t => t.id === id);
    if (txIndex === -1) return;
    const tx = transactions[txIndex];
    const isReverting = !tx.isReverted;
    const updatedTransactions = [...transactions];
    updatedTransactions[txIndex] = { ...tx, isReverted: isReverting };
    setTransactions(updatedTransactions);
    applyTransactionEffect(tx, isReverting);
  };

  const startDeleteTimer = (id: string) => {
    if (id === 'BANK') return;
    setDeleteState(prev => ({ ...prev, id, progress: 0 }));
    const startTime = Date.now();
    if (deleteTimerRef.current) clearInterval(deleteTimerRef.current);
    deleteTimerRef.current = window.setInterval(() => {
      const elapsed = Date.now() - startTime;
      const progress = Math.min((elapsed / REVEAL_DELETE_THRESHOLD_MS) * 100, 100);
      setDeleteState(prev => ({ ...prev, progress }));
      if (progress >= 100) {
        clearInterval(deleteTimerRef.current!);
        deleteTimerRef.current = null;
        setDeleteState(prev => ({ ...prev, id: null, progress: 0, revealedId: id }));
      }
    }, 50);
  };

  const cancelDeleteTimer = () => {
    if (deleteTimerRef.current) { clearInterval(deleteTimerRef.current); deleteTimerRef.current = null; }
    setDeleteState(prev => ({ ...prev, id: null, progress: 0 }));
  };

  const handlePointerDown = (e: React.PointerEvent, id: string) => {
    if (e.button !== 0) return;
    if (deleteState.revealedId && deleteState.revealedId !== id) {
       setDeleteState(prev => ({ ...prev, revealedId: null }));
    }
    const clientX = e.clientX;
    const clientY = e.clientY;
    dragRef.current = { isDragging: true, sourceId: id, startX: clientX, startY: clientY, hasMoved: false };
    setDragVisual({ isDragging: true, startX: clientX, startY: clientY, currX: clientX, currY: clientY });
    startDeleteTimer(id);
    try { (e.target as Element).setPointerCapture(e.pointerId); } catch (err) { }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    if (!dragRef.current.isDragging) return;
    const dx = e.clientX - dragRef.current.startX;
    const dy = e.clientY - dragRef.current.startY;
    if (Math.abs(dx) > 15 || Math.abs(dy) > 15) {
      dragRef.current.hasMoved = true;
      cancelDeleteTimer();
    }
    setDragVisual(prev => ({ ...prev, currX: e.clientX, currY: e.clientY }));
  };

  const handlePointerUp = (e: React.PointerEvent) => {
    cancelDeleteTimer();
    if (!dragRef.current.isDragging) return;
    const { sourceId, hasMoved } = dragRef.current;
    if (!hasMoved && sourceId) {
      if (sourceId === 'BANK') setIsHistoryOpen(true);
      else if (deleteState.revealedId !== sourceId) {
        const player = players.find(p => p.name === sourceId); // Bug here, sourceId is used as name instead of ID
        const playerActual = players.find(p => p.id === sourceId);
        if (playerActual) setPlayerFormState({ isOpen: true, playerToEdit: playerActual });
      }
    } else if (hasMoved && sourceId) {
      const elements = document.elementsFromPoint(e.clientX, e.clientY);
      const targetId = elements.find(el => el.getAttribute('data-id'))?.getAttribute('data-id');
      if (targetId && targetId !== sourceId) {
        setModalState({ isOpen: true, initialFromId: sourceId, initialToId: targetId });
      }
    }
    dragRef.current = { isDragging: false, sourceId: null, startX: 0, startY: 0, hasMoved: false };
    setDragVisual(prev => ({ ...prev, isDragging: false }));
    try { (e.target as Element).releasePointerCapture(e.pointerId); } catch (err) { }
  };

  useEffect(() => {
    if (!gameStarted || !boardRef.current) return;
    const updatePositions = () => {
      if (!boardRef.current) return;
      const { width, height } = boardRef.current.getBoundingClientRect();
      if (width === 0) return;
      const cx = width / 2;
      const cy = height / 2;
      const isMobile = width < 768;
      const rx = (width / 2) - (isMobile ? 85 : 180);
      const ry = (height / 2) - (isMobile ? 130 : 180);
      if (rx <= 20 || ry <= 20) return;
      const newPositions: { [key: string]: { x: number, y: number } } = {};
      const numPlayers = players.length;
      const startAngle = numPlayers === 4 ? -Math.PI / 4 : -Math.PI / 2;
      players.forEach((player, index) => {
        const angle = (index / numPlayers) * 2 * Math.PI + startAngle; 
        newPositions[player.id] = { x: cx + rx * Math.cos(angle), y: cy + ry * Math.sin(angle) };
      });
      setPlayerPositions(newPositions);
    };
    updatePositions();
    const observer = new ResizeObserver(() => updatePositions());
    observer.observe(boardRef.current);
    return () => observer.disconnect();
  }, [players.length, gameStarted]);

  const appendShorthand = (setter: React.Dispatch<React.SetStateAction<string>>, current: string, unit: 'K' | 'M') => {
    const upper = current.toUpperCase();
    if (!upper.endsWith('K') && !upper.endsWith('M')) setter(current + unit);
    else setter(current.slice(0, -1) + unit);
  };

  if (!gameStarted) {
    return (
      <div className="fixed inset-0 bg-slate-950 flex flex-col items-center p-4 md:p-8 font-sans text-slate-100 overflow-y-auto custom-scrollbar">
        <div className="w-full max-w-2xl space-y-8 pb-20">
          <div className="text-center space-y-2 py-8">
            <h1 className="text-7xl font-black text-transparent bg-clip-text bg-gradient-to-r from-cyan-300 via-blue-500 to-indigo-600 drop-shadow-2xl tracking-tighter">BankAIr</h1>
            <p className="text-slate-500 text-lg font-medium tracking-tight">Lite Monopoly Banking Assistant</p>
          </div>
          <div className="glass-panel rounded-[2rem] p-8 shadow-2xl space-y-8 border-white/5 bg-white/5">
            <div className="space-y-4">
              <label className="text-xs font-black text-cyan-400 uppercase tracking-[0.2em]">Currency</label>
              <div className="grid grid-cols-4 sm:grid-cols-8 gap-2">
                {CURRENCIES.map((c) => (
                  <button key={c.name} onClick={() => setCurrency(c)} className={`flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all ${currency.name === c.name ? 'bg-cyan-500 border-cyan-400 shadow-lg shadow-cyan-500/20' : 'bg-white/5 border-white/5 text-slate-400'}`}>
                    <span className="text-xl font-black">{c.symbol}</span>
                  </button>
                ))}
              </div>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
              <div className="space-y-3">
                <label className="text-xs font-black text-cyan-400 uppercase tracking-[0.2em]">Initial Balance</label>
                <div className="relative">
                  <input type="text" inputMode="numeric" value={setupBalanceInput} onChange={(e) => setSetupBalanceInput(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-2xl py-5 pl-6 pr-16 text-white font-mono text-xl focus:ring-4 focus:ring-cyan-500/20 outline-none uppercase transition-all" />
                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                    <button onClick={() => appendShorthand(setSetupBalanceInput, setupBalanceInput, 'K')} className="bg-white/10 px-2 py-1 rounded text-[10px] font-black">K</button>
                    <button onClick={() => appendShorthand(setSetupBalanceInput, setupBalanceInput, 'M')} className="bg-white/10 px-2 py-1 rounded text-[10px] font-black">M</button>
                  </div>
                  <div className="absolute left-6 -bottom-5 text-[10px] font-black text-cyan-400 opacity-60">{formatFullAmount(parseMoneyInput(setupBalanceInput), currency)}</div>
                </div>
              </div>
              <div className="space-y-3">
                <label className="text-xs font-black text-cyan-400 uppercase tracking-[0.2em]">GO Reward</label>
                <div className="relative">
                  <input type="text" inputMode="numeric" value={setupGoInput} onChange={(e) => setSetupGoInput(e.target.value)} className="w-full bg-black/40 border border-white/10 rounded-2xl py-5 pl-6 pr-16 text-white font-mono text-xl focus:ring-4 focus:ring-cyan-500/20 outline-none uppercase transition-all" />
                  <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                    <button onClick={() => appendShorthand(setSetupGoInput, setupGoInput, 'K')} className="bg-white/10 px-2 py-1 rounded text-[10px] font-black">K</button>
                    <button onClick={() => appendShorthand(setSetupGoInput, setupGoInput, 'M')} className="bg-white/10 px-2 py-1 rounded text-[10px] font-black">M</button>
                  </div>
                  <div className="absolute left-6 -bottom-5 text-[10px] font-black text-cyan-400 opacity-60">{formatFullAmount(parseMoneyInput(setupGoInput), currency)}</div>
                </div>
              </div>
            </div>
          </div>
          <div className="glass-panel rounded-[2rem] p-8 shadow-2xl space-y-6 border-white/5 bg-white/5">
            <div className="flex items-center justify-between border-b border-white/10 pb-6">
               <h2 className="text-2xl font-black text-white tracking-tight">Players ({players.length}/6)</h2>
               <button onClick={handleAddPlayer} disabled={players.length >= 6} className="bg-cyan-500 text-white p-3 rounded-2xl active:scale-90 transition-transform">
                 <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M12 4v16m8-8H4" /></svg>
               </button>
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              {players.map((player) => (
                <div key={player.id} className="flex items-center gap-4 bg-white/5 p-4 rounded-2xl border border-white/5">
                  <span className="text-4xl">{player.avatar}</span>
                  <input type="text" value={player.name} onChange={(e) => setPlayers(prev => prev.map(p => p.id === player.id ? { ...p, name: e.target.value } : p))} className="bg-transparent text-white font-black w-full outline-none" />
                  <button onClick={() => setPlayers(prev => prev.filter(p => p.id !== player.id))} className="text-slate-600 hover:text-red-500"><svg className="w-5 h-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
                </div>
              ))}
            </div>
          </div>
          <Button fullWidth size="lg" onClick={handleStartGame} disabled={players.length < 2} className="rounded-[2rem] !py-6 !text-2xl !font-black !bg-gradient-to-r !from-cyan-500 !to-blue-600">Start Session 🏁</Button>
        </div>
        <PlayerFormModal isOpen={playerFormState.isOpen} onClose={() => setPlayerFormState({ isOpen: false })} initialData={playerFormState.playerToEdit} onSave={(data) => { if (playerFormState.playerToEdit) setPlayers(prev => prev.map(p => p.id === playerFormState.playerToEdit?.id ? { ...p, ...data } : p)); }} />
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-slate-950 overflow-hidden touch-none" onPointerMove={handlePointerMove} onPointerUp={handlePointerUp} onContextMenu={(e) => e.preventDefault()}>
      {showFeedback && <TransactionFeedback />}

      <div className="absolute top-0 left-0 right-0 p-6 flex justify-between items-start z-[100] pointer-events-none">
        <button onClick={() => setIsSettingsOpen(true)} className="bg-black/40 text-slate-400 p-4 rounded-3xl border border-white/10 hover:text-white pointer-events-auto transition-all">
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924-1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" /><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" /></svg>
        </button>
        <button onClick={() => setIsHistoryOpen(true)} className="bg-black/40 text-slate-400 p-4 rounded-3xl border border-white/10 pointer-events-auto">📜</button>
      </div>
      <div ref={boardRef} className="absolute inset-0 z-0">
        <BankCard currency={currency} onDragStart={handlePointerDown} />
        {players.map((player) => (
          <PlayerCard key={player.id} player={player} currency={currency} onEditName={() => {}} onDragStart={handlePointerDown} onDeleteClick={() => setPlayers(prev => prev.filter(p => p.id !== player.id))} showDeleteButton={deleteState.revealedId === player.id} deleteProgress={deleteState.id === player.id ? deleteState.progress : 0} style={{ left: playerPositions[player.id]?.x || '50%', top: playerPositions[player.id]?.y || '50%', opacity: playerPositions[player.id] ? 1 : 0, transition: (deleteState.id === player.id) ? 'none' : 'opacity 0.4s, left 0.6s cubic-bezier(0.34, 1.56, 0.64, 1), top 0.6s cubic-bezier(0.34, 1.56, 0.64, 1)' }} />
        ))}
      </div>
      {dragVisual.isDragging && <div className="absolute inset-0 pointer-events-none z-[110]"><svg className="w-full h-full"><line x1={dragVisual.startX} y1={dragVisual.startY} x2={dragVisual.currX} y2={dragVisual.currY} stroke="#22d3ee" strokeWidth="4" strokeDasharray="10 10" className="opacity-40" /></svg></div>}
      <TransactionModal isOpen={modalState.isOpen} initialFromId={modalState.initialFromId} initialToId={modalState.initialToId} onClose={() => setModalState({ isOpen: false })} players={players} currency={currency} passGoAmount={gameSettings.passGoAmount} onTransaction={handleTransaction} />
      <HistoryLogModal isOpen={isHistoryOpen} onClose={() => setIsHistoryOpen(false)} transactions={transactions} players={players} currency={currency} onToggleTransaction={handleToggleTransaction} />
      <PlayerFormModal isOpen={playerFormState.isOpen} onClose={() => setPlayerFormState({ isOpen: false })} initialData={playerFormState.playerToEdit} onSave={(data) => { if (playerFormState.playerToEdit) setPlayers(prev => prev.map(p => p.id === playerFormState.playerToEdit?.id ? { ...p, ...data } : p)); }} />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={gameSettings} onUpdateSettings={setGameSettings} onResetGame={handleResetGame} onRestartMatch={handleRestartMatch} currency={currency} onUpdateCurrency={setCurrency} playerCount={players.length} onAddPlayer={handleAddPlayer} />
    </div>
  );
};

export default App;

import React from 'react';
import { Player, Currency } from '../types';
import { PLAYER_COLORS, PLAYER_BORDER_COLORS } from '../constants';
import { ThemeColor } from '../types';

interface PlayerCardProps {
  player: Player;
  currency: Currency;
  onEditName: (name: string) => void;
  onDragStart: (e: React.PointerEvent, id: string) => void;
  onDeleteClick: (id: string) => void;
  showDeleteButton?: boolean;
  deleteProgress?: number; // 0 to 100
  style?: React.CSSProperties;
  className?: string;
}

const PlayerCard: React.FC<PlayerCardProps> = ({ 
  player, 
  currency, 
  onEditName, 
  onDragStart, 
  onDeleteClick,
  showDeleteButton = false,
  deleteProgress = 0,
  style, 
  className = '' 
}) => {
  const colorKey = player.color as ThemeColor;

  const borderColor = PLAYER_BORDER_COLORS[colorKey] || 'border-slate-500';
  const glowColor = PLAYER_COLORS[colorKey] || 'bg-slate-500';

  const formatMoney = (amount: number) => {
    // Standardizing on en-US for comma thousands separator
    const displayVal = amount.toLocaleString('en-US');

    return currency.position === 'prefix' 
      ? `${currency.symbol}${displayVal}`
      : `${displayVal}${currency.symbol}`;
  };

  const isActivating = deleteProgress > 0 && deleteProgress < 100;
  const jiggleClass = showDeleteButton ? 'animate-jiggle' : '';

  return (
    <div 
      className={`absolute flex flex-col items-center touch-none select-none group cursor-grab active:cursor-grabbing ${className} ${jiggleClass}`}
      style={{
        ...style,
        transform: 'translate(-50%, -50%)',
        width: 'max-content',
        transition: isActivating ? 'none' : (style?.transition || 'all 0.4s ease-out'),
        zIndex: showDeleteButton ? 100 : style?.zIndex
      }}
      onPointerDown={(e) => onDragStart(e, player.id)}
      data-id={player.id}
    >
      {/* Avatar Circle */}
      <div 
        className={`relative w-28 h-28 md:w-40 md:h-40 rounded-full border-[6px] md:border-[8px] ${borderColor} shadow-[0_0_30px_rgba(0,0,0,0.6)] z-20 flex items-center justify-center bg-gradient-to-b from-slate-700 to-slate-900`}
      >
        {/* Activation Progress Ring */}
        {isActivating && (
          <div className="absolute inset-0 z-30 pointer-events-none">
            <svg className="w-full h-full rotate-[-90deg]">
              <circle
                cx="50%"
                cy="50%"
                r="48%"
                fill="transparent"
                stroke="rgba(34, 211, 238, 0.6)"
                strokeWidth="8"
                strokeDasharray="301.6"
                strokeDashoffset={301.6 - (301.6 * deleteProgress) / 100}
                className="transition-all duration-75 ease-linear"
              />
            </svg>
          </div>
        )}

        {/* Delete Button (X) */}
        {showDeleteButton && (
          <button
            onClick={(e) => {
              e.stopPropagation();
              onDeleteClick(player.id);
            }}
            onPointerDown={(e) => e.stopPropagation()}
            onPointerUp={(e) => e.stopPropagation()}
            className="absolute -top-3 -right-3 w-12 h-12 md:w-16 md:h-16 bg-red-600 border-4 border-slate-900 rounded-full flex items-center justify-center text-white shadow-xl z-[120] hover:bg-red-500 hover:scale-110 active:scale-90 transition-all animate-pop-in pointer-events-auto"
          >
            <svg className="w-7 h-7 md:w-9 md:h-9" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        )}

        <div className="absolute inset-0 rounded-full bg-gradient-to-tr from-white/10 to-transparent pointer-events-none"></div>
        <div className={`absolute -inset-2 rounded-full opacity-0 group-hover:opacity-40 blur-xl transition-opacity duration-300 ${glowColor}`}></div>

        <span className="text-5xl md:text-7xl relative z-10 filter drop-shadow-lg select-none leading-none transform group-hover:rotate-6 transition-transform">
          {player.avatar}
        </span>

        {player.isBankrupt && (
          <div className="absolute inset-0 bg-black/80 rounded-full flex items-center justify-center z-40 border-4 border-red-600">
            <span className="text-4xl md:text-6xl">💀</span>
          </div>
        )}
      </div>

      {/* Info Pill - Refined Alignment without Scale */}
      <div className={`mt-3 flex flex-col items-center z-30 filter drop-shadow-xl transition-all ${showDeleteButton ? 'opacity-30 blur-[1px]' : 'opacity-100'}`}>
        <div className="bg-slate-900/95 backdrop-blur-md rounded-t-xl px-4 py-1.5 text-[11px] md:text-sm text-white font-black text-center w-24 md:w-32 border-b border-white/10 truncate tracking-wide">
          {player.name}
        </div>
        <div className={`bg-slate-800/95 backdrop-blur-md border border-t-0 border-white/10 rounded-b-xl px-4 py-1.5 min-w-[6rem] md:min-w-[8rem] text-center shadow-lg ${player.balance < 0 ? 'text-red-400' : 'text-emerald-400'}`}>
          <span className="text-sm md:text-lg font-black font-mono tracking-tight">
            {formatMoney(player.balance)}
          </span>
        </div>
      </div>

      <style>{`
        @keyframes jiggle {
          0% { transform: translate(-50%, -50%) rotate(-1deg); }
          50% { transform: translate(-50%, -50%) rotate(1deg); }
          100% { transform: translate(-50%, -50%) rotate(-1deg); }
        }
        @keyframes pop-in {
          0% { transform: scale(0); opacity: 0; }
          70% { transform: scale(1.2); opacity: 1; }
          100% { transform: scale(1); opacity: 1; }
        }
        .animate-jiggle { animation: jiggle 0.3s infinite ease-in-out; }
        .animate-pop-in { animation: pop-in 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275) forwards; }
      `}</style>
    </div>
  );
};

export default PlayerCard;

import React, { useRef } from 'react';
import { Transaction, Player, TransactionType, Currency } from '../types';

interface HistoryLogProps {
  transactions: Transaction[];
  players: Player[];
  currency: Currency;
  onToggleTransaction: (id: string) => void;
}

const HistoryLog: React.FC<HistoryLogProps> = ({ transactions, players, currency, onToggleTransaction }) => {
  const scrollRef = useRef<HTMLDivElement>(null);

  const getPlayer = (id: string) => {
    if (id === 'BANK') return { name: 'Bank', avatar: '🏛️' };
    const p = players.find(p => p.id === id);
    return p ? { name: p.name, avatar: p.avatar } : { name: 'Unknown', avatar: '❓' };
  };

  const formatMoney = (amount: number) => {
    const displayVal = amount.toLocaleString('en-US');
    return currency.position === 'prefix' ? `${currency.symbol}${displayVal}` : `${displayVal}${currency.symbol}`;
  };

  if (transactions.length === 0) {
    return (
      <div className="flex flex-col items-center justify-center h-full text-slate-500 p-8 text-center">
        <span className="text-4xl mb-2 opacity-30">📜</span>
        <p className="text-sm">No transactions yet.</p>
      </div>
    );
  }

  const displayTransactions = [...transactions].reverse();

  return (
    <div ref={scrollRef} className="h-full overflow-y-auto space-y-3 pr-2 custom-scrollbar">
      {displayTransactions.map((tx) => {
        const isDeposit = tx.toId !== 'BANK' && tx.fromId === 'BANK';
        const isPayment = tx.fromId !== 'BANK' && tx.toId === 'BANK';

        const fromPlayer = getPlayer(tx.fromId);
        const toPlayer = getPlayer(tx.toId);

        let icon = '';
        let colorClass = 'text-slate-300';

        if (tx.type === TransactionType.PASS_GO) {
          icon = '🏁';
          colorClass = 'text-emerald-400';
        } else if (isDeposit) {
          icon = '🏦';
          colorClass = 'text-emerald-400';
        } else if (isPayment) {
          icon = '📉';
          colorClass = 'text-red-400';
        } else {
            icon = '💸';
        }

        const isReverted = tx.isReverted;

        return (
          <div 
            key={tx.id} 
            className={`rounded-lg p-3 border transition-all ${
              isReverted 
                ? 'bg-red-900/10 border-red-500/20 opacity-60' 
                : 'bg-slate-800/50 border-slate-700/50'
            }`}
          >
            <div className="flex justify-between items-start mb-2">
              <div className="flex items-center gap-2">
                 <span className={`text-lg ${isReverted ? 'grayscale' : ''}`}>{icon}</span>
                 {isReverted && <span className="text-xs font-bold text-red-500 uppercase tracking-wider border border-red-500/50 px-1 rounded">Undone</span>}
              </div>
               <span className={`font-mono font-bold ${isReverted ? 'line-through text-slate-500' : colorClass}`}>
                 {formatMoney(tx.amount)}
               </span>
            </div>

            <div className={`flex items-center justify-between p-2 rounded ${isReverted ? 'bg-black/20 text-slate-500' : 'text-slate-300 bg-slate-900/50'}`}>
              <div className="flex items-center gap-1.5 overflow-hidden">
                <span className="text-base">{fromPlayer.avatar}</span>
                <span className="truncate">{fromPlayer.name}</span>
              </div>
              <span className="text-slate-600 px-1">➜</span>
              <div className="flex items-center gap-1.5 overflow-hidden justify-end">
                <span className="truncate">{toPlayer.name}</span>
                <span className="text-base">{toPlayer.avatar}</span>
              </div>
            </div>

            <div className="flex justify-between items-center mt-2">
               <span className="text-[10px] text-slate-600">
                {new Date(tx.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
              </span>

              <button 
                onClick={() => onToggleTransaction(tx.id)}
                className={`text-xs px-2 py-1 rounded border transition-colors ${
                  isReverted
                    ? 'bg-emerald-500/20 border-emerald-500/30 text-emerald-400 hover:bg-emerald-500/30'
                    : 'bg-slate-700/50 border-slate-600 text-slate-400 hover:bg-red-500/20 hover:text-red-400 hover:border-red-500/30'
                }`}
              >
                {isReverted ? 'Redo' : 'Undo'}
              </button>
            </div>
          </div>
        );
      })}
    </div>
  );
};

export default HistoryLog;

import React, { useState, useEffect } from 'react';
import { Player, TransactionType, Currency } from '../types';
import Button from './Button';

interface TransactionModalProps {
  isOpen: boolean;
  initialFromId?: string;
  initialToId?: string;
  onClose: () => void;
  players: Player[];
  currency: Currency;
  passGoAmount: number;
  onTransaction: (type: TransactionType, fromId: string, toId: string, amount: number) => void;
}

const TransactionModal: React.FC<TransactionModalProps> = ({ 
  isOpen, 
  initialFromId, 
  initialToId, 
  onClose, 
  players, 
  currency,
  passGoAmount,
  onTransaction 
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'bank' | 'go'>('transfer');

  const [fromId, setFromId] = useState<string>('');
  const [toId, setToId] = useState<string>('');
  const [amount, setAmount] = useState<string>(''); 

  const [bankPlayerId, setBankPlayerId] = useState<string>('');
  const [bankAction, setBankAction] = useState<'pay' | 'receive'>('pay');

  useEffect(() => {
    if (isOpen) {
      if (initialFromId === 'BANK' && initialToId && initialToId !== 'BANK') {
        setActiveTab('bank');
        setBankAction('receive');
        setBankPlayerId(initialToId);
      } else if (initialToId === 'BANK' && initialFromId && initialFromId !== 'BANK') {
        setActiveTab('bank');
        setBankAction('pay');
        setBankPlayerId(initialFromId);
      } else if (initialFromId && initialToId && initialFromId !== 'BANK' && initialToId !== 'BANK') {
        setActiveTab('transfer');
        setFromId(initialFromId);
        setToId(initialToId);
      } else {
        setActiveTab('transfer');
        setFromId('');
        setToId('');
        setBankPlayerId('');
      }
      setAmount('');
    }
  }, [isOpen, initialFromId, initialToId]);

  if (!isOpen) return null;

  const parseValue = (val: string): number => {
    const clean = val.toLowerCase().replace(/,/g, '').replace(/\./g, '').trim();
    if (!clean) return 0;

    let multiplier = 1;
    let numericPart = clean;

    if (clean.endsWith('m')) {
      multiplier = 1000000;
      numericPart = clean.slice(0, -1);
    } else if (clean.endsWith('k')) {
      multiplier = 1000;
      numericPart = clean.slice(0, -1);
    }

    const num = parseFloat(numericPart);
    return isNaN(num) ? 0 : Math.floor(num * multiplier);
  };

  const handleTransfer = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = parseValue(amount);
    if (fromId && toId && numericAmount > 0 && fromId !== toId) {
      onTransaction(TransactionType.TRANSFER, fromId, toId, numericAmount);
      onClose();
    }
  };

  const handleBankTransaction = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = parseValue(amount);
    if (bankPlayerId && numericAmount > 0) {
      if (bankAction === 'pay') {
        onTransaction(TransactionType.BANK_DEPOSIT, bankPlayerId, 'BANK', numericAmount);
      } else {
        onTransaction(TransactionType.BANK_WITHDRAWAL, 'BANK', bankPlayerId, numericAmount);
      }
      onClose();
    }
  };

  const handlePassGo = () => {
    if (bankPlayerId) {
      onTransaction(TransactionType.PASS_GO, 'BANK', bankPlayerId, passGoAmount);
      onClose();
    }
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    // Allow numeric, dots, commas, and k/m shorthand
    if (/^[0-9.,kmKM]*$/.test(val)) {
      setAmount(val);
    }
  };

  const formatMoneyDisplay = (amount: number) => {
    const displayVal = amount.toLocaleString('en-US');
    return currency.position === 'prefix' ? `${currency.symbol}${displayVal}` : `${displayVal}${currency.symbol}`;
  };

  const formatFullAmountPreview = (amount: number) => {
    const displayVal = amount.toLocaleString('en-US');
    return currency.position === 'prefix' 
      ? `${currency.symbol}${displayVal}` 
      : `${displayVal}${currency.symbol}`;
  };

  const appendUnit = (unit: 'K' | 'M') => {
    const cleanAmount = amount.toUpperCase();
    if (!cleanAmount.endsWith('K') && !cleanAmount.endsWith('M')) {
      setAmount(amount + unit);
    } else {
      setAmount(amount.slice(0, -1) + unit);
    }
  };

  const renderAmountInput = (value: string, setter: (v: string) => void) => {
    const numericValue = parseValue(value);

    return (
      <div className="space-y-4">
        <label className="block text-xs font-black text-blue-300 uppercase tracking-widest">Amount</label>
        <div className="relative group">
          <input 
            type="text" 
            inputMode="numeric"
            value={value} 
            onChange={handleAmountChange}
            className="w-full bg-black/40 border-2 border-white/10 text-white rounded-[1.5rem] p-6 text-5xl font-mono text-center focus:ring-4 focus:ring-cyan-500/20 focus:border-cyan-500/50 outline-none transition-all shadow-inner uppercase placeholder:opacity-20" 
            placeholder="0" 
            required 
          />
          <div className="absolute right-3 top-1/2 -translate-y-1/2 flex flex-col gap-2">
            <button 
              type="button" 
              onClick={() => appendUnit('K')} 
              className="bg-cyan-600 hover:bg-cyan-500 text-white font-black px-4 py-2 rounded-xl text-sm shadow-lg transition-transform active:scale-90 border border-white/10"
            >
              K
            </button>
            <button 
              type="button" 
              onClick={() => appendUnit('M')} 
              className="bg-purple-600 hover:bg-purple-500 text-white font-black px-4 py-2 rounded-xl text-sm shadow-lg transition-transform active:scale-90 border border-white/10"
            >
              M
            </button>
          </div>
        </div>

        {numericValue > 0 && (
          <div className="flex justify-center">
            <div className="bg-cyan-500/10 border-2 border-cyan-500/30 px-6 py-2 rounded-full animate-in fade-in slide-in-from-top-2 duration-300 shadow-[0_0_15px_rgba(34,211,238,0.2)]">
              <span className="text-base font-black text-cyan-400">
                Resolved: {formatFullAmountPreview(numericValue)}
              </span>
            </div>
          </div>
        )}

        <div className="grid grid-cols-4 gap-2">
          {[50, 100, 200, 500].map(amt => (
            <button 
              key={amt} 
              type="button" 
              onClick={() => setter(amt.toString())} 
              className="bg-white/5 hover:bg-white/10 text-blue-200 font-black py-4 rounded-xl border border-white/5 transition-all active:bg-cyan-500/20 text-sm"
            >
              {amt}
            </button>
          ))}
        </div>
      </div>
    );
  };

  const renderPlayerSelect = (value: string, onChange: (val: string) => void, excludeId?: string, label?: string) => (
    <div className="space-y-2">
      {label && <label className="block text-xs font-black text-blue-300 uppercase tracking-widest">{label}</label>}
      <div className="relative">
        <select 
          value={value} 
          onChange={(e) => onChange(e.target.value)}
          className="w-full bg-black/40 border-2 border-white/10 text-white rounded-2xl p-5 pl-14 appearance-none focus:ring-4 focus:ring-cyan-500/20 focus:border-cyan-500/50 outline-none transition-all backdrop-blur-sm cursor-pointer"
          required
        >
          <option value="" className="bg-slate-900">Select Player</option>
          {players.filter(p => p.id !== excludeId).map(p => (
            <option key={p.id} value={p.id} className="bg-slate-900">{p.name} ({formatMoneyDisplay(p.balance)})</option>
          ))}
        </select>
        <div className="absolute left-5 top-1/2 -translate-y-1/2 text-3xl pointer-events-none">
          {value ? players.find(p => p.id === value)?.avatar : '👤'}
        </div>
        <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-white/20">
          <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 9l-7 7-7-7" /></svg>
        </div>
      </div>
    </div>
  );

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in zoom-in duration-200">
      <div className="bg-slate-900 border border-white/10 rounded-[2.5rem] w-full max-w-md shadow-2xl overflow-hidden backdrop-blur-2xl">

        {/* Modern Tab HUD */}
        <div className="flex bg-black/30 p-2 gap-1">
          {(['transfer', 'bank', 'go'] as const).map(tab => (
            <button 
              key={tab}
              onClick={() => setActiveTab(tab)} 
              className={`flex-1 py-4 rounded-2xl text-xs font-black uppercase tracking-[0.2em] transition-all ${
                activeTab === tab 
                  ? 'bg-gradient-to-r from-cyan-600 to-blue-600 text-white shadow-lg' 
                  : 'text-slate-500 hover:text-slate-300 hover:bg-white/5'
              }`}
            >
              {tab === 'transfer' ? 'Transfer' : tab === 'bank' ? 'Bank' : 'Go'}
            </button>
          ))}
        </div>

        <div className="p-8">
          {activeTab === 'transfer' && (
            <form onSubmit={handleTransfer} className="space-y-6">
              {renderPlayerSelect(fromId, setFromId, undefined, "Sender")}
              <div className="flex justify-center -my-3 relative z-10">
                <div className="bg-slate-800 rounded-full p-3 border-2 border-slate-700 shadow-xl text-cyan-400">
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 14l-7 7m0 0l-7-7m7 7V3" /></svg>
                </div>
              </div>
              {renderPlayerSelect(toId, setToId, fromId, "Recipient")}
              {renderAmountInput(amount, setAmount)}
              <div className="pt-6 flex gap-4">
                <Button type="button" variant="ghost" fullWidth onClick={onClose} className="rounded-2xl py-4">Cancel</Button>
                <Button type="submit" fullWidth disabled={!fromId || !toId || parseValue(amount) <= 0} className="bg-cyan-600 rounded-2xl py-4 text-lg shadow-xl shadow-cyan-500/20">Send</Button>
              </div>
            </form>
          )}

          {activeTab === 'bank' && (
            <form onSubmit={handleBankTransaction} className="space-y-6">
              <div className="flex bg-black/40 rounded-[1.2rem] p-1.5 gap-1">
                {(['pay', 'receive'] as const).map(action => (
                  <button 
                    key={action}
                    type="button"
                    onClick={() => setBankAction(action)}
                    className={`flex-1 py-3 rounded-xl text-xs font-black uppercase tracking-widest transition-all ${
                      bankAction === action 
                        ? (action === 'pay' ? 'bg-red-500' : 'bg-emerald-500') + ' text-white shadow-lg'
                        : 'text-slate-500 hover:text-slate-400'
                    }`}
                  >
                    {action === 'pay' ? 'Pay Bank' : 'Collect'}
                  </button>
                ))}
              </div>
              {renderPlayerSelect(bankPlayerId, setBankPlayerId, undefined, "Select Player")}
              {renderAmountInput(amount, setAmount)}
              <div className="pt-6 flex gap-4">
                <Button type="button" variant="ghost" fullWidth onClick={onClose} className="rounded-2xl py-4">Cancel</Button>
                <Button 
                  type="submit" 
                  fullWidth 
                  disabled={!bankPlayerId || parseValue(amount) <= 0} 
                  className={`${bankAction === 'pay' ? "bg-red-500" : "bg-emerald-500"} rounded-2xl py-4 text-lg shadow-xl transition-colors`}
                >
                  {bankAction === 'pay' ? 'Pay Bank' : 'Receive Funds'}
                </Button>
              </div>
            </form>
          )}

          {activeTab === 'go' && (
            <div className="space-y-8 text-center">
              <div className="bg-emerald-500/10 border-2 border-emerald-500/20 rounded-[2.5rem] p-10 space-y-4 shadow-inner">
                <div className="text-6xl animate-bounce">🏁</div>
                <h3 className="text-3xl font-black text-emerald-400">Collect {formatMoneyDisplay(passGoAmount)}</h3>
                <p className="text-slate-500 text-xs font-bold uppercase tracking-widest">Passed Go Reward</p>
              </div>
              {renderPlayerSelect(bankPlayerId, setBankPlayerId, undefined, "Player reaching GO")}
              <div className="pt-6 flex gap-4">
                <Button variant="ghost" fullWidth onClick={onClose} className="rounded-2xl py-4">Cancel</Button>
                <Button fullWidth onClick={handlePassGo} disabled={!bankPlayerId} className="bg-emerald-500 rounded-2xl py-4 text-lg shadow-xl shadow-emerald-500/20">Collect</Button>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

