import React, { useState, useEffect, useRef } from 'react';
import { Player, TransactionType } from '../types';
import { parseTransactionCommand } from '../services/geminiService';
import Button from './Button';

interface CommandCenterProps {
  isOpen: boolean;
  onClose: () => void;
  players: Player[];
  onTransaction: (type: TransactionType, fromId: string, toId: string, amount: number) => void;
}

const CommandCenter: React.FC<CommandCenterProps> = ({ isOpen, onClose, players, onTransaction }) => {
  const [input, setInput] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;
      recognitionRef.current.lang = 'en-US';

      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInput(transcript);
        setIsListening(false);
      };

      recognitionRef.current.onerror = (event: any) => {
        console.error('Speech recognition error', event.error);
        setIsListening(false);
        setError("Failed to capture audio. Try typing?");
      };

      recognitionRef.current.onend = () => {
        setIsListening(false);
      };
    }
  }, []);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      setError(null);
      setInput('');
      try {
        recognitionRef.current?.start();
        setIsListening(true);
      } catch (e) {
        setError("Microphone unavailable.");
      }
    }
  };

  const handleProcess = async () => {
    if (!input.trim() || isProcessing) return;
    setIsProcessing(true);
    setError(null);

    const result = await parseTransactionCommand(input, players);

    if (result) {
      onTransaction(result.type, result.fromId, result.toId, result.amount);
      onClose();
      setInput('');
    } else {
      setError("I didn't quite catch that. Try saying something like 'Joe pays Sarah 50k'.");
    }
    setIsProcessing(false);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[300] flex items-end sm:items-center justify-center p-4 bg-black/80 backdrop-blur-xl animate-in fade-in duration-300">
      <div className="bg-slate-900 border border-white/10 rounded-[2.5rem] w-full max-w-lg shadow-2xl overflow-hidden backdrop-blur-3xl animate-in slide-in-from-bottom-10">
        <div className="p-8 space-y-8">
          <div className="flex justify-between items-center">
            <div className="flex items-center gap-3">
              <span className="text-3xl animate-pulse">✨</span>
              <h3 className="text-2xl font-black text-white tracking-tight">AI Command Center</h3>
            </div>
            <button onClick={onClose} className="text-slate-500 hover:text-white transition-colors p-2">
              <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          </div>

          <div className="space-y-4">
            <div className="relative group">
              <textarea
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ex: 'Player 1 pays 200 to bank' or 'Pass Go Joe'"
                className="w-full bg-black/40 border-2 border-white/10 text-white rounded-[1.5rem] p-6 text-xl min-h-[120px] focus:ring-4 focus:ring-cyan-500/20 focus:border-cyan-500/50 outline-none transition-all resize-none placeholder:text-slate-600 font-medium"
              />

              <button 
                onClick={toggleListening}
                className={`absolute right-4 bottom-4 p-4 rounded-2xl transition-all ${
                  isListening 
                    ? 'bg-red-500 animate-pulse scale-110 shadow-[0_0_20px_rgba(239,68,68,0.5)]' 
                    : 'bg-white/10 hover:bg-white/20 text-cyan-400'
                }`}
              >
                <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  {isListening ? (
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z M9 10a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1h-4a1 1 0 01-1-1v-4z" />
                  ) : (
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                  )}
                </svg>
              </button>
            </div>

            {error && (
              <div className="bg-red-500/10 border border-red-500/20 rounded-xl p-4 text-red-400 text-sm font-bold animate-in slide-in-from-top-2">
                ⚠️ {error}
              </div>
            )}
          </div>

          <div className="flex gap-4">
            <Button 
              variant="ghost" 
              fullWidth 
              onClick={onClose} 
              className="rounded-2xl py-4"
            >
              Cancel
            </Button>
            <Button 
              fullWidth 
              onClick={handleProcess} 
              disabled={!input.trim() || isProcessing}
              className="bg-gradient-to-r from-cyan-600 to-indigo-600 rounded-2xl py-4 text-lg font-black shadow-xl shadow-cyan-500/20 relative"
            >
              {isProcessing ? (
                <div className="flex items-center gap-2">
                  <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
                  Parsing...
                </div>
              ) : 'Execute 🚀'}
            </Button>
          </div>

          <p className="text-center text-slate-500 text-xs font-bold uppercase tracking-widest">
            AI handles nicknames, typos, and units (k/m)
          </p>
        </div>
      </div>
    </div>
  );
};

