    if (!upper.endsWith('K') && !upper.endsWith('M')) {
      newVal = current + unit;
    } else {
      newVal = current.slice(0, -1) + unit;
    }

    if (type === 'balance') {
      setLocalBalance(newVal);
      onUpdateSettings({ ...settings, startingBalance: parseMoneyInput(newVal) });
