  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[300] flex items-end sm:items-center justify-center p-4 bg-black/90 backdrop-blur-2xl animate-in fade-in duration-300">
      <div className="bg-slate-900/90 border-2 border-cyan-500/20 rounded-[3rem] w-full max-w-lg shadow-[0_0_100px_rgba(8,145,178,0.2)] overflow-hidden animate-in slide-in-from-bottom-10 relative">

        {/* Matrix Rain Decoration (Subtle) */}
        <div className="absolute inset-0 opacity-5 pointer-events-none overflow-hidden">
          <div className="text-cyan-400 font-mono-tech text-[10px] break-all leading-none animate-[matrix_20s_linear_infinite]">
            0101100101101010110101011010101010110101011010101101010110101010101101010110101011010101101010101011010101101010110101011010101010110101011010101101010110101010101
          </div>
        </div>

        <div className="p-10 space-y-10 relative z-10">
          <div className="flex justify-between items-center">
            <div className="flex flex-col">
              <div className="flex items-center gap-3">
                <div className="w-3 h-3 rounded-full bg-cyan-500 pulse-cyan"></div>
                <h3 className="text-2xl font-black text-white tracking-tight uppercase italic">Neural Command</h3>
              </div>
              <span className="text-[10px] font-black text-cyan-400/50 uppercase tracking-[0.5em] mt-1 ml-6">v2.5 Link Active</span>
            </div>
            <button onClick={onClose} className="text-slate-500 hover:text-white transition-all p-3 hover:bg-white/5 rounded-full active:scale-90">
              <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
