            </Button>
          </div>

          <div className="flex items-center justify-center gap-6 opacity-30">
             <div className="h-[1px] flex-1 bg-white/20"></div>
             <span className="text-[9px] font-black uppercase tracking-[0.5em] text-cyan-400">Secure Protocol Interface</span>
             <div className="h-[1px] flex-1 bg-white/20"></div>
