import React, { useState, useEffect } from 'react';
import { GameSettings, Currency } from '../types';
import { CURRENCIES } from '../constants';
import Button from './Button';

interface SettingsModalProps {
  isOpen: boolean;
  onClose: () => void;
  settings: GameSettings;
  onUpdateSettings: (settings: GameSettings) => void;
  currency: Currency;
  onUpdateCurrency: (currency: Currency) => void;
  playerCount: number;
  onAddPlayer: () => void;
}

const parseMoneyInput = (val: string): number => {
  let str = val.toLowerCase().replace(/,/g, '').trim();
  if (!str) return 0;

  let multiplier = 1;
  if (str.endsWith('m')) {
    multiplier = 1000000;
    str = str.slice(0, -1);
  } else if (str.endsWith('k')) {
    multiplier = 1000;
    str = str.slice(0, -1);
  }

  const num = parseFloat(str);
  return isNaN(num) ? 0 : Math.floor(num * multiplier);
};

const formatFullAmount = (amount: number, currency: Currency) => {
  const formatted = (amount ?? 0).toLocaleString('en-US');
  return currency.position === 'prefix' ? `${currency.symbol}${formatted}` : `${formatted}${currency.symbol}`;
};

const SettingsModal: React.FC<SettingsModalProps> = ({
  isOpen,
  onClose,
  settings,
  onUpdateSettings,
  currency,
  onUpdateCurrency,
  playerCount,
  onAddPlayer
}) => {
  const [localBalance, setLocalBalance] = useState('');
  const [localGo, setLocalGo] = useState('');

  useEffect(() => {
    if (isOpen) {
      setLocalBalance(settings.startingBalance.toString());
      setLocalGo(settings.passGoAmount.toString());
    }
  }, [isOpen, settings.startingBalance, settings.passGoAmount]);

  const commitChanges = () => {
    const newSettings = {
      startingBalance: parseMoneyInput(localBalance),
      passGoAmount: parseMoneyInput(localGo)
    };
    onUpdateSettings(newSettings);
    return newSettings;
  };

  const appendShorthand = (type: 'balance' | 'go', unit: 'K' | 'M') => {
    const current = type === 'balance' ? localBalance : localGo;
    const upper = current.toUpperCase();
    let newVal = '';
    if (!upper.endsWith('K') && !upper.endsWith('M')) {
      newVal = current + unit;
    } else {
      newVal = current.slice(0, -1) + unit;
    }

    if (type === 'balance') {
      setLocalBalance(newVal);
      onUpdateSettings({ ...settings, startingBalance: parseMoneyInput(newVal) });
    } else {
      setLocalGo(newVal);
      onUpdateSettings({ ...settings, passGoAmount: parseMoneyInput(newVal) });
    }
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center p-4 bg-black/80 backdrop-blur-md animate-in fade-in duration-200">
      <div className="bg-slate-900 border border-white/10 rounded-[2.5rem] w-full max-w-md shadow-2xl overflow-hidden backdrop-blur-2xl flex flex-col max-h-[90vh]">

        <div className="p-6 border-b border-white/10 flex justify-between items-center bg-white/5 flex-shrink-0">
          <div className="flex items-center gap-3">
            <span className="text-2xl">⚙️</span>
            <h3 className="text-xl font-black text-white tracking-tight">Game Settings</h3>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-white transition-colors">
            <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div className="p-8 space-y-8 overflow-y-auto custom-scrollbar">

          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <label className="text-xs font-black text-cyan-400 uppercase tracking-[0.2em]">Manage Roster</label>
              <span className="text-[10px] font-bold text-slate-500">{playerCount}/6 Players</span>
            </div>
            <Button 
              onClick={onAddPlayer} 
              disabled={playerCount >= 6}
              className={`rounded-2xl py-4 font-black w-full border-2 transition-all ${
                playerCount >= 6 ? 'bg-white/5 border-white/5 text-slate-600' : 'bg-white/5 border-cyan-500/30 text-cyan-400 hover:bg-cyan-500/10'
              }`}
            >
              {playerCount >= 6 ? 'Roster Full' : '+ Add Late Player'}
            </Button>
          </div>

          <div className="space-y-4">
            <label className="text-xs font-black text-cyan-400 uppercase tracking-[0.2em]">Active Currency</label>
            <div className="grid grid-cols-4 gap-2">
              {CURRENCIES.map((c) => (
                <button 
                  key={c.name} 
                  onClick={() => onUpdateCurrency(c)} 
                  className={`flex flex-col items-center justify-center p-3 rounded-2xl border-2 transition-all ${
                    currency.name === c.name ? 'bg-cyan-500 border-cyan-400 text-white shadow-lg' : 'bg-white/5 border-white/5 text-slate-400'
                  }`}
                >
                  <span className="text-lg font-black">{c.symbol}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="space-y-6">
            <div className="space-y-3">
              <label className="text-xs font-black text-cyan-400 uppercase tracking-[0.2em]">Initial Balance</label>
              <div className="relative">
                <input 
                  type="text" 
                  inputMode="numeric"
                  value={localBalance}
                  onChange={(e) => setLocalBalance(e.target.value)}
                  onBlur={commitChanges}
                  className="w-full bg-black/40 border-2 border-white/10 rounded-2xl py-4 pl-6 pr-16 text-white font-mono focus:ring-4 focus:ring-cyan-500/20 outline-none transition-all uppercase"
                />
                <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                  <button type="button" onClick={() => appendShorthand('balance', 'K')} className="bg-white/10 px-2 py-1 rounded text-[10px] font-black hover:bg-white/20">K</button>
                  <button type="button" onClick={() => appendShorthand('balance', 'M')} className="bg-white/10 px-2 py-1 rounded text-[10px] font-black hover:bg-white/20">M</button>
                </div>
                <div className="absolute left-6 -bottom-5 text-[10px] font-black text-cyan-400 opacity-60">
                  Resolved: {formatFullAmount(parseMoneyInput(localBalance), currency)}
                </div>
              </div>
            </div>

            <div className="space-y-3 pt-2">
              <label className="text-xs font-black text-cyan-400 uppercase tracking-[0.2em]">Pass GO Amount</label>
              <div className="relative">
                <input 
                  type="text" 
                  inputMode="numeric"
                  value={localGo}
                  onChange={(e) => setLocalGo(e.target.value)}
                  onBlur={commitChanges}
                  className="w-full bg-black/40 border-2 border-white/10 rounded-2xl py-4 pl-6 pr-16 text-white font-mono focus:ring-4 focus:ring-cyan-500/20 outline-none transition-all uppercase"
                />
                <div className="absolute right-2 top-1/2 -translate-y-1/2 flex gap-1">
                  <button type="button" onClick={() => appendShorthand('go', 'K')} className="bg-white/10 px-2 py-1 rounded text-[10px] font-black hover:bg-white/20">K</button>
                  <button type="button" onClick={() => appendShorthand('go', 'M')} className="bg-white/10 px-2 py-1 rounded text-[10px] font-black hover:bg-white/20">M</button>
                </div>
                <div className="absolute left-6 -bottom-5 text-[10px] font-black text-cyan-400 opacity-60">
                  Resolved: {formatFullAmount(parseMoneyInput(localGo), currency)}
                </div>
              </div>
            </div>
          </div>

          <div className="pt-6">
            <Button variant="ghost" fullWidth onClick={onClose} className="rounded-2xl py-3 text-slate-400 hover:text-white">
              Back to Game
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SettingsModal;

import React, { useState, useEffect } from 'react';
import { Player, TransactionType, Currency } from '../types';
import Button from './Button';

interface TransactionModalProps {
  isOpen: boolean;
  initialFromId?: string;
  initialToId?: string;
  onClose: () => void;
  players: Player[];
  currency: Currency;
  passGoAmount: number;
  onTransaction: (type: TransactionType, fromId: string, toId: string, amount: number) => void;
}

const TransactionModal: React.FC<TransactionModalProps> = ({ 
  isOpen, 
  initialFromId, 
  initialToId, 
  onClose, 
  players, 
  currency,
  passGoAmount,
  onTransaction 
}) => {
  const [activeTab, setActiveTab] = useState<'transfer' | 'bank' | 'go'>('transfer');

  const [fromId, setFromId] = useState<string>('');
  const [toId, setToId] = useState<string>('');
  const [amount, setAmount] = useState<string>(''); 

  const [bankPlayerId, setBankPlayerId] = useState<string>('');
  const [bankAction, setBankAction] = useState<'pay' | 'receive'>('pay');

  useEffect(() => {
    if (isOpen) {
      if (initialFromId === 'BANK' && initialToId && initialToId !== 'BANK') {
        setActiveTab('bank');
        setBankAction('receive');
        setBankPlayerId(initialToId);
      } else if (initialToId === 'BANK' && initialFromId && initialFromId !== 'BANK') {
        setActiveTab('bank');
        setBankAction('pay');
        setBankPlayerId(initialFromId);
      } else if (initialFromId && initialToId && initialFromId !== 'BANK' && initialToId !== 'BANK') {
        setActiveTab('transfer');
        setFromId(initialFromId);
        setToId(initialToId);
      } else {
        setActiveTab('transfer');
        setFromId('');
        setToId('');
        setBankPlayerId('');
      }
      setAmount('');
    }
  }, [isOpen, initialFromId, initialToId]);

  if (!isOpen) return null;

  const parseValue = (val: string): number => {
    let str = val.toLowerCase().replace(/,/g, '').trim();
    if (!str) return 0;

    let multiplier = 1;
    if (str.endsWith('m')) {
      multiplier = 1000000;
      str = str.slice(0, -1);
    } else if (str.endsWith('k')) {
      multiplier = 1000;
      str = str.slice(0, -1);
    }

    const num = parseFloat(str);
    return isNaN(num) ? 0 : Math.floor(num * multiplier);
  };

  const handleTransfer = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = parseValue(amount);
    if (fromId && toId && numericAmount > 0 && fromId !== toId) {
      onTransaction(TransactionType.TRANSFER, fromId, toId, numericAmount);
      onClose();
    }
  };

  const handleBankTransaction = (e: React.FormEvent) => {
    e.preventDefault();
    const numericAmount = parseValue(amount);
    if (bankPlayerId && numericAmount > 0) {
      if (bankAction === 'pay') {
        onTransaction(TransactionType.BANK_DEPOSIT, bankPlayerId, 'BANK', numericAmount);
      } else {
        onTransaction(TransactionType.BANK_WITHDRAWAL, 'BANK', bankPlayerId, numericAmount);
      }
      onClose();
    }
  };

  const handlePassGo = () => {
    if (bankPlayerId) {
      onTransaction(TransactionType.PASS_GO, 'BANK', bankPlayerId, passGoAmount);
      onClose();
    }
  };

  const handleAmountChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const val = e.target.value;
    // Allow numeric, dots, commas, and k/m shorthand
    if (/^[0-9.,kmKM]*$/.test(val)) {
      setAmount(val);
    }
  };

  const formatMoneyDisplay = (amount: number) => {
    const displayVal = (amount ?? 0).toLocaleString('en-US');
    return currency.position === 'prefix' ? `${currency.symbol}${displayVal}` : `${displayVal}${currency.symbol}`;
  };

  const formatFullAmountPreview = (amount: number) => {
    const displayVal = (amount ?? 0).toLocaleString('en-US');
    return currency.position === 'prefix' 
      ? `${currency.symbol}${displayVal}` 
      : `${displayVal}${currency.symbol}`;
  };

  const appendUnit = (unit: 'K' | 'M') => {
    const cleanAmount = amount.toUpperCase();
    if (!cleanAmount.endsWith('K') && !cleanAmount.endsWith('M')) {
      setAmount(amount + unit);
    } else {
      setAmount(amount.slice(0, -1) + unit);
    }
  };

  const renderAmountInput = (value: string, setter: (v: string) => void) => {
    const numericValue = parseValue(value);

    return (
      <div className="space-y-4">
        <label className="block text-xs font-black text-blue-300 uppercase tracking-widest">Amount</label>
        <div className="relative group">
          <input 
            type="text" 
            inputMode="numeric"
            value={value} 
            onChange={handleAmountChange}
            className="w-full bg-black/40 border-2 border-white/10 text-white rounded-[1.5rem] p-6 text-5xl font-mono text-center focus:ring-4 focus:ring-cyan-500/20 focus:border-cyan-500/50 outline-none transition-all shadow-inner uppercase placeholder:opacity-20" 
            placeholder="0" 
            required 
          />
          <div className="absolute right-3 top-1/2 -translate-y-1/2 flex flex-col gap-2">
            <button 
              type="button" 
              onClick={() => appendUnit('K')} 
              className="bg-cyan-600 hover:bg-cyan-500 text-white font-black px-4 py-2 rounded-xl text-sm shadow-lg transition-transform active:scale-90 border border-white/10"
            >
              K
            </button>
            <button 
              type="button" 
              onClick={() => appendUnit('M')} 
              className="bg-purple-600 hover:bg-purple-500 text-white font-black px-4 py-2 rounded-xl text-sm shadow-lg transition-transform active:scale-90 border border-white/10"
            >
              M
            </button>
          </div>
        </div>

        {numericValue > 0 && (
