import React, { useState, useEffect, useRef } from 'react';
import { Player, TransactionType } from '../types';
import { parseTransactionCommand } from '../services/geminiService';
import Button from './Button';

interface CommandCenterProps {
  isOpen: boolean;
  onClose: () => void;
  players: Player[];
  onTransaction: (type: TransactionType, fromId: string, toId: string, amount: number) => void;
}

const CommandCenter: React.FC<CommandCenterProps> = ({ isOpen, onClose, players, onTransaction }) => {
  const [input, setInput] = useState('');
  const [isListening, setIsListening] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const recognitionRef = useRef<any>(null);

  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;
      recognitionRef.current.lang = 'en-US';

      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        setInput(transcript);
        setIsListening(false);
      };

      recognitionRef.current.onerror = (event: any) => {
        console.error('Speech recognition error', event.error);
        setIsListening(false);
        setError("Audio capture failed.");
      };

      recognitionRef.current.onend = () => {
        setIsListening(false);
      };
    }
  }, []);

  const toggleListening = () => {
    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
    } else {
      setError(null);
      setInput('');
      try {
        recognitionRef.current?.start();
        setIsListening(true);
      } catch (e) {
        setError("Microphone unavailable.");
      }
    }
  };

  const handleProcess = async () => {
    if (!input.trim() || isProcessing) return;
    setIsProcessing(true);
    setError(null);

    const result = await parseTransactionCommand(input, players);

    if (result) {
      onTransaction(result.type, result.fromId, result.toId, result.amount);
      onClose();
      setInput('');
    } else {
      setError("Instruction unclear. Use format: '[Name] pays [Name] [Amount]'.");
    }
    setIsProcessing(false);
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-[300] flex items-end sm:items-center justify-center p-4 bg-black/90 backdrop-blur-2xl animate-in fade-in duration-300">
      <div className="bg-slate-900/90 border-2 border-cyan-500/20 rounded-[3rem] w-full max-w-lg shadow-[0_0_100px_rgba(8,145,178,0.2)] overflow-hidden animate-in slide-in-from-bottom-10 relative">

        {/* Matrix Rain Decoration (Subtle) */}
        <div className="absolute inset-0 opacity-5 pointer-events-none overflow-hidden">
          <div className="text-cyan-400 font-mono-tech text-[10px] break-all leading-none animate-[matrix_20s_linear_infinite]">
            0101100101101010110101011010101010110101011010101101010110101010101101010110101011010101101010101011010101101010110101011010101010110101011010101101010110101010101
          </div>
        </div>

        <div className="p-10 space-y-10 relative z-10">
          <div className="flex justify-between items-center">
            <div className="flex flex-col">
              <div className="flex items-center gap-3">
                <div className="w-3 h-3 rounded-full bg-cyan-500 pulse-cyan flex-shrink-0"></div>
                <h3 className="text-2xl font-black text-white tracking-tight uppercase italic leading-none">Neural Command</h3>
              </div>
              <span className="text-[10px] font-black text-cyan-400/50 uppercase tracking-[0.5em] mt-2 ml-6">v2.5 Link Active</span>
            </div>
            <button onClick={onClose} className="text-slate-500 hover:text-white transition-all p-3 hover:bg-white/5 rounded-full active:scale-90">
              <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M6 18L18 6M6 6l12 12" /></svg>
            </button>
          </div>

          <div className="space-y-6">
            <div className="relative group">
              <textarea
                value={input}
                onChange={(e) => setInput(e.target.value)}
                placeholder="Ex: 'Collect 200 for Bob' or 'Alice pays Bob 1500'"
                className="w-full bg-black/60 border-2 border-white/10 text-cyan-400 rounded-[2rem] p-8 text-2xl min-h-[160px] focus:ring-4 focus:ring-cyan-500/10 focus:border-cyan-500/50 outline-none transition-all resize-none placeholder:text-slate-800 font-mono-tech shadow-inner"
              />

              <button 
                onClick={toggleListening}
                className={`absolute right-6 bottom-6 p-5 rounded-[1.5rem] transition-all duration-300 ${
                  isListening 
                    ? 'bg-red-600 scale-110 shadow-[0_0_30px_rgba(220,38,38,0.6)]' 
                    : 'bg-cyan-600 hover:bg-cyan-500 text-white shadow-[0_0_20px_rgba(8,145,178,0.3)]'
                }`}
              >
                <svg className="w-7 h-7" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  {isListening ? (
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z M9 10a1 1 0 011-1h4a1 1 0 011 1v4a1 1 0 01-1 1h-4a1 1 0 01-1-1v-4z" />
                  ) : (
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={4} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
                  )}
                </svg>
              </button>
            </div>

            {error && (
              <div className="bg-red-500/10 border-2 border-red-500/20 rounded-2xl p-5 text-red-500 text-xs font-black uppercase tracking-widest animate-in slide-in-from-top-2 flex items-center gap-3">
                <span className="text-xl">⚠️</span> {error}
              </div>
            )}
          </div>

          <div className="flex gap-4">
            <Button 
              variant="ghost" 
              fullWidth 
              onClick={onClose} 
              className="rounded-[1.5rem] py-5 font-black uppercase tracking-widest border border-white/5"
            >
              Abort
            </Button>
            <Button 
              fullWidth 
              onClick={handleProcess} 
              disabled={!input.trim() || isProcessing}
              className="bg-gradient-to-r from-cyan-600 via-blue-600 to-indigo-600 rounded-[1.5rem] py-5 text-xl font-black uppercase tracking-[0.2em] shadow-2xl disabled:opacity-30 relative overflow-hidden group"
            >
              {isProcessing && <div className="absolute inset-0 bg-white/20 animate-pulse"></div>}
