                {isProcessing ? (
                  <>
                    <div className="w-5 h-5 border-[3px] border-white/30 border-t-white rounded-full animate-spin"></div>
                    <span>Decoding...</span>
                  </>
                ) : (
                  <>
                    <span>Execute</span> 
                    <span className="group-hover:translate-x-1 transition-transform">⚡</span>
                  </>
                )}
